UpdateBigCheckMark proc near ; CODE XREF: cseg_116E8↑p
                    ; SquadMenuSavePlayerPositions+A8↑p
push    D0
mov     D0, 1       ; big check/uncheck sprite on top
call    CalcMenuEntryAddress
pop     D0
mov     esi, A0
mov     [esi+MenuEntry.isInvisible], 1
mov     ax, teamSkillDiffAfterChange
or      ax, ax
jns     short @@out
mov     esi, A0
mov     ax, [esi+MenuEntry.stringFlags]
mov     word ptr D1, ax
and     word ptr D1, 0DFFFh ; clear blink flag
mov     ax, word ptr D1
mov     esi, A0
mov     [esi+MenuEntry.stringFlags], ax
mov     ax, oldPlayerSkill
mov     word ptr D1, ax
mov     ax, newPlayerSkill
cmp     word ptr D1, ax
ja      short @@good_change
mov     ax, newPlayerSkill
cmp     word ptr D1, ax
jb      short @@bad_change

@@out:              ; CODE XREF: UpdateBigCheckMark+30↑j
retn                ; skill is equal
; ---------------------------------------------------------------------------

@@bad_change:       ; CODE XREF: UpdateBigCheckMark+83↑j
mov     esi, A0
mov     word ptr [esi+MenuEntry.fg], SPR_NOT_CHECK_BIG
jmp     short cseg_13A1F
; ---------------------------------------------------------------------------

@@good_change:      ; CODE XREF: UpdateBigCheckMark+74↑j
mov     esi, A0
mov     word ptr [esi+MenuEntry.fg], SPR_CHECK_BIG

cseg_13A1F:         ; CODE XREF: UpdateBigCheckMark+92↑j
