mov     ax, [esi+MenuEntry.stringFlags]
mov     word ptr D1, ax
or      word ptr D1, 2000h ; set blink flag
mov     ax, word ptr D1
mov     esi, A0
mov     [esi+MenuEntry.stringFlags], ax
mov     esi, A0
mov     [esi+MenuEntry.isInvisible], 0
retn
UpdateBigCheckMark endp


