int     21h         ; DOS - GET CURRENT TIME
                    ; Return: CH = hours, CL = minutes, DH = seconds
                    ; DL = hundredths of seconds
xor     ax, ax
mov     ax, dx
mul     al          ; simply square hundredths (seconds get overwritten)
xor     al, cl
and     al, 0FFh
mov     byte ptr randomSeed, al
mov     useIndividualPlayerSkinColor, 1
