and     word ptr D0, 0FFh
jnz     short @@seed_non_zero
add     randXorIndex, 1
mov     al, randXorIndex
mov     byte ptr D1, al
and     word ptr D1, 0FFh
mov     esi, A0
movzx   ebx, word ptr D1
mov     al, [esi+ebx]
mov     randXorKey, al

@@seed_non_zero:    ; CODE XREF: Rand+29↑j
mov     esi, A0
movzx   ebx, word ptr D0
mov     al, [esi+ebx]
mov     byte ptr D0, al
mov     al, randXorKey
mov     byte ptr D1, al
mov     al, byte ptr D1
xor     byte ptr D0, al
add     seed, 1
pop     A0
pop     D1
retn
Rand endp


