; [ebp safe]

MainKeysCheck proc near ; CODE XREF: GameLoop+3A5↑p GameLoop+411↑p ...
movzx   ax, convertedKey
mov     word ptr D0, ax
mov     ax, lastKey
or      ax, ax
jz      @@out
