mov     ax, normalReplayRunning
or      ax, ax
jnz     @@test_if_game_paused
cmp     word ptr D0, 'R'
jnz     short @@not_replay
mov     ax, fadeState ; replay
or      ax, ax
jz      @@out
mov     ax, g_inSubstitutesMenu
or      ax, ax
jnz     @@out
cmp     gameState, ST_RESULT_AFTER_THE_GAME
jz      @@out
cmp     gameState, ST_RESULT_ON_HALFTIME
jz      @@out
mov     instantReplayFlag, 1
mov     ax, replayState
or      ax, ax
jnz     @@out
mov     userRequestedReplay, 1
jmp     @@out
