mov     esi, A0
cmp     [esi+TeamGeneralInfo.playerNumber], 2
jz      short @@test_player2_fire
mov     esi, A0
cmp     [esi+TeamGeneralInfo.playerCoachNumber], 1
jz      short @@test_player1_fire
mov     esi, A0
cmp     [esi+TeamGeneralInfo.playerCoachNumber], 2
jz      short @@test_player2_fire
jmp     short @@computer_team
