; =============== S U B R O U T I N E =======================================

; in:
;      ebx -> sample table in form of array of:
;              dword - offset in linAdr2_6Mb
;              dword - sample size
;      cx   - last played sample index
;      D1   - max sample index (bit-mask)
;
; out:
;      ax   - index of played sample

PlayCommentarySample proc near
                    ; CODE XREF: PlayGoodJumpHeaderComment+31↑p
                    ; PlayPenaltyGoalComment+2A↑p ...
cmp     g_trainingGame, 0
jnz     @@out       ; don't play commentary while training
cmp     g_soundOff, 1
jz      @@out
cmp     commentaryOff, -1
jz      short @@out
nop
nop
nop
nop
cmp     g_muteCommentary, -1
jz      short @@out
push    D1
push    ebx
call    Rand
pop     ebx
pop     D1
mov     ax, word ptr D1
and     word ptr D0, ax ; normalize range
movzx   eax, word ptr D0
cmp     cx, ax      ; make sure not to play same sample twice in a row
jnz     short @@not_the_same_sample
inc     word ptr D0 ; next sample
mov     ax, word ptr D1
and     word ptr D0, ax
movzx   eax, word ptr D0

@@not_the_same_sample: ; CODE XREF: PlayCommentarySample+5E↑j
push    eax
shl     eax, 3
mov     edx, linAdr2_6Mb
add     edx, [ebx+eax] ; edx -> sample raw data
mov     eax, [ebx+eax+4] ; eax = size
mov     ebx, 127
mov     ecx, 1
call    PlayCommentarySample22Khz
mov     commentarySampleHandle, eax
pop     eax

@@out:              ; CODE XREF: PlayCommentarySample+8↑j
                    ; PlayCommentarySample+16↑j ...
retn
PlayCommentarySample endp


