push    A0
push    D0
push    D1
mov     ebx, offset redCardSamplesTable

PlayCardSample:     ; CODE XREF: PlayYellowCardSample+1D↑j
cmp     g_trainingGame, 0
jnz     short @@out
cmp     g_muteCommentary, -1
jz      short @@out
cmp     commentaryOff, -1
jz      short @@out
cmp     g_soundOff, 1
jz      short @@out
push    ebx
call    Rand
pop     ebx
movzx   eax, word ptr D0
and     eax, 0Fh    ; eax = [0..15]
mov     eax, [ebx+eax*4]
mov     A0, eax
mov     eax, linAdr120k
mov     A1, eax
call    LoadFile
mov     edx, linAdr120k
mov     eax, D1
mov     ebx, 127
mov     ecx, 1
call    PlayCommentarySample22Khz
mov     commentarySampleHandle, eax

@@out:              ; CODE XREF: PlayRedCardSample+25↑j
                    ; PlayRedCardSample+2F↑j ...
pop     D1
pop     D0
pop     A0
pop     A1
retn
PlayRedCardSample endp


