LoadAndPlayEndGameComment proc near ; CODE XREF: GameOver+D0↓p
cmp     g_memAllOk, 2
jz      short @@out
nop
nop
nop
nop
mov     ax, team1GoalsDigit2
cmp     team2GoalsDigit2, ax
jz      short @@draw
jl      short @@home_win
mov     eax, 1
jmp     short @@play_sample
; ---------------------------------------------------------------------------

@@draw:             ; CODE XREF: LoadAndPlayEndGameComment+1B↑j
mov     eax, 2
jmp     short @@play_sample
; ---------------------------------------------------------------------------

@@home_win:         ; CODE XREF: LoadAndPlayEndGameComment+1D↑j
mov     eax, 0

@@play_sample:      ; CODE XREF: LoadAndPlayEndGameComment+24↑j
                    ; LoadAndPlayEndGameComment+2B↑j
call    LoadAndPlayEndGameCrowdSample
mov     ax, statsTeam1Goals
sub     ax, statsTeam2Goals
jns     short @@goal_difference_positive
neg     ax

@@goal_difference_positive: ; CODE XREF: LoadAndPlayEndGameComment+44↑j
cmp     ax, 3
jge     short @@complete_rout
jz      short @@draw_comment ; <-- bug, this jump is never taken
mov     dx, statsTeam1Goals
add     dx, statsTeam2Goals
cmp     dx, 4
jge     short @@4_or_more_goals
jmp     short @@out
; ---------------------------------------------------------------------------

@@draw_comment:     ; CODE XREF: LoadAndPlayEndGameComment+4F↑j
call    PlayDrawComment
jmp     short @@out
; ---------------------------------------------------------------------------

@@complete_rout:    ; CODE XREF: LoadAndPlayEndGameComment+4D↑j
call    PlayItsBeenACompleteRoutComment
jmp     short @@out
; ---------------------------------------------------------------------------

@@4_or_more_goals:  ; CODE XREF: LoadAndPlayEndGameComment+63↑j
call    PlaySensationalGameComment

@@out:              ; CODE XREF: LoadAndPlayEndGameComment+8↑j
                    ; LoadAndPlayEndGameComment+65↑j ...
retn
LoadAndPlayEndGameComment endp


