PlayCrowdChants proc near
                    ; CODE XREF: PlayEnqueuedSamples:@@play_chants↑p
cmp     g_soundOff, 1
jz      @@out
mov     ax, g_trainingGame
or      ax, ax
jnz     @@out
mov     ax, g_crowdChantsOn
or      ax, ax
jz      @@out
mov     ax, fadeInChantTimer
or      ax, ax
jnz     @@fade_in_chant
mov     ax, nextChantTimer
or      ax, ax
jnz     @@decrease_chant_timer_and_leave
mov     ax, fadeOutChantTimer
or      ax, ax
jnz     @@fade_out_chant
call    Rand
cmp     word ptr D0, 128
jb      short @@reschedule_next_chant
call    Rand        ; 50% chance to not play anything but reschedule chant again
shl     word ptr D0, 1 ; next chant: after 0-512 ticks
mov     ax, word ptr D0
mov     nextChantTimer, ax
jmp     @@out
; ---------------------------------------------------------------------------

@@reschedule_next_chant: ; CODE XREF: PlayCrowdChants+67↑j
cmp     playCrowdChantsFunction, -1
jz      short @@generate_random_chant_index
call    Rand        ; we already have chant function, 50% chance to just play it again
cmp     word ptr D0, 128
jb      short @@play_crowd_chants

@@generate_random_chant_index: ; CODE XREF: PlayCrowdChants+8D↑j
call    Rand
and     word ptr D0, 3
cmp     itsAnInterestingGame, -1
jnz     short @@select_chant_to_play
mov     word ptr D0, 2 ; select most dynamic chant (or result chant)

@@select_chant_to_play: ; CODE XREF: PlayCrowdChants+B4↑j
mov     A0, offset playIntroChantSampleOffset
mov     esi, A0
movzx   ebx, word ptr D0
shl     ebx, 2
mov     eax, [esi+ebx]
mov     D1, eax
mov     eax, D1
mov     playCrowdChantsFunction, eax

@@play_crowd_chants: ; CODE XREF: PlayCrowdChants+9D↑j
mov     word ptr D0, 2
call    playCrowdChantsFunction
mov     fadeInChantTimer, 128
call    Rand
shl     word ptr D0, 1
add     word ptr D0, 500 ; next chant: after 500-1012 ticks
mov     ax, word ptr D0
mov     nextChantTimer, ax
mov     fadeOutChantTimer, 128
jmp     @@out
; ---------------------------------------------------------------------------

@@decrease_chant_timer_and_leave: ; CODE XREF: PlayCrowdChants+44↑j
sub     nextChantTimer, 1
retn
; ---------------------------------------------------------------------------
sub     nextChantTimer, 1
retn
; ---------------------------------------------------------------------------

@@fade_out_chant:   ; CODE XREF: PlayCrowdChants+53↑j
sub     fadeOutChantTimer, 1
mov     ax, fadeOutChantTimer
mov     word ptr D1, ax
shr     word ptr D1, 1 ; new volume = fadeOutChantTimer / 2
mov     word ptr D0, 2
mov     ax, word ptr D1
mov     crowdChantVolume, ax
call    SetVolumeOrStopChants
retn
; ---------------------------------------------------------------------------

@@fade_in_chant:    ; CODE XREF: PlayCrowdChants+35↑j
sub     fadeInChantTimer, 1
mov     word ptr D1, 128
mov     ax, fadeInChantTimer
sub     word ptr D1, ax
shr     word ptr D1, 1 ; new volume = (128 - fadeInChatTimer) / 2
mov     word ptr D0, 2 ; D0 = 2
mov     ax, word ptr D1
mov     crowdChantVolume, ax ; volume fades in up to 64
or      ax, ax      ; don't stop it when it's zero
jz      short @@out2
call    SetVolumeOrStopChants

@@out2:             ; CODE XREF: PlayCrowdChants+1B7↑j
retn
; ---------------------------------------------------------------------------

@@out:              ; CODE XREF: PlayCrowdChants+8↑j
                    ; PlayCrowdChants+17↑j ...
retn
PlayCrowdChants endp


; =============== S U B R O U T I N E =======================================

; Main program initialization.

Initialization proc near ; CODE XREF: SWOS+6↑p
mov     ah, 0Fh
int     10h         ; VIDEO - get current video mode
mov     prevVideoMode, al ; save video mode prior to game
mov     errorCheckWord, 0
mov     skipIntro, 0 ; clear CPU variable
mov     edx, offset aSensibleWorldOfSoccerV2_0 ; "Sensible World Of Soccer V2.0 \r\n$"
mov     ah, 9       ; write copyright message
int     21h         ; DOS - print string
call    DetectCPU   ; check the processor
