; ---------------------------------------------------------------------------

@@color_greater:    ; CODE XREF: FadeOut+16↑j
dec     al
jmp     short @@store_color
; ---------------------------------------------------------------------------

@@color_equal:      ; CODE XREF: FadeOut+14↑j
inc     dx          ; color match

@@store_color:      ; CODE XREF: FadeOut+1A↑j FadeOut+1E↑j
