inc     esi         ; go to next color
inc     ebx
loop    @@equalize_colors_loop
pop     ebx
push    dx
call    WaitRetrace
mov     esi, offset g_fadePalette
call    SetPalette
pop     dx
cmp     dx, 768     ; dx is the number of entries which are equal; when dx is 768,
                    ; that means that all the colors have been equalized
jnz     short FadeOut
mov     fadeState, 0
retn
