VerifyJoypadControls proc near
cmp     g_inputControls, 1
jz      short @@out
push    small [g_numLoopsJoy1]
push    small [g_numLoopsJoy2]
mov     g_numLoopsJoy1, -1
mov     g_numLoopsJoy2, -1
call    ReadGamePort
pop     small [g_numLoopsJoy2]
pop     small [g_numLoopsJoy1]
cmp     g_joy1X, 65535
jz      short @@keyboard_only
cmp     g_joy2X, 65535
jz      short @@keyboard_and_joypad

@@out:              ; CODE XREF: VerifyJoypadControls+8↑j
retn
; ---------------------------------------------------------------------------

@@keyboard_only:    ; CODE XREF: VerifyJoypadControls+45↑j
