retn
; ---------------------------------------------------------------------------

@@keyboard_and_joypad: ; CODE XREF: VerifyJoypadControls+4F↑j
mov     g_inputControls, 3
retn
VerifyJoypadControls endp


; =============== S U B R O U T I N E =======================================


ReadGamePort proc near ; CODE XREF: ReplayExitMenuAfterFriendly+CE↑p
                    ; VerifyJoypadControls+2A↑p ...
cmp     g_inputControls, KEYBOARD_ONLY ; if keyboard only, exit immediately
jz      short @@exit
xor     esi, esi
xor     edi, edi
xor     ebx, ebx
xor     ebp, ebp
xor     ecx, ecx
mov     cx, g_numLoopsJoy2
cmp     g_inputControls, TWO_JOYPADS
jz      short @@joy_loop
mov     cx, g_numLoopsJoy1

@@joy_loop:         ; CODE XREF: ReadGamePort+23↑j
cli
mov     dx, 201h
out     dx, al      ; Game I/O port
                    ; bits 0-3: Coordinates (resistive, time-dependent inputs)
                    ; bits 4-7: Buttons/Triggers (digital inputs)
jmp     short $+2
jmp     short $+2

@@values_loop:      ; CODE XREF: ReadGamePort+4F↓j
in      al, dx      ; Game I/O port
                    ; bits 0-3: Coordinates (resistive, time-dependent inputs)
                    ; bits 4-7: Buttons/Triggers (digital inputs)
shr     al, 1
adc     bx, 0
shr     al, 1
adc     bp, 0
shr     al, 1
adc     di, 0
shr     al, 1
adc     si, 0
loop    @@values_loop
sti
mov     g_joy1X, bx
mov     g_joy1Y, bp
mov     g_joy2X, di
mov     g_joy2Y, si

@@exit:             ; CODE XREF: ReadGamePort+8↑j
retn
ReadGamePort endp

