; =============== S U B R O U T I N E =======================================

; out:
;      pl1Left
;      pl1Right
;      pl1Up
;      pl1Down
;      pl1Fire
;      pl1SecondaryFire
;      pl1UpRight
;      pl1DownRight
;      pl1DownLeft
;      pl1UpLeft
;      pl1FireCounter
;
; In the form 0 = on, -1 = off.
;
; pl1Direction
;     0 - up
;     1 - up right
;     2 - right
;     3 - down right
;     4 - down
;     5 - down left
;     6 - left
;     7 - up left
;    -1 - none of it
;
; destroys: ax, ebx, cl, dx
; [ebp safe]

Player1StatusProc proc near ; CODE XREF: GameLoop+3AA↑p
                    ; PlayInstantReplayLoop:@@computer_team↑p ...
cmp     g_inputControls, KEYBOARD_ONLY
jnz     short @@check_joypad
mov     bx, keyboardControlFlags
mov     g_pl1ControlFlags, bx
jmp     short @@testing
; ---------------------------------------------------------------------------

@@check_joypad:     ; CODE XREF: Player1StatusProc+8↑j
call    Joy1SetStatus

@@testing:          ; CODE XREF: Player1StatusProc+18↑j
mov     ax, g_pl1ControlFlags
test    ax, 4
mov     pl1Left, 0
jz      short @@not_left
mov     pl1Left, -1

@@not_left:         ; CODE XREF: Player1StatusProc+30↑j
test    ax, 8
mov     pl1Right, 0
jz      short @@not_right
mov     pl1Right, -1

@@not_right:        ; CODE XREF: Player1StatusProc+44↑j
test    ax, 1
mov     pl1Up, 0
jz      short @@not_up
mov     pl1Up, -1

@@not_up:           ; CODE XREF: Player1StatusProc+58↑j
test    ax, 2
mov     pl1Down, 0
jz      short @@not_down
mov     pl1Down, -1

@@not_down:         ; CODE XREF: Player1StatusProc+6C↑j
test    ax, 32
mov     pl1Fire, 0
jz      short @@not_fire1
mov     pl1Fire, -1

@@not_fire1:        ; CODE XREF: Player1StatusProc+80↑j
test    ax, 64
mov     pl1SecondaryFire, 0
jz      short @@not_fire2
mov     pl1SecondaryFire, -1

@@not_fire2:        ; CODE XREF: Player1StatusProc+94↑j
mov     al, pl1Up
and     al, pl1Right
mov     pl1UpRight, al
mov     al, pl1Down
and     al, pl1Right
mov     pl1DownRight, al
mov     al, pl1Down
and     al, pl1Left
mov     pl1DownLeft, al
mov     al, pl1Up
and     al, pl1Left
mov     pl1UpLeft, al
mov     al, pl1LastFired
or      al, al
jz      short @@was_not_firing
mov     pl1ShortFire, 0
mov     al, pl1Fire
or      al, al
jz      short @@not_firing_now
mov     ax, pl1FireCounter
or      ax, ax
jz      short @@done_with_joy_fire
sub     pl1FireCounter, 1
jmp     short @@done_with_joy_fire
; ---------------------------------------------------------------------------

@@not_firing_now:   ; CODE XREF: Player1StatusProc+F4↑j
mov     pl1LastFired, 0
neg     pl1FireCounter
jmp     short @@done_with_joy_fire
; ---------------------------------------------------------------------------

@@was_not_firing:   ; CODE XREF: Player1StatusProc+E4↑j
mov     al, pl1Fire ; fire wasn't pressed in the previous cycle
mov     pl1ShortFire, 0
mov     pl1LastFired, 0
or      al, al
jz      short @@not_firing_now2
mov     pl1ShortFire, 1 ; but it is now
mov     pl1LastFired, 1

@@not_firing_now2:  ; CODE XREF: Player1StatusProc+130↑j
jz      short @@done_with_joy_fire
mov     pl1FireCounter, -1

@@done_with_joy_fire: ; CODE XREF: Player1StatusProc+FF↑j
                    ; Player1StatusProc+109↑j ...
mov     bx, 1
mov     al, pl1UpRight
or      al, al
jnz     short @@out
mov     bx, 3
mov     al, pl1DownRight
or      al, al
jnz     short @@out
mov     bx, 5
mov     al, pl1DownLeft
or      al, al
jnz     short @@out
mov     bx, 7
mov     al, pl1UpLeft
or      al, al
jnz     short @@out
mov     bx, 0
mov     al, pl1Up
or      al, al
jnz     short @@out
mov     bx, 2
mov     al, pl1Right
or      al, al
jnz     short @@out
mov     bx, 4
mov     al, pl1Down
or      al, al
jnz     short @@out
mov     bx, 6
mov     al, pl1Left
or      al, al
jnz     short @@out
mov     bx, -1

@@out:              ; CODE XREF: Player1StatusProc+156↑j
                    ; Player1StatusProc+163↑j ...
mov     pl1Direction, bx
retn
Player1StatusProc endp


