test    ax, 1000000b
mov     pl2SecondaryFire, 0
jz      short cseg_1A033
mov     pl2SecondaryFire, -1

cseg_1A033:         ; CODE XREF: Player2StatusProc+94↑j
mov     al, pl2Up
