mov     pl2DownRight, al
mov     al, pl2Down
and     al, pl2Left
mov     pl2DownLeft, al
mov     al, pl2Up
and     al, pl2Left
mov     pl2UpLeft, al
mov     al, pl2LastFired
or      al, al
jz      short @@was_not_firing
mov     pl2ShortFire, 0
