jmp     short @@done_fire_check
; ---------------------------------------------------------------------------

@@was_not_firing:   ; CODE XREF: Player2StatusProc+E4↑j
mov     al, pl2Fire
mov     pl2ShortFire, 0
mov     pl2LastFired, 0
or      al, al
jz      short @@not_firing_2
mov     pl2ShortFire, 1
mov     pl2LastFired, 1

@@not_firing_2:     ; CODE XREF: Player2StatusProc+130↑j
jz      short @@done_fire_check
mov     pl2FireCounter, -1

@@done_fire_check:  ; CODE XREF: Player2StatusProc+FF↑j
                    ; Player2StatusProc+109↑j ...
mov     bx, 1
mov     al, pl2UpRight
or      al, al
jnz     short @@out
mov     bx, 3
mov     al, pl2DownRight
or      al, al
jnz     short @@out
mov     bx, 5
mov     al, pl2DownLeft
or      al, al
jnz     short @@out
mov     bx, 7
mov     al, pl2UpLeft
or      al, al
jnz     short @@out
mov     bx, 0
mov     al, pl2Up
or      al, al
jnz     short @@out
mov     bx, 2
mov     al, pl2Right
or      al, al
jnz     short @@out
mov     bx, 4
mov     al, pl2Down
or      al, al
jnz     short @@out
mov     bx, 6
mov     al, pl2Left
or      al, al
jnz     short @@out
mov     bx, -1

@@out:              ; CODE XREF: Player2StatusProc+156↑j
                    ; Player2StatusProc+163↑j ...
