; =============== S U B R O U T I N E =======================================

; in:  A0 -> filename
;      A1 -> buffer
;      D1 = buffer size
;
; out: D0 = 0 - success
;           1 - failure
;      zero flag set - all OK
;        -||-  clear - error
;
; Create file and write buffer content into it.

WriteFile proc near ; CODE XREF: SaveCareerFile+62↓p
                    ; SavePresetCompetitionFile+5C↓p ...
pushf
pusha
mov     edx, A0
mov     ah, 3Ch
mov     ecx, 0
int     21h         ; DOS - 2+ - CREATE A FILE WITH HANDLE (CREAT)
                    ; CX = attributes for file
                    ; DS:DX -> ASCIZ filename (may include drive and path)
jb      short @@file_error
mov     bx, ax
push    bx
mov     edx, A1
mov     ecx, D1
mov     ah, 40h
int     21h         ; DOS - 2+ - WRITE TO FILE WITH HANDLE
                    ; BX = file handle, CX = number of bytes to write, DS:DX -> buffer
jb      short @@file_error
pop     bx
mov     al, 0
mov     ah, 3Eh
int     21h         ; DOS - 2+ - CLOSE A FILE WITH HANDLE
                    ; BX = file handle
jb      short @@file_error
popa
popf
xor     ax, ax
mov     word ptr D0, ax
retn
; ---------------------------------------------------------------------------

@@file_error:       ; CODE XREF: WriteFile+11↑j WriteFile+28↑j ...
popa
popf
mov     word ptr D0, 1
mov     ax, 1
