ReadCommandLineParameters proc near
                    ; CODE XREF: Initialization:@@its_not_ega↑p
push    es
mov     ah, 62h
int     21h         ; DOS - 3+ - GET PSP ADDRESS
mov     es, ebx
mov     ebx, 80h    ; 80h - offset to number of bytes in command line
movzx   cx, byte ptr es:[ebx] ; cx holds number of bytes
jcxz    @@no_params
inc     ebx

@@param_scan:       ; CODE XREF: ReadCommandLineParameters:@@back_to_params↓j
cmp     byte ptr es:[ebx], 0Dh ; command line ends with carriage return
jz      short @@no_params
cmp     byte ptr es:[ebx], '/' ; if backslash, then parameter is following
jz      short @@got_parameter
inc     ebx

@@back_to_params:   ; CODE XREF: ReadCommandLineParameters+42↓j
                    ; ReadCommandLineParameters+4D↓j ...
loop    @@param_scan

@@no_params:        ; CODE XREF: ReadCommandLineParameters+11↑j
                    ; ReadCommandLineParameters+19↑j
pop     es          ; no parameters found, just return
retn
; ---------------------------------------------------------------------------

@@got_parameter:    ; CODE XREF: ReadCommandLineParameters+1F↑j
inc     ebx         ; do the comparision
mov     al, es:[ebx]
cmp     al, 'N'
jz      short @@N_switch
cmp     al, 'n'
jz      short @@N_switch
cmp     al, 'F'
jz      short @@full_version
cmp     al, 'f'
jz      short @@full_version
cmp     al, 'H'
jz      short @@half_version
cmp     al, 'h'
jz      short @@half_version
jmp     short @@back_to_params
; ---------------------------------------------------------------------------

@@N_switch:         ; CODE XREF: ReadCommandLineParameters+2C↑j
                    ; ReadCommandLineParameters+30↑j
mov     commentaryOff, -1
jmp     short @@back_to_params
; ---------------------------------------------------------------------------

@@full_version:     ; CODE XREF: ReadCommandLineParameters+34↑j
                    ; ReadCommandLineParameters+38↑j
mov     setupDatBuffer, 0
jmp     short @@back_to_params
; ---------------------------------------------------------------------------

@@half_version:     ; CODE XREF: ReadCommandLineParameters+3C↑j
                    ; ReadCommandLineParameters+40↑j
mov     setupDatBuffer, -1
jmp     short @@back_to_params
ReadCommandLineParameters endp


; =============== S U B R O U T I N E =======================================

; out:
;      al - processor code:
;           3 - 80386
;           4 - 80486
;      ah - if set, CPUID is supported
;
; Less than 3 means 80286 or older.

DetectCPU proc near ; CODE XREF: Initialization+24↑p
cli
pushf
pop     eax         ; put flags in eax
mov     ebx, eax    ; save it in ebx
xor     eax, 40000h ; invert bit 18 (alignment check, introduced with 80486)
push    eax
popf                ; set flags with bit 18 inverted
pushf
pop     eax         ; get updated flags in eax
push    ebx
popf                ; set flags to saved state
sti
xor     eax, ebx    ; if bits are different, 80386 it is
jnz     short @@check_for_80486
mov     ax, 3       ; 80386
jmp     short @@out
; ---------------------------------------------------------------------------

@@check_for_80486:  ; CODE XREF: DetectCPU+13↑j
cli
pushf
pop     eax         ; flags in eax
mov     ebx, eax    ; save original state in ebx
xor     eax, 200000h ; invert bit 21 - CPUID support
push    eax
popf                ; set flags with bit 21 inverted
pushf
pop     eax         ; current state in eax
push    ebx
popf                ; put back original state of flags
sti
xor     eax, ebx    ; if bit 21 is intact, this is 80486 surely
jnz     short @@CPUID_supported
mov     ax, 4       ; 80486, but without CPUID
jmp     short @@out
; ---------------------------------------------------------------------------

@@CPUID_supported:  ; CODE XREF: DetectCPU+2E↑j
push    ecx
push    edx
mov     eax, 1
cpuid
and     eax, 0F00h  ; leave only bits 8-11 - family type
shr     eax, 8      ; put them to low nibble
mov     ah, 1       ; set ah to indicate CPUID supported
pop     edx
pop     ecx

@@out:              ; CODE XREF: DetectCPU+19↑j DetectCPU+34↑j
retn
DetectCPU endp


