FindCdrom proc near ; CODE XREF: CDROM_InitCheck+18↑p
mov     ax, dosMemSegment
mov     rmRegs.rEs, ax
mov     rmRegs.rEbx, 0
mov     word ptr rmRegs.rEax, 150Dh
mov     ax, 300h    ; get CD-ROM drive letters
mov     bh, 0
mov     bl, 2Fh
mov     cx, 0
mov     edi, offset rmRegs
int     31h         ; DPMI Services   ax=func xxxxh
                    ; SIMULATE REAL MODE INTERRUPT
                    ; BL=interrupt number
                    ; CX=number of words to copy from protected mode to real mode stack
                    ; ES:DI / ES:EDI = selector:offset of real mode call structure
                    ; Return: CF set on error
                    ; CF clear if ok
mov     esi, dosMemLinAdr
mov     edi, offset cdromLettersBuffer
xor     ecx, ecx
mov     cx, numOfCdrom
rep movsb
mov     ebx, offset cdromLettersBuffer
mov     cx, numOfCdrom

@@next_cdrom:       ; CODE XREF: FindCdrom+B9↓j
push    ebx
push    ecx
push    ebx
mov     ax, dosMemSegment
mov     rmRegs.rEs, ax
mov     rmRegs.rEbx, 0
mov     word ptr rmRegs.rEax, 1504h ; CD-ROM - GET BIBLIOGRAPHIC DOC FILE NAME
xor     eax, eax
mov     al, [ebx]
mov     word ptr rmRegs.rEcx, ax
mov     ax, 300h
mov     bh, 0
mov     bl, 2Fh
mov     cx, 0
mov     edi, offset rmRegs
int     31h         ; DPMI Services   ax=func xxxxh
                    ; SIMULATE REAL MODE INTERRUPT
                    ; BL=interrupt number
                    ; CX=number of words to copy from protected mode to real mode stack
                    ; ES:DI / ES:EDI = selector:offset of real mode call structure
                    ; Return: CF set on error
                    ; CF clear if ok
pop     ebx
mov     ax, rmRegs.flags
test    ax, 1
jnz     short @@not_a_cdrom
mov     al, [ebx]
add     al, 'A'
mov     firstCdLetter, al
mov     edx, offset firstCdLetter
mov     al, 0
mov     ah, 3Dh
int     21h         ; DOS - 2+ - OPEN DISK FILE WITH HANDLE
                    ; DS:DX -> ASCIZ filename
                    ; AL = access mode
                    ; 0 - read
jnb     short @@cdrom_ok

@@not_a_cdrom:      ; CODE XREF: FindCdrom+9E↑j
pop     ecx
pop     ebx
inc     ebx
loop    @@next_cdrom
xor     ax, ax
retn
; ---------------------------------------------------------------------------

@@cdrom_ok:         ; CODE XREF: FindCdrom+B4↑j
pop     ecx
pop     ebx
mov     al, [ebx]
mov     byte ptr cdDriveLetter, al
mov     ax, 1
or      ax, ax
retn
FindCdrom endp


