; =============== S U B R O U T I N E =======================================

; out:
;      ax - device return status
;
; Bitfields for device request status:
; Bit(s)  Description
;  15     error
;  14-11  reserved
;  10     ??? set by DOS kernel on entry to some driver calls
;  9      busy
;  8      done (may be clear on return under European MS-DOS 4.0)
;  7-0    error code if bit 15 set
;
; Values for device driver error code:
;  00h    write-protect violation
;  01h    unknown unit
;  02h    drive not ready
;  03h    unknown command
;  04h    CRC error
;  05h    bad drive request structure length
;  06h    seek error
;  07h    unknown media
;  08h    sector not found
;  09h    printer out of paper
;  0Ah    write fault
;  0Bh    read fault
;  0Ch    general failure
;  0Dh    reserved
;  0Eh    (CD-ROM) media unavailable
;  0Fh    invalid disk change

IOCTL_CDROM_Read proc near ; CODE XREF: CDROM_InitCheck+4F↑p
                    ; MenuProc+80↓p
mov     ax, mem1kSeg
mov     rmRegs.rEs, ax
mov     ebx, linAdr1k
add     ebx, 0
mov     [ebx+IOCTL_Struct.headerSize], 13
mov     [ebx+IOCTL_Struct.commandCode], 3 ; ioctl input
mov     word ptr [ebx+IOCTL_Struct.transferAddress], 49
mov     word ptr [ebx+(IOCTL_Struct.transferAddress+2)], ax ; address = mem_1k_seg + 31h
mov     [ebx+IOCTL_Struct.numBytesReadWritten], 7
mov     word ptr rmRegs.rEbx, 0
call    RequestToCDRom
mov     ax, [ebx+IOCTL_Struct.status]
retn
IOCTL_CDROM_Read endp


