mov     ebx, 75
mul     ebx
mov     ecx, eax
movzx   eax, byte ptr [esi+1]
mov     ebx, 75
mul     ebx
add     ecx, eax
movzx   eax, byte ptr [esi]
add     eax, ecx
pop     esi
retn
CalcLogicalSectorNumber endp


