                    ; 1: 1=light pen is triggered; 0=armed
                    ; 2: 1=light pen switch is open; 0=closed
                    ; 3: 1=vertical sync pulse is occurring.
inc     bx
test    al, 8
jnz     short @@retrace_time
mov     al, 1
cmp     bx, cx
jnb     short @@retrace_takes_longer
xor     al, al

@@retrace_takes_longer: ; CODE XREF: TimeRetraceAndScreenDraw+29↑j
mov     retraceTakesLonger, al
retn
