; in:
;      D1 - x offset in dest sprite
;      D2 - y offset in dest sprite (only in EGA)
;      D4 - dest sprite index
;      A0 -> text
;      A1 -> chars table
; out:
;      D0 = 0:OK (& zf set), 1:error (& zf clear) (text wider than sprite)
;      D1 = total width in pixels of entire sprite after concatenation
;
; Converts text in A0 and concatenates it to sprite in D4.
; In case of not enough space in the sprite to write the text, the sprite
; will not be modified.
; Sets ebp to -1 unconditionally.

Text2Sprite proc near ; CODE XREF: GoalScored+5AA↓p GoalScored+6EE↓p ...
mov     copySpriteAllowAND, 0
push    D1
push    D2
push    D3
push    D4
push    A0
push    A1
call    GetTextWidth
pop     A1
pop     A0
pop     D4
pop     D3
pop     D2
pop     D1
mov     ax, word ptr D1
add     word ptr D7, ax ; D7 = number of pixels needed to display string + D1
mov     eax, g_spriteGraphicsPtr
mov     A2, eax
mov     ax, word ptr D4
mov     word ptr D0, ax
shl     word ptr D0, 2
mov     esi, A2
movzx   ebx, word ptr D0
mov     eax, [esi+ebx]
mov     A2, eax
mov     esi, A2
mov     ax, [esi+SpriteGraphics.pixWidth]
cmp     word ptr D7, ax
ja      @@err_out   ; if text wider than sprite
mov     eax, A1
mov     A5, eax     ; A5 -> chars table
mov     esi, A5
mov     ax, [esi+CharTable.spriteIndexOffset]
mov     word ptr D6, ax ; D6 = sprite delta
mov     esi, A5
mov     ax, [esi+CharTable.charSpacing]
mov     word ptr D5, ax ; D5 = space between characters
mov     eax, A5
add     eax, 14
mov     A3, eax     ; A3 -> conversion table
mov     eax, g_spriteGraphicsPtr
mov     A2, eax     ; A2 -> sprite.dat

@@chars_loop:       ; CODE XREF: Text2Sprite+14B↓j Text2Sprite+29C↓j
mov     esi, A0
mov     al, [esi]
inc     A0
mov     byte ptr D0, al
or      al, al
jz      @@ok_out
cmp     byte ptr D0, '_'
jnz     short @@not_underscore
mov     byte ptr D0, ' ' ; convert '_' to space

@@not_underscore:   ; CODE XREF: Text2Sprite+110↑j
cmp     byte ptr D0, ' '
jnz     short @@not_space
mov     esi, A5
mov     ax, [esi+CharTable.spaceWidth]
mov     word ptr D7, ax
mov     ax, word ptr D1
add     word ptr D7, ax ; D7 = D1 - length nedeed
mov     ax, word ptr D7
mov     word ptr D1, ax
jmp     short @@chars_loop
; ---------------------------------------------------------------------------

@@not_space:        ; CODE XREF: Text2Sprite+120↑j
sub     byte ptr D0, 32
and     word ptr D0, 0FFh
mov     esi, A3
movzx   ebx, word ptr D0
mov     al, [esi+ebx]
mov     byte ptr D0, al
and     word ptr D0, 0FFh
mov     ax, word ptr D6
add     word ptr D0, ax
mov     ax, word ptr D0
mov     word ptr D7, ax ; D7 = character sprite index
shl     word ptr D7, 2
mov     esi, A2
movzx   ebx, word ptr D7
mov     eax, [esi+ebx]
mov     A1, eax     ; A1 -> sprite struct
mov     esi, A1
mov     ax, [esi+SpriteGraphics.pixWidth]
mov     word ptr D7, ax
mov     ax, word ptr D1
add     word ptr D7, ax ; add sprite length
mov     ax, word ptr D5
add     word ptr D7, ax ; add space between characters
push    D2
push    D3
push    D4
push    D5
push    D6
push    D7
push    A0
push    A2
push    A3
push    A5
mov     ax, word ptr D4
mov     word ptr D3, ax
mov     ebp, -1
cmp     EGA_graphics, -1
jz      short @@benc2_dat
cmp     word ptr D3, SPR_TEAM1_NAME
jz      short @@spr_307_308_team_names
cmp     word ptr D3, SPR_TEAM2_NAME
jz      short @@spr_307_308_team_names

@@benc2_dat:        ; CODE XREF: Text2Sprite+230↑j
call    CopySprite
jmp     short @@next_char
; ---------------------------------------------------------------------------

@@spr_307_308_team_names: ; CODE XREF: Text2Sprite+23B↑j
                    ; Text2Sprite+246↑j
call    TextToTeamNameSprites

@@next_char:        ; CODE XREF: Text2Sprite+24D↑j
pop     A5
pop     A3
pop     A2
pop     A0
pop     D7
pop     D6
pop     D5
pop     D4
pop     D3
pop     D2
mov     ax, word ptr D7
mov     word ptr D1, ax
jmp     @@chars_loop
; ---------------------------------------------------------------------------

@@ok_out:           ; CODE XREF: Text2Sprite+103↑j
mov     ax, word ptr D4
mov     word ptr D0, ax
mov     ax, word ptr D7
mov     word ptr D1, ax
mov     word ptr D0, 0
xor     ax, ax
retn
; ---------------------------------------------------------------------------

@@err_out:          ; CODE XREF: Text2Sprite+A7↑j
mov     word ptr D0, 1
mov     ax, 1
or      ax, ax
retn
Text2Sprite endp


