; in:
;      D0 -  sprite number
;      A0 -> color conversion table
;
; Converts sprites to 8 colors.

ConvertSpriteColors proc near ; CODE XREF: DrawMenuItem+9F5↓p
                    ; InitLittlePlayerSprites+1C4↓p ...
mov     eax, A0
mov     A1, eax
shl     word ptr D0, 1
shl     word ptr D0, 1
movzx   ebx, word ptr D0
mov     esi, g_spriteGraphicsPtr
add     esi, ebx
mov     edi, [esi]
mov     A0, edi
