mov     ecx, eax    ; ecx = number of pixels in sprite

@@pixels_loop:      ; CODE XREF: ConvertSpriteColors+6F↓j
movzx   ebx, byte ptr [edi] ; edi -> sprite data
shr     ebx, 4      ; hi pixel from src byte
shl     ebx, 1      ; turn it to word index
mov     esi, A1
add     esi, ebx
mov     ax, [esi]   ; get word from color table (lo byte will be the new pixel value, lo nibble to be more exact)
shl     al, 4       ; shift it back to its position as hi pixel
movzx   ebx, byte ptr [edi]
and     ebx, 0Fh    ; lo pixel from src byte
shl     ebx, 1      ; make word index out of it
mov     esi, A1
add     esi, ebx
mov     bl, [esi]   ; get byte from color table
or      al, bl      ; now complete byte in al (might trash hi pixel if color table byte has value >15)
mov     [edi], al   ; write that byte back to sprite data (2 converted pixels)
add     edi, 1      ; src ptr ++
loop    @@pixels_loop
retn
ConvertSpriteColors endp

