CopySprite proc near ; CODE XREF: Text2Sprite:@@benc2_dat↑p
                    ; CopyWholeSprite+31↓p ...
cmp     EGA_graphics, -1
jz      EGACopySprite
movzx   ebx, word ptr D3
shl     ebx, 2
mov     esi, g_spriteGraphicsPtr
add     esi, ebx
mov     edi, [esi]
mov     A1, edi     ; A1 -> sprite1
movzx   ebx, word ptr D0
shl     ebx, 2
mov     esi, g_spriteGraphicsPtr
