mov     edi, A1
movzx   eax, [edi+SpriteGraphics.wquads]
shl     eax, 3
mov     D6, eax     ; D6 = sprite1 number of bytes in a line
mov     edi, A1
mov     edi, [edi+SpriteGraphics.sprData]
mov     A1, edi
mov     edi, A0
