xor     edx, edx
movzx   ecx, word ptr D1 ; get sprite1 offset
shr     ecx, 1      ; /=2 because 1 pixel = 1 nibble
add     edi, ecx
movzx   ecx, word ptr D0 ; ecx = number of lines in sprite2

