mov     bl, [esi]
and     bl, 0Fh
or      [edi], bl
inc     esi
inc     edi
loop    @@inner_loop

@@inner_loop_ends:  ; CODE XREF: CopySprite+C3↑j
pop     ecx
pop     esi
pop     edi
add     esi, D5
add     edi, D6
loop    @@outer_loop
retn
CopySprite endp


