add     A1, eax     ; in sprite.dat
mov     esi, A1
mov     eax, [esi]
mov     A1, eax
mov     edi, A1
mov     A0, edi
mov     eax, [edi+SpriteGraphics.sprData]
mov     A0, eax     ; A0 -> sprite data
xor     eax, eax
