; Destroys eax, ebx, ecx, esi, edi, ebp.

DrawChar proc near  ; CODE XREF: DrawMenuText+191↓p
mov     eax, g_spriteGraphicsPtr
mov     A1, eax
shl     word ptr D0, 2
movzx   eax, word ptr D0
add     A1, eax
mov     esi, A1
mov     eax, [esi]
