xchg    eax, D5
mov     D3, eax     ; D3 = restored width
pop     small [word ptr D0]
mov     al, byte ptr D0
cbw
mov     word ptr D0, ax
mov     ax, word ptr D4
add     word ptr D2, ax
sub     word ptr D2, 1 ; D2 = y + height - 1
mov     eax, D4
xchg    eax, D5     ; save height in D5
mov     D4, eax
mov     word ptr D4, 1 ; height = 1
push    D0
push    D1
push    D2
push    D3
push    D4
push    D5
call    DrawMenuItemBackground ; draw bottom line
pop     D5
pop     D4
pop     D3
pop     D2
pop     D1
pop     D0
mov     eax, D4
xchg    eax, D5
mov     D4, eax     ; D4 = restored height
mov     ax, word ptr D4
sub     word ptr D2, ax
add     word ptr D2, 1 ; D2 = y
mov     ax, word ptr D3
add     word ptr D1, ax
sub     word ptr D1, 1 ; D1 = x + width - 1
mov     word ptr D3, 1 ; width = 1
call    DrawMenuItemBackground
retn
DrawMenuItemOuterFrame endp


