mov     esi, A6
mov     eax, [esi]
mov     A3, eax     ; A3 -> current tactics positions to fill
mov     esi, A3
mov     byte ptr [esi], 0 ; 0 for goalkeeper
inc     A3
mov     A2, offset positionDefensiveness
