add     word ptr D0, ax ; current player current ball quadrant positions
mov     esi, A4     ; A4 -> tactics table
movzx   ebx, word ptr D0
mov     al, [esi+ebx+Tactics.playerPos.positions]
mov     byte ptr D1, al
and     word ptr D1, 0FFh
mov     ax, word ptr D1
mov     word ptr D2, ax
