mov     esi, A2
movzx   ebx, word ptr D3
add     [esi+ebx], ax
sub     word ptr D4, 1
cmp     word ptr D4, 15
jnb     @@players_loop ; skip lowest 3 rows of quadrants - only do it for positions from the top half
add     word ptr D6, 1
cmp     word ptr D6, 11
jb      @@players_positions_loop
mov     esi, A6
mov     eax, [esi]
add     A6, 4
mov     A4, eax
add     A4, 1       ; A4 -> player positions to fill, skip goalkeeper
mov     word ptr D5, 8

@@bubble_sort_positions: ; CODE XREF: InitializeTacticsPositions+27F↓j
mov     eax, A4
mov     A3, eax     ; A3 -> tactics positions
mov     A2, (offset positionDefensiveness+2)
