mov     ax, word ptr D5 ; inner sort loop limit
mov     word ptr D4, ax ; bubble sort the list by defensiveness decreasingly

@@buble_position_loop: ; CODE XREF: InitializeTacticsPositions+270↓j
add     A3, 1
mov     esi, A2
mov     ax, [esi]
add     A2, 2
mov     word ptr D0, ax
mov     esi, A2
mov     ax, [esi]
