jnb     short @@next_position
mov     esi, A2     ; swap defensiveness index
mov     ax, [esi]
mov     esi, A2
mov     [esi-2], ax
mov     ax, word ptr D0
mov     esi, A2
mov     [esi], ax
mov     esi, A3     ; swap tactics positions too
mov     al, [esi-1]
mov     byte ptr D0, al
mov     esi, A3
mov     al, [esi]
mov     esi, A3
