; =============== S U B R O U T I N E =======================================

; Set text at CONTINUE... and SAVE... entries, depending
; on mode (career, season, diy) and name of the save file.
; Called when returning to main menu from various submenus.

CommonMenuExit proc near ; CODE XREF: SWOSMainMenuInit+E↑p
                    ; FriendlyMenu+11↓j ...
mov     ax, g_gameType
mov     word ptr D0, ax
cmp     word ptr D0, GAME_TYPE_DIY_COMPETITION
jz      @@diy_competition
cmp     word ptr D0, GAME_TYPE_PRESET_COMPETITION
jz      @@preset_competition
cmp     word ptr D0, GAME_TYPE_SEASON
jz      @@season
cmp     word ptr D0, GAME_TYPE_CAREER
jz      @@career
mov     word ptr D0, 11 ; save career
call    CalcMenuEntryAddress
mov     esi, A0
mov     [esi+MenuEntry.isInvisible], 1 ; make save career invisible
mov     word ptr D0, 10 ; continue ...
call    CalcMenuEntryAddress
mov     esi, A0
mov     [esi+MenuEntry.isInvisible], 1 ; continue career invisible
mov     eax, A0
xchg    eax, A1
mov     A0, eax
push    D0
mov     D0, 10      ; continue ...
call    CalcMenuEntryAddress
pop     D0
mov     eax, A0
xchg    eax, A1     ; A1 -> entry 10 (continue career)
mov     A0, eax
push    D0
mov     D0, 12      ; load competition
call    CalcMenuEntryAddress
pop     D0
mov     esi, A1
mov     ax, [esi+MenuEntry.y]
mov     esi, A0
mov     [esi+MenuEntry.y], ax
retn
; ---------------------------------------------------------------------------

@@diy_competition:  ; CODE XREF: CommonMenuExit+14↑j
mov     A2, offset diyPresetNameOfCompetition
mov     ax, competitionOver
mov     word ptr D0, ax
cmp     word ptr D0, 1
jnz     short @@replay
jmp     short @@continue
; ---------------------------------------------------------------------------

@@preset_competition: ; CODE XREF: CommonMenuExit+22↑j
mov     A2, offset diyPresetNameOfCompetition
mov     ax, competitionOver
mov     word ptr D0, ax
cmp     word ptr D0, 1
jnz     short @@replay
jmp     short @@continue
; ---------------------------------------------------------------------------

@@season:           ; CODE XREF: CommonMenuExit+30↑j
mov     A2, offset aSeason ; "SEASON******"
jmp     short @@continue
; ---------------------------------------------------------------------------

@@career:           ; CODE XREF: CommonMenuExit+3E↑j
mov     A2, offset aCareer ; "CAREER************"
jmp     short $+2

@@continue:         ; CODE XREF: CommonMenuExit+103↑j
                    ; CommonMenuExit+125↑j ...
mov     A0, offset aContinueA ; "CONTINUE %a***"
jmp     short @@show_save_and_continue_entries
; ---------------------------------------------------------------------------

@@replay:           ; CODE XREF: CommonMenuExit+101↑j
                    ; CommonMenuExit+123↑j
mov     A0, offset aReplayA ; "REPLAY %a*****"

@@show_save_and_continue_entries: ; CODE XREF: CommonMenuExit+149↑j
mov     eax, A0
xchg    eax, A1     ; A1 -> format string
mov     A0, eax
push    D0
mov     D0, 10      ; continue career
call    CalcMenuEntryAddress
pop     D0
mov     eax, A0
xchg    eax, A1     ; A1 -> continue career entry
mov     A0, eax     ; A0 -> format string
mov     esi, A1
mov     eax, [esi+MenuEntry.fg.string]
mov     A1, eax     ; set text to "continue..." or "replay..."
call    PrintFormatted
mov     A0, offset aSaveA ; "SAVE %a*******"
mov     A1, offset saveFileTitle
call    PrintFormatted
mov     word ptr D0, 11 ; save career
call    CalcMenuEntryAddress
mov     esi, A0
mov     [esi+MenuEntry.isInvisible], 0
mov     word ptr D0, 10 ; continue career
call    CalcMenuEntryAddress
mov     esi, A0
mov     [esi+MenuEntry.isInvisible], 0
retn
CommonMenuExit endp


