; =============== S U B R O U T I N E =======================================

; Compare new line-up to the old, and display big check or X mark depending is it better or not.
; If skills are equal, or we are looking at opponents team leave it hidden.

UpdateCheckMarkSprite proc near ; CODE XREF: SetVariableButtons+243↑p
                    ; UpdateLittleCheckmark+AB↑p ...
push    D0
mov     D0, 0       ; check or X mark sprite entry
call    CalcMenuEntryAddress
pop     D0
mov     esi, A0
mov     [esi+MenuEntry.isInvisible], 1 ; start hidden
mov     ax, viewingOpponentTeam
or      ax, ax      ; if we are looking at opponents team leave it hidden
jnz     short @@out
mov     esi, A0
mov     ax, [esi+MenuEntry.stringFlags]
mov     word ptr D1, ax
and     word ptr D1, 0DFFFh ; clear bit 13, assume no blinking
mov     ax, word ptr D1
mov     esi, A0
mov     [esi+MenuEntry.stringFlags], ax
mov     ax, oldPlayerSkill ; compare the skills
mov     word ptr D1, ax
mov     ax, newPlayerSkill
cmp     word ptr D1, ax
ja      short @@right
mov     ax, newPlayerSkill ; if new skills are equal to the old don't display anything
cmp     word ptr D1, ax
jb      short @@wrong

@@out:              ; CODE XREF: UpdateCheckMarkSprite+30↑j
retn
; ---------------------------------------------------------------------------

@@wrong:            ; CODE XREF: UpdateCheckMarkSprite+83↑j
mov     esi, A0
mov     [esi+MenuEntry.fg.sprite2], SPR_NOT_CHECK_BIG
jmp     short @@go_on
; ---------------------------------------------------------------------------

@@right:            ; CODE XREF: UpdateCheckMarkSprite+74↑j
mov     esi, A0
mov     [esi+MenuEntry.fg.sprite2], SPR_CHECK_BIG

@@go_on:            ; CODE XREF: UpdateCheckMarkSprite+92↑j
mov     esi, A0
mov     ax, [esi+MenuEntry.stringFlags]
mov     word ptr D1, ax
or      word ptr D1, 2000h ; set bit 13, make it blink
mov     ax, word ptr D1
mov     esi, A0
mov     [esi+MenuEntry.stringFlags], ax
mov     esi, A0
mov     [esi+MenuEntry.isInvisible], 0
retn
UpdateCheckMarkSprite endp


