EditTactics proc near ; CODE XREF: EditTacticsMenu↑p
mov     inEditTactics, 1
mov     A0, offset careerTeam
cmp     g_gameType, GAME_TYPE_CAREER
jz      @@show_menu
mov     ax, g_numSelectedTeams
mov     word ptr D1, ax
or      ax, ax
jz      @@no_selected_teams
sub     word ptr D1, 1
mov     eax, selTeamsPtr
mov     A0, eax
mov     A1, offset editTacticsCountryBuffer
mov     word ptr D0, 0

@@teams_loop:       ; CODE XREF: EditTactics+A3↓j
mov     esi, A0     ; count number of player teams selected,
                    ; number will be in A0
                    ; copy their country numbers
cmp     [esi+TeamFile.teamControls], TEAM_COMPUTER
jz      short @@next_team
mov     esi, A0
mov     ax, [esi]
mov     esi, A1
mov     [esi], ax
add     A1, 2
mov     eax, A0
mov     A2, eax
add     word ptr D0, 1

@@next_team:        ; CODE XREF: EditTactics+65↑j
add     A0, 684
dec     word ptr D1
jns     short @@teams_loop
mov     ax, word ptr D0
or      ax, ax
jz      short @@no_player_teams
mov     eax, A2
mov     A0, eax
cmp     word ptr D0, 1
jz      short @@show_menu
nop
nop
nop
nop
mov     A0, offset aEditTacticsSel ; "EDIT TACTICS - SELECT TEAM***"
mov     A1, offset editTacticsCountryBuffer
call    ChooseTeamForEditTactics
cmp     A0, 0
jnz     short @@show_menu
jmp     short @@out
; ---------------------------------------------------------------------------

@@no_player_teams:  ; CODE XREF: EditTactics+AE↑j
mov     ax, g_numSelectedTeams
or      ax, ax
jnz     short @@computer_teams_only

@@no_selected_teams: ; CODE XREF: EditTactics+30↑j
mov     byte ptr D0, 8 ; english premier division
call    LoadTeamFile
mov     A0, (offset teamFileBuffer+2D6Eh) ; 18th team
call    AddTeamToBuffer ; if nothing selected, load Leicester City
call    InitTeams
jmp     short @@to_career_game
; ---------------------------------------------------------------------------

@@computer_teams_only: ; CODE XREF: EditTactics+F5↑j
mov     A0, offset careerTeam
cmp     selTeamNumber, -1
jnz     short @@show_menu

@@to_career_game:   ; CODE XREF: EditTactics+117↑j
mov     eax, selTeamsPtr
mov     A0, eax

@@show_menu:        ; CODE XREF: EditTactics+1B↑j EditTactics+C2↑j ...
call    ShowStandardChooseTacticsMenu

@@out:              ; CODE XREF: EditTactics+EA↑j
retn
EditTactics endp


