; in:
;      D0 - speed
;      D1 - destination x
;      D2 - destination y
;      D3 - current x
;      D4 - current y
;      (all inputs are 16-bit integers)
; out:
;      D0 - angle (0..255) (0 is 270 degrees, start of trigonometric circle is 64)
;           -1 if no movement (word)
;      D1 - delta x (32-bit fixed point)
;      D2 - delta y (32-bit fixed point)
;      sign flag: set = no movement, clear = there is movement
;
; Delta x and y are numbers of pixels that sprite needs to be moved in one cycle to reach
; destination coordinates.

CalculateDeltaXAndY proc near ; CODE XREF: DrawPlayerDirections+BB↑p
                    ; UpdateBall+1CD↓p ...
mov     ax, word ptr D3
sub     word ptr D1, ax ; D1 = delta x
mov     ax, word ptr D4
sub     word ptr D2, ax ; D2 = delta y
mov     ax, word ptr D0
mov     word ptr D5, ax ; D5 = speed
mov     A1, offset kAngleCoeficients
mov     byte ptr D3, 0 ; D3 = 0 - delta x positive, -1 - delta x negative
mov     ax, word ptr D1
or      ax, ax
jns     short @@test_delta_y
mov     byte ptr D3, -1
neg     word ptr D1

@@test_delta_y:     ; CODE XREF: CalculateDeltaXAndY+40↑j
mov     byte ptr D4, 0 ; D4 = 0 - delta y positive, -1 - delta y negative
mov     ax, word ptr D2
or      ax, ax
