                    ; CalculateDeltaXAndY+88↓j
cmp     word ptr D1, 32
jl      short @@squash_delta_y
shr     word ptr D1, 1 ; divide delta x and y by two until delta x becomes less than 32
shr     word ptr D2, 1
jmp     short @@squash_delta_x
; ---------------------------------------------------------------------------

@@squash_delta_y:   ; CODE XREF: CalculateDeltaXAndY+78↑j
                    ; CalculateDeltaXAndY+A2↓j
cmp     word ptr D2, 32
jl      short @@get_angle_coeficient
shr     word ptr D1, 1 ; divide delta x and y by two until delta y becomes less than 32
shr     word ptr D2, 1
jmp     short @@squash_delta_y
; ---------------------------------------------------------------------------

@@get_angle_coeficient: ; CODE XREF: CalculateDeltaXAndY+92↑j
shl     word ptr D2, 5
mov     ax, word ptr D2
or      word ptr D1, ax
shl     word ptr D1, 1
mov     esi, A1
movzx   ebx, word ptr D1
mov     ax, [esi+ebx]
mov     word ptr D0, ax ; D0 = tangent of the angle [0..64]
or      ax, ax      ; D0 < 0 means dx = dy = 0
js      @@no_movement
shl     word ptr D0, 1
mov     al, byte ptr D3
or      al, al
js      short @@x_negative
mov     al, byte ptr D4
or      al, al
js      short @@x_positive_y_negative
mov     word ptr D1, 128 ; x and y positive
mov     ax, word ptr D0
sub     word ptr D1, ax
jmp     short @@calculate_sine_cosine
; ---------------------------------------------------------------------------

@@x_positive_y_negative: ; CODE XREF: CalculateDeltaXAndY+F7↑j
mov     word ptr D1, 128
mov     ax, word ptr D0
add     word ptr D1, ax
jmp     short @@calculate_sine_cosine
; ---------------------------------------------------------------------------

@@x_negative:       ; CODE XREF: CalculateDeltaXAndY+EE↑j
mov     al, byte ptr D4
or      al, al
js      short @@x_and_y_negative
mov     word ptr D1, 384 ; x negative y positive
mov     ax, word ptr D0
add     word ptr D1, ax
