align 4

; =============== S U B R O U T I N E =======================================

; This proc serves to draw some additional patterns, mostly fans jumping and cheering.
; Called once every frame, also during replays.

DrawAnimatedPatterns proc near ; CODE XREF: GameLoop+4F6↑p
                    ; DrawReplayFrame+287↓p
mov     ax, replayState
or      ax, ax
jz      @@no_game
mov     ax, animPatternsState
or      ax, ax
jz      @@out
mov     otherTeamScored, 0
cmp     animPatternsState, 1
jz      @@ball_out_of_play
cmp     animPatternsState, 2
jz      @@greatest_cheers
cmp     animPatternsState, 3
jz      @@middle_cheers
cmp     animPatternsState, 4
jz      @@other_team_scored_be_still
cmp     animPatternsState, 5
jz      @@cheers_fading
cmp     animPatternsState, 6
jz      @@game_hasnt_started
cmp     animPatternsState, 7
jz      @@game_in_progress
int     3           ; Trap to Debugger

@@endless_loop:     ; CODE XREF: DrawAnimatedPatterns:@@endless_loop↓j
jmp     short @@endless_loop
; ---------------------------------------------------------------------------
retn
; ---------------------------------------------------------------------------

@@no_game:          ; CODE XREF: DrawAnimatedPatterns+9↑j
mov     animPatternsState, 0
mov     ax, g_trainingGame
or      ax, ax
jnz     @@out       ; if training game, go out - there are no fans
mov     ax, patternsGoalCounter
or      ax, ax
jz      short @@game_starting
add     patternsGoalCounter, 1
cmp     patternsGoalCounter, 300
jb      short @@decrease_fans_timer
mov     patternsGoalCounter, 0
jmp     short @@decrease_fans_timer
; ---------------------------------------------------------------------------

@@game_starting:    ; CODE XREF: DrawAnimatedPatterns+AE↑j
mov     ax, goalCounter
or      ax, ax
jz      short @@decrease_fans_timer
mov     patternsGoalCounter, 1

@@decrease_fans_timer: ; CODE XREF: DrawAnimatedPatterns+C1↑j
                    ; DrawAnimatedPatterns+CC↑j ...
mov     ax, showFansCounter
or      ax, ax
jz      short @@fans_counter_zero
sub     showFansCounter, 1

@@fans_counter_zero: ; CODE XREF: DrawAnimatedPatterns+EB↑j
mov     otherTeamScored, 0
mov     ax, showFansCounter
or      ax, ax
jnz     @@game_hasnt_started
cmp     gameStatePl, ST_GAME_IN_PROGRESS
jz      @@game_in_progress
cmp     gameState, ST_KEEPER_HOLDS_BALL
jnz     short @@game_not_started
mov     eax, lastTeamPlayedBeforeBreak
mov     A0, eax
cmp     A0, 0
jz      short @@game_not_started
mov     esi, A0
mov     eax, [esi+TeamGeneralInfo.controlledPlayer]
mov     A0, eax
cmp     A0, 0
jz      @@game_in_progress
jmp     @@game_in_progress
; ---------------------------------------------------------------------------

@@game_not_started: ; CODE XREF: DrawAnimatedPatterns+123↑j
                    ; DrawAnimatedPatterns+136↑j
mov     ax, patternsGoalCounter
or      ax, ax
jz      short @@ball_out_of_play ; nobody scored
nop                 ; not patched
nop
nop
nop
mov     eax, teamScoredGamePtr
mov     A0, eax
cmp     g_cameraY, 440
ja      short @@second_half_of_pitch
mov     ax, fansSidesSwapped ; upper half of pitch
or      ax, ax
jz      short @@fans_not_swapped

cseg_6319F:         ; CODE XREF: DrawAnimatedPatterns+19E↓j
cmp     A0, offset topTeamInGame
jz      short @@left_team_scored
jmp     short @@jmp_other_team_scored_be_still
; ---------------------------------------------------------------------------

@@second_half_of_pitch: ; CODE XREF: DrawAnimatedPatterns+17A↑j
mov     ax, fansSidesSwapped
or      ax, ax
jz      short cseg_6319F

@@fans_not_swapped: ; CODE XREF: DrawAnimatedPatterns+185↑j
cmp     A0, offset bottomTeamInGame
jz      short @@left_team_scored

@@jmp_other_team_scored_be_still:
                    ; CODE XREF: DrawAnimatedPatterns+193↑j
jmp     @@other_team_scored_be_still
; ---------------------------------------------------------------------------

@@left_team_scored: ; CODE XREF: DrawAnimatedPatterns+191↑j
                    ; DrawAnimatedPatterns+1AA↑j
cmp     patternsGoalCounter, 25
jb      short @@greatest_cheers
cmp     patternsGoalCounter, 200
jb      short @@middle_cheers
