mov     word ptr D0, ax ; get month
mov     ax, word ptr D0
mov     bx, 7
mul     bx          ; get month offset in table
mov     word ptr D0, ax
mov     word ptr D0+2, dx
mov     eax, D0
add     A0, eax

@@get_random_probability: ; CODE XREF: SetPitchTypeAndNumber+33↑j
call    Rand
mov     ax, word ptr D0
mov     bx, 100
mul     bx
mov     word ptr D0, ax
mov     word ptr D0+2, dx
mov     ax, word ptr D0
mov     dx, word ptr D0+2
mov     bx, 256
div     bx
mov     word ptr D0, ax
mov     word ptr D0+2, dx ; D0 in range 0..99
mov     word ptr D1, 0

