and     word ptr D0, 10h
shl     word ptr D0, 4 ; this value gets overwritten
mov     ax, plg_D0_param
or      ax, ax
jz      short @@set_pseudo_random_pitch
call    Rand
and     word ptr D0, 0Fh
jmp     short @@select_pitch_number
