UpdateAndDrawStatistics proc near ; CODE XREF: GameLoop+50A↑p
                    ; KeepStatisticsOnScreen+F↑p
mov     ax, showStats
or      ax, ax
jz      short @@check_if_stats_on_screen
mov     showStats, 0
mov     showingUserStats, 1
mov     statsTimer, 32000
call    DrawStatistics

@@check_if_stats_on_screen: ; CODE XREF: UpdateAndDrawStatistics+9↑j
mov     ax, showingUserStats
or      ax, ax
jz      short @@not_showing_stats
call    Player1StatusProc
call    Player2StatusProc
mov     al, pl1Fire
or      al, al
jnz     short @@joy1_firing
mov     al, pl2Fire
or      al, al
jnz     short @@joy2_firing
retn
; ---------------------------------------------------------------------------

@@joy1_firing:      ; CODE XREF: UpdateAndDrawStatistics+47↑j
mov     fireBlocked, 1
jmp     @@out_stats_off
; ---------------------------------------------------------------------------

@@joy2_firing:      ; CODE XREF: UpdateAndDrawStatistics+50↑j
mov     fireBlocked, 1
jmp     @@out_stats_off
; ---------------------------------------------------------------------------

@@not_showing_stats: ; CODE XREF: UpdateAndDrawStatistics+34↑j
mov     ax, playingPenalties
or      ax, ax
jnz     @@stats_update_done
cmp     gameStatePl, ST_GAME_IN_PROGRESS
jnz     short @@ball_possession_updated
mov     eax, lastTeamPlayed
mov     A0, eax
cmp     A0, offset topTeamData
jz      short @@increase_possession
cmp     A0, offset bottomTeamData
jnz     short @@ball_possession_updated

@@increase_possession: ; CODE XREF: UpdateAndDrawStatistics+9C↑j
mov     esi, A0
mov     eax, [esi+TeamGeneralInfo.teamStatsPtr]
mov     A0, eax
mov     esi, A0
add     [esi+TeamStatisticsData.ballPossession], 1

@@ball_possession_updated: ; CODE XREF: UpdateAndDrawStatistics+86↑j
                    ; UpdateAndDrawStatistics+A8↑j
cmp     gameStatePl, ST_GAME_IN_PROGRESS
jnz     @@reset_goal_attempt
mov     ax, isGoalAttempt
or      ax, ax
jz      short @@no_goal_attempts
mov     A0, offset topTeamData
mov     eax, ballSprite.deltaY
mov     D0, eax
cmp     word ptr ballSprite.y+2, 449
jb      short @@check_last_team_played
mov     A0, offset bottomTeamData
neg     D0

@@check_last_team_played: ; CODE XREF: UpdateAndDrawStatistics+F8↑j
mov     eax, lastTeamPlayed
cmp     A0, eax
jz      @@reset_goal_attempt
mov     eax, D0
or      eax, eax
jns     @@reset_goal_attempt
jmp     @@stats_update_done
; ---------------------------------------------------------------------------

@@no_goal_attempts: ; CODE XREF: UpdateAndDrawStatistics+D9↑j
mov     ax, ballInGoalkeeperArea
or      ax, ax
jz      @@stats_update_done
mov     A0, offset topTeamData
mov     eax, ballSprite.deltaY
mov     D0, eax
cmp     word ptr ballSprite.y+2, 449
ja      short @@check_if_y_movement
mov     A0, offset bottomTeamData
neg     D0

@@check_if_y_movement: ; CODE XREF: UpdateAndDrawStatistics+159↑j
mov     eax, D0
or      eax, eax
jle     @@stats_update_done
mov     eax, lastTeamPlayed
cmp     A0, eax
jnz     @@stats_update_done
mov     esi, A0
mov     ax, [esi+TeamGeneralInfo.playerHasBall]
or      ax, ax
jnz     @@stats_update_done
cmp     strikeDestX, 240
jb      @@stats_update_done
cmp     strikeDestX, 431
ja      @@stats_update_done
cmp     strikeDestX, 303
jb      short @@goal_attempt_not_on_target
cmp     strikeDestX, 367
ja      short @@goal_attempt_not_on_target
mov     eax, topTeamData.teamStatsPtr
mov     A0, eax
mov     eax, A0
add     eax, TeamStatisticsData.onTarget
mov     A0, eax
cmp     word ptr ballSprite.y+2, 449
ja      short @@update_shots_on_target
mov     eax, bottomTeamData.teamStatsPtr
mov     A0, eax
mov     eax, A0
add     eax, TeamStatisticsData.onTarget
mov     A0, eax

@@update_shots_on_target: ; CODE XREF: UpdateAndDrawStatistics+1F0↑j
mov     esi, A0
add     word ptr [esi], 1

@@goal_attempt_not_on_target: ; CODE XREF: UpdateAndDrawStatistics+1C3↑j
                    ; UpdateAndDrawStatistics+1CE↑j
mov     eax, topTeamData.teamStatsPtr
mov     A0, eax
mov     eax, A0
add     eax, TeamStatisticsData.goalAttempts
mov     A0, eax
cmp     word ptr ballSprite.y+2, 449
ja      short @@bump_goal_attempts
mov     eax, bottomTeamData.teamStatsPtr
mov     A0, eax
mov     eax, A0
add     eax, TeamStatisticsData.goalAttempts
mov     A0, eax

@@bump_goal_attempts: ; CODE XREF: UpdateAndDrawStatistics+233↑j
mov     esi, A0
add     word ptr [esi], 1
mov     isGoalAttempt, 1
jmp     short @@stats_update_done
; ---------------------------------------------------------------------------

@@reset_goal_attempt: ; CODE XREF: UpdateAndDrawStatistics+CA↑j
                    ; UpdateAndDrawStatistics+115↑j ...
mov     isGoalAttempt, 0

@@stats_update_done: ; CODE XREF: UpdateAndDrawStatistics+78↑j
                    ; UpdateAndDrawStatistics+128↑j ...
mov     ax, showStats
or      ax, ax
jz      short @@check_stats_timer
mov     showStats, 0
mov     showingUserStats, 1

@@check_stats_timer: ; CODE XREF: UpdateAndDrawStatistics+273↑j
mov     ax, statsTimer
or      ax, ax
jz      short @@out
js      short @@out_stats_off
cmp     statsTimer, 32000
jnz     short @@decrement_stats_timeout
mov     statsTimer, 30000
jmp     short @@draw_stats
; ---------------------------------------------------------------------------

@@decrement_stats_timeout: ; CODE XREF: UpdateAndDrawStatistics+29D↑j
mov     ax, lastFrameTicks
mov     word ptr D0, ax
mov     ax, word ptr D0
sub     statsTimer, ax
jg      short @@draw_stats

@@out_stats_off:    ; CODE XREF: UpdateAndDrawStatistics+5C↑j
                    ; UpdateAndDrawStatistics+6A↑j ...
call    StatisticsOff
retn
; ---------------------------------------------------------------------------

@@draw_stats:       ; CODE XREF: UpdateAndDrawStatistics+2A8↑j
                    ; UpdateAndDrawStatistics+2C3↑j
call    DrawStatistics

@@out:              ; CODE XREF: UpdateAndDrawStatistics+290↑j
retn
UpdateAndDrawStatistics endp


