DrawGrid proc near  ; CODE XREF: DrawStatistics+24↑p
                    ; DrawStatistics+65↑p ...
mov     word ptr D0, SPR_SQUARE_GRID
shr     word ptr D3, 4
shr     word ptr D4, 4 ; divide width and height by 16
mov     ax, word ptr D1
mov     word ptr D5, ax
sub     word ptr D3, 1
sub     word ptr D4, 1

@@outer_loop:       ; CODE XREF: DrawGrid+C8↓j
mov     ax, word ptr D5 ; saved x
mov     word ptr D1, ax
mov     ax, word ptr D3
mov     word ptr D6, ax ; number of 16-pixel segments by height

@@inner_loop:       ; CODE XREF: DrawGrid+B7↓j
push    D0
push    D1
push    D2
push    D3
push    D4
push    D5
push    D6
xor     ebp, ebp
call    DarkenRectangle
pop     D6
pop     D5
pop     D4
pop     D3
pop     D2
pop     D1
pop     D0
add     word ptr D1, 16
dec     word ptr D6
jns     short @@inner_loop
add     word ptr D2, 16
dec     word ptr D4
jns     @@outer_loop
retn
DrawGrid endp


; =============== S U B R O U T I N E =======================================

; in:
;      D1 - x (where the center of the string will be)
;      D2 - y
;      D3 - color
;      A1 -> chars table (big or small)
;      A0 -> text
; out:
;      D1 - width of string just written in pixels

PrintCenteredStringInColor proc near ; CODE XREF: DrawStatistics+356↑p
                    ; DrawStatistics+3C5↑p ...
push    D1
push    D2
push    A0
push    A1
call    GetTextWidth
pop     A1
pop     A0
pop     D2
pop     D1
add     word ptr D7, 1
shr     word ptr D7, 1 ; num. pixels /= 2 (rounded up)
mov     ax, word ptr D7
sub     word ptr D1, ax ; x - (num. pixels / 2) = centered x coordinate
jmp     short $+2   ; assume fallthrough
PrintCenteredStringInColor endp


; =============== S U B R O U T I N E =======================================

; in:
;      D1 - x
;      D2 - y
;      D3 - color
;      A1 -> chars table (big or small)
;      A0 -> text
; out:
;      D1 - width of string just written in pixels
;
; Doesn't save background when drawing sprites.
; Stops if the string goes off the right screen border.

PrintStringInColor proc near ; CODE XREF: DrawSubstitutesMenuEntry+77E↓p
mov     eax, A1
mov     A5, eax
mov     esi, A5
mov     ax, [esi+CharTable.spriteIndexOffset]
mov     word ptr D4, ax ; D4 = sprite index offset
mov     esi, A5
mov     ax, [esi+CharTable.charSpacing]
mov     word ptr D5, ax ; D5 = space between characters
mov     eax, A5
add     eax, CharTable.conversionTable
mov     A3, eax     ; A3 -> conversion table
mov     eax, g_spriteGraphicsPtr
mov     A2, eax     ; A2 -> sprite.dat
mov     word ptr D6, 320 ; D6 = 320, screen width

@@next_char:        ; CODE XREF: PrintStringInColor+BB↓j
                    ; PrintStringInColor+1E3↓j
mov     esi, A0
movzx   eax, byte ptr [esi]
inc     A0
mov     D0, eax
or      al, al
jz      @@out
cmp     byte ptr D0, '_'
jnz     short @@not_underscore
mov     byte ptr D0, ' '

@@not_underscore:   ; CODE XREF: PrintStringInColor+6D↑j
cmp     byte ptr D0, ' '
jnz     short @@not_space
mov     esi, A5
mov     ax, [esi+CharTable.spaceWidth]
mov     word ptr D7, ax
mov     ax, word ptr D1
add     word ptr D7, ax ; D7 = current text width
mov     ax, word ptr D6
cmp     word ptr D7, ax
jnb     @@out
mov     ax, word ptr D7
mov     word ptr D1, ax ; D1 = current x
jmp     short @@next_char
; ---------------------------------------------------------------------------

@@not_space:        ; CODE XREF: PrintStringInColor+7D↑j
sub     byte ptr D0, 32 ; original string character minus 32
and     word ptr D0, 0FFh
mov     esi, A3
movzx   eax, word ptr D0
add     esi, eax
movzx   eax, byte ptr [esi]
mov     D0, eax     ; D0 = sprite index from the conversion table
and     word ptr D0, 0FFh
mov     ax, word ptr D4
add     word ptr D0, ax ; D0 = final sprite index (with sprite offset added)
mov     ax, word ptr D0
mov     word ptr D7, ax
shl     word ptr D7, 2
mov     esi, A2
movzx   eax, word ptr D7
add     esi, eax
mov     eax, [esi]
mov     A1, eax     ; A1 -> sprite
mov     esi, A1
mov     ax, [esi+SpriteGraphics.pixWidth]
mov     word ptr D7, ax
mov     ax, word ptr D1
