; =============== S U B R O U T I N E =======================================

; Search the whole team for a player with the same position as the one about to enter the game.
; If there's no exact match try approximate (RB,LB,D -> D, RW,LW,M -> M). If there isn't evan an
; approximate match, then just use first one available.
; This data will be used to mark the initial player when substitutes menu opens up for the first time.

FindInitialPlayerToBeSubstituted proc near
                    ; CODE XREF: FirePressedInSubsMenu:@@do_substitute↑p
mov     eax, benchTeamGame
mov     A0, eax
mov     A1, offset inGameTeamPlayerOffsets
mov     ax, plToEnterGameIndex
mov     word ptr D0, ax
shl     word ptr D0, 1
mov     esi, A1
movzx   ebx, word ptr D0
mov     ax, [esi+ebx]
mov     word ptr D0, ax
mov     esi, A0
movzx   ebx, word ptr D0
mov     al, [esi+ebx+PlayerInfoHeader.position]
mov     byte ptr D7, al ; D7 = player's position
mov     word ptr D6, -1 ; D6 = first available player
mov     word ptr D5, -1 ; D5 = exact match
mov     word ptr D4, -1 ; D4 = approximate match
mov     eax, benchTeamGame
mov     A0, eax
mov     A1, offset inGameTeamPlayerOffsets
mov     ax, plToEnterGameIndex
mov     word ptr D0, ax
shl     word ptr D0, 1
mov     esi, A1
movzx   ebx, word ptr D0
mov     ax, [esi+ebx]
mov     word ptr D0, ax
mov     esi, A0
movzx   ebx, word ptr D0
mov     al, [esi+ebx+PlayerInfoHeader.position]
mov     byte ptr D7, al ; D7 = position (duplicated code)
mov     word ptr D1, 0

@@find_not_sent_off_player:
                    ; CODE XREF: FindInitialPlayerToBeSubstituted+1D7↓j
mov     ax, word ptr D1 ; D1 - current player index
mov     word ptr D0, ax
call    GetBenchPlayerPointer
mov     esi, A0     ; A0 -> current player in-game pointer
cmp     [esi+PlayerInfoHeader.cards], 2
jnb     @@next_player
mov     ax, word ptr D6
or      ax, ax
jns     short @@check_if_we_have_approximate_match
mov     ax, word ptr D1
mov     word ptr D6, ax

@@check_if_we_have_approximate_match:
                    ; CODE XREF: FindInitialPlayerToBeSubstituted+F6↑j
mov     ax, word ptr D4
or      ax, ax
jns     @@check_if_we_got_exact_match
cmp     byte ptr D7, POS_DEFENDER
jz      short @@defender
cmp     byte ptr D7, POS_RIGHT_BACK
jz      short @@defender
cmp     byte ptr D7, POS_LEFT_BACK
jz      short @@defender
cmp     byte ptr D7, POS_MIDFIELDER
jz      short @@midfielder
cmp     byte ptr D7, POS_RIGHT_WING
jz      short @@midfielder
cmp     byte ptr D7, POS_LEFT_WING
jnz     short @@check_if_we_got_exact_match

@@midfielder:       ; CODE XREF: FindInitialPlayerToBeSubstituted+135↑j
                    ; FindInitialPlayerToBeSubstituted+13E↑j
mov     esi, A0
cmp     [esi+PlayerInfoHeader.position], POS_MIDFIELDER
jz      short @@match
mov     esi, A0
cmp     [esi+PlayerInfoHeader.position], POS_RIGHT_WING
jz      short @@match
mov     esi, A0
cmp     [esi+PlayerInfoHeader.position], POS_LEFT_WING
jz      short @@match
jmp     short @@check_if_we_got_exact_match
; ---------------------------------------------------------------------------

@@defender:         ; CODE XREF: FindInitialPlayerToBeSubstituted+11A↑j
                    ; FindInitialPlayerToBeSubstituted+123↑j ...
mov     esi, A0
cmp     [esi+PlayerInfoHeader.position], POS_DEFENDER
jz      short @@match
mov     esi, A0
cmp     [esi+PlayerInfoHeader.position], POS_RIGHT_BACK
jz      short @@match
mov     esi, A0
cmp     [esi+PlayerInfoHeader.position], POS_LEFT_BACK
jnz     short @@check_if_we_got_exact_match

@@match:            ; CODE XREF: FindInitialPlayerToBeSubstituted+153↑j
                    ; FindInitialPlayerToBeSubstituted+15F↑j ...
mov     ax, word ptr D1
mov     word ptr D4, ax ; D4 = approximate match

@@check_if_we_got_exact_match:
                    ; CODE XREF: FindInitialPlayerToBeSubstituted+10D↑j
                    ; FindInitialPlayerToBeSubstituted+147↑j ...
mov     ax, word ptr D5
or      ax, ax
jns     short @@next_player
mov     esi, A0
mov     al, [esi+PlayerInfoHeader.position]
cmp     byte ptr D7, al
jnz     short @@next_player
mov     ax, word ptr D1
mov     word ptr D5, ax ; D5 = exact match

@@next_player:      ; CODE XREF: FindInitialPlayerToBeSubstituted+E7↑j
                    ; FindInitialPlayerToBeSubstituted+1A8↑j ...
add     word ptr D1, 1
cmp     word ptr D1, 11
jnz     @@find_not_sent_off_player
mov     ax, word ptr D5
mov     word ptr D0, ax
or      ax, ax
jns     short @@set_pl_to_be_substituted_ord
mov     ax, word ptr D4
mov     word ptr D0, ax
or      ax, ax
jns     short @@set_pl_to_be_substituted_ord
mov     ax, word ptr D6
mov     word ptr D0, ax

@@set_pl_to_be_substituted_ord:
                    ; CODE XREF: FindInitialPlayerToBeSubstituted+1EC↑j
                    ; FindInitialPlayerToBeSubstituted+1FD↑j
mov     ax, word ptr D0
mov     plToBeSubstitutedOrd, ax
call    GetBenchPlayerPointer
mov     ax, word ptr D0
mov     plToBeSubstitutedPos, ax
retn
FindInitialPlayerToBeSubstituted endp


; =============== S U B R O U T I N E =======================================

; in:
;      D6 - index of player that's entering the game
;      D7 - index of player that's leaving the game
;
; Swap name lengths and ordinals of players.

SwapPlayerNameData proc near
                    ; CODE XREF: SubstitutePlayer:@@swap_player_name_data↑p
                    ; MarkPlayersMenuHandler:@@swap_player_data↑p
mov     A0, offset plOrdinalsTable
mov     A1, offset plNamesLengthTableCopy
cmp     benchTeamGame, offset topTeamInGame
jz      short @@swap_name_length
mov     eax, A0
add     eax, 16
mov     A0, eax
mov     eax, A1
add     eax, 16
mov     A1, eax

@@swap_name_length: ; CODE XREF: SwapPlayerNameData+1E↑j
mov     esi, A0
movzx   ebx, word ptr D6
mov     al, [esi+ebx]
mov     byte ptr D0, al
mov     esi, A0
movzx   ebx, word ptr D7
mov     al, [esi+ebx]
mov     esi, A0
movzx   ebx, word ptr D6
mov     [esi+ebx], al
mov     al, byte ptr D0
mov     esi, A0
movzx   ebx, word ptr D7
mov     [esi+ebx], al
mov     esi, A1
movzx   ebx, word ptr D6
mov     al, [esi+ebx]
mov     byte ptr D0, al
mov     esi, A1
movzx   ebx, word ptr D7
mov     al, [esi+ebx]
mov     esi, A1
movzx   ebx, word ptr D6
mov     [esi+ebx], al
mov     al, byte ptr D0
mov     esi, A1
movzx   ebx, word ptr D7
mov     [esi+ebx], al
retn
SwapPlayerNameData endp


