; in:
;      D0 - player index
; out:
;      A0 -> player pointer (game) + header
;      D0 -  player ordinal (0..10)
;
; Get in-game player pointer given his index, based on current tactics.

GetBenchPlayerPointer proc near
                    ; CODE XREF: UpdatePlayerToBeSubstitutedPosition+C↑p
                    ; FindInitialPlayerToBeSubstituted+D8↑p ...
push    small [word ptr D1]
mov     ax, pl1Tactics
mov     word ptr D1, ax
mov     eax, benchTeam
mov     A0, eax
mov     esi, A0
cmp     [esi+TeamGeneralInfo.teamNumber], 1
jz      short @@get_position
mov     ax, pl2Tactics
mov     word ptr D1, ax

@@get_position:     ; CODE XREF: GetBenchPlayerPointer+28↑j
shl     word ptr D1, 2
mov     A0, offset positionsTable
mov     esi, A0
movzx   ebx, word ptr D1
mov     eax, [esi+ebx]
mov     A0, eax     ; A0 -> ordinals
mov     esi, A0
movzx   ebx, word ptr D0
mov     al, [esi+ebx]
mov     byte ptr D0, al
sub     byte ptr D0, 1 ; D0 = player position
mov     A0, offset inGameTeamPlayerOffsets
mov     ax, word ptr D0
mov     word ptr D1, ax
shl     word ptr D1, 1
mov     esi, A0
movzx   ebx, word ptr D1
mov     ax, [esi+ebx]
mov     word ptr D1, ax ; D1 = player offset
mov     eax, benchTeamGame
mov     A0, eax
mov     eax, A0
add     eax, 0
movzx   ebx, word ptr D1
add     eax, ebx
mov     A0, eax     ; A0 -> player (game)
pop     small [word ptr D1]
retn
GetBenchPlayerPointer endp


