; in:
;      D1 - x (for player sprites)
;      D2 - y
;      A0 -> team that requested team management (in-game)
;      A1 -> team data (general info)
;
; Draws all bench sprites.

DrawBenchPlayersAndCoach proc near
                    ; CODE XREF: DrawBenchAndSubsMenu+1AE↑p
                    ; DrawOpponentsBench+73↑p
mov     g_deltaColor, 16
mov     word ptr D5, 0 ; coach frame team offset
mov     word ptr D6, 0 ; reserve players frame team offset
mov     esi, A1
cmp     [esi+TeamGeneralInfo.teamNumber], 1
jz      short @@calc_y
