sub     ax, SPR_COACH1_SITTING_1 ; ax = 7
mov     word ptr D5, ax
mov     ax, SPR_RESERVE_PLAYERS_SITTING1 ; reserve player pictures, sitting and standing
sub     ax, SPR_BENCH_SITTING_GOALIE_WHITE ; ax = 12
mov     word ptr D6, ax

@@calc_y:           ; CODE XREF: DrawBenchPlayersAndCoach+24↑j
sub     word ptr D2, 19
add     word ptr D2, 4 ; y -= 15
mov     word ptr D3, SPR_COACH1_SITTING_1 ; D3 = coach frame
cmp     initialSubsState, 4 ; formation menu
jz      short @@listing_players
cmp     initialSubsState, 2
jnz     short @@get_coach_random_frame

@@listing_players:  ; CODE XREF: DrawBenchPlayersAndCoach+63↑j
mov     ax, g_benchPlayerIndex
or      ax, ax
jnz     short @@get_coach_random_frame
mov     word ptr D3, SPR_COACH1_STANDING_1

@@get_coach_random_frame: ; CODE XREF: DrawBenchPlayersAndCoach+6D↑j
                    ; DrawBenchPlayersAndCoach+78↑j
