or      ax, ax
jnz     short @@prepare_players_loop
sub     word ptr D2, 14

@@prepare_players_loop: ; CODE XREF: DrawBenchPlayersAndCoach+10C↑j
                    ; DrawBenchPlayersAndCoach+18E↑j ...
add     word ptr D2, 7
