; ---------------------------------------------------------------------------

@@set_player_sitting_sprite: ; CODE XREF: DrawBenchPlayersAndCoach+233↑j
                    ; DrawBenchPlayersAndCoach+267↑j ...
mov     word ptr D0, SPR_BENCH_PLAYER_SITTING_WHITE
cmp     gameMaxSubstitutes, 5
jbe     short @@check_if_goalkeeper_sitting
cmp     word ptr D7, 1
jnz     short @@determine_player_face
jmp     short @@set_goalie_sitting_sprite
; ---------------------------------------------------------------------------

@@check_if_goalkeeper_sitting:
                    ; CODE XREF: DrawBenchPlayersAndCoach+2C9↑j
mov     esi, A0
cmp     [esi+PlayerInfoHeader.position], POS_GOALKEEPER
jnz     short @@determine_player_face

@@set_goalie_sitting_sprite: ; CODE XREF: DrawBenchPlayersAndCoach+2D5↑j
mov     word ptr D0, SPR_BENCH_SITTING_GOALIE_WHITE

@@determine_player_face: ; CODE XREF: DrawBenchPlayersAndCoach+29D↑j
                    ; DrawBenchPlayersAndCoach+2AB↑j ...
mov     ax, useIndividualPlayerSkinColor
or      ax, ax
jnz     short @@use_real_player_face
mov     esi, A1
