DrawFormationMenuEntry proc near
                    ; CODE XREF: DrawFormationMenu:@@draw_formation_entry↑p
push    D2
push    D4
mov     ax, formationMenuX
mov     word ptr D0, ax
mov     ax, g_cameraX
sub     word ptr D0, ax
mov     ax, word ptr D2
mov     word ptr D1, ax
mov     word ptr D2, 60
mov     word ptr D3, 9 ; 60 x 9, 2 pixels more than the entry
mov     word ptr D4, 8 ; color - greenish black
push    D0
push    D1
push    D2
push    D3
push    D7
push    A1
push    A2
push    A3
push    A4
