pop     A4
pop     A3
pop     A2
pop     A1
pop     D7
pop     D3
pop     D2
pop     D1
pop     D0
sub     word ptr D0, 2 ; frame is moved 2 pixels top-left
sub     word ptr D1, 2
mov     ax, subsMenuEntryFrameColor
mov     word ptr D4, ax
push    D7
push    A1
push    A2
push    A3
push    A4
call    FillRectangle ; draw entry frame
pop     A4
pop     A3
pop     A2
pop     A1
pop     D7
pop     D4          ; restore D4 (entry color)
pop     D2          ; restore D2 (y)
push    D2
mov     ax, formationMenuX
mov     word ptr D0, ax
mov     ax, g_cameraX
sub     word ptr D0, ax
sub     word ptr D0, 1 ; frame is at -2 pixels so background comes at +1
mov     ax, word ptr D2
mov     word ptr D1, ax
sub     word ptr D1, 1
mov     word ptr D2, 58
mov     word ptr D3, 7 ; dimensions 58x7
push    D7
push    A1
push    A2
push    A3
push    A4
call    FillRectangle ; draw entry background
pop     A4
pop     A3
pop     A2
pop     A1
pop     D7
pop     D2
cmp     word ptr D7, 12
jnb     short @@user_tactics
mov     A0, offset tacticsStringTable
mov     ax, word ptr D7
mov     word ptr D0, ax
shl     word ptr D0, 2
mov     esi, A0
movzx   ebx, word ptr D0
mov     eax, [esi+ebx]
mov     A0, eax     ; A0 -> tactics name
jmp     short @@print_tactics_name
; ---------------------------------------------------------------------------

@@user_tactics:     ; CODE XREF: DrawFormationMenuEntry+1C2↑j
