shl     word ptr D0, 2
mov     esi, A0
movzx   ebx, word ptr D0
mov     eax, [esi+ebx]
mov     A0, eax
mov     eax, A0
add     eax, 0
mov     A0, eax     ; A0 -> user tactics name

@@print_tactics_name: ; CODE XREF: DrawFormationMenuEntry+1F7↑j
