sub     word ptr D1, ax
add     word ptr D1, 30 ; entry center: 30
mov     word ptr D3, 2
push    D0
push    D2
push    D6
push    D7
push    A1
push    A2
push    A3
push    A4
call    PrintCenteredStringInColor
pop     A4
pop     A3
pop     A2
pop     A1
pop     D7
pop     D6
pop     D2
pop     D0
retn
DrawFormationMenuEntry endp


; =============== S U B R O U T I N E =======================================

; in:
;      D0 - >= 0 - sprite index
;           = -2 - mark end of the segment with -1
;              < 0 - (usually -1) beginning of frame
;      D4 - sprite x coordinate (or camera if D0 < 0)
;      D5 - sprite y coordinate (or camera if D0 < 0)
;
; Saves current sprite coordinate for highlights.

SaveCoordinatesForHighlights proc near ; CODE XREF: GameLoop+4A1↑p
                    ; GameLoop+518↑p ...
mov     eax, currentHilPtr
mov     A1, eax
mov     ax, word ptr D0
or      ax, ax
js      @@end_or_start_of_scene
mov     D3, 10
mov     cl, byte ptr D3
shl     D0, cl
and     word ptr D4, 3FFh
mov     ax, word ptr D4
or      word ptr D0, ax
mov     cl, byte ptr D3
shl     D0, cl
and     word ptr D5, 3FFh
mov     ax, word ptr D5
or      word ptr D0, ax
and     D0, 7FFFFFFFh
mov     eax, D0
mov     esi, A1
mov     [esi], eax
add     A1, 4
call    IncrementHilBufferPointer
mov     eax, A1
mov     currentHilPtr, eax
retn
; ---------------------------------------------------------------------------

@@end_or_start_of_scene: ; CODE XREF: SaveCoordinatesForHighlights+13↑j
cmp     word ptr D0, -2
jnz     short @@starting_a_frame
mov     esi, A1
mov     dword ptr [esi], -1
retn
; ---------------------------------------------------------------------------

@@starting_a_frame: ; CODE XREF: SaveCoordinatesForHighlights+9D↑j
or      D5, 8000h
mov     ax, word ptr D4
mov     esi, A1
mov     [esi], ax
add     A1, 2
mov     ax, word ptr D5
mov     esi, A1
mov     [esi], ax   ; save camera x and camera y (and set dword's highest bit)
add     A1, 2
call    IncrementHilBufferPointer
mov     eax, A1
mov     currentHilPtr, eax
mov     ax, team1TotalGoals
mov     esi, A1
mov     [esi], ax
add     A1, 2
mov     ax, team2TotalGoals
mov     esi, A1
mov     [esi], ax
add     A1, 2
call    IncrementHilBufferPointer
mov     ax, animPatternsState
mov     esi, A1
mov     [esi], ax
add     A1, 2
mov     ax, animPatternsState
mov     esi, A1
mov     [esi], ax
add     A1, 2
call    IncrementHilBufferPointer
mov     eax, A1
mov     currentHilPtr, eax
mov     esi, A1     ; no increment
mov     dword ptr [esi], -1 ; if anything follows it will overwrite -1 marker
retn
SaveCoordinatesForHighlights endp


; =============== S U B R O U T I N E =======================================

; out:
;      A1 -> current position in hil buffer

IncrementHilBufferPointer proc near
                    ; CODE XREF: SaveCoordinatesForHighlights+85↑p
                    ; SaveCoordinatesForHighlights+E2↑p ...
mov     eax, nextGoalPtr
cmp     A1, eax
jnz     short @@out
mov     eax, goalBasePtr
mov     A1, eax

@@out:              ; CODE XREF: IncrementHilBufferPointer+B↑j
retn
IncrementHilBufferPointer endp


; =============== S U B R O U T I N E =======================================

; Handle 'R' key press during the game. If not already replaying
; start the quick replay. If replaying toggle between slow motion
; mode.
;
; If just starting the in-game quick replay find the first dword
; that has highest bit set and set currentGoalPtr to it. This is
; the dword from which the playback starts.

HandleInstantReplayStateSwitch proc near ; CODE XREF: GameLoop+55A↑p
                    ; PlayInstantReplayLoop+15A↑p ...
mov     ax, replayState
or      ax, ax
jnz     short @@already_replaying
mov     D0, 0
mov     eax, currentHilPtr
mov     A0, eax

@@loop:             ; CODE XREF: HandleInstantReplayStateSwitch+5A↓j
cmp     D0, 19000
jz      short @@out
add     D0, 4
add     A0, 4
mov     eax, nextGoalPtr
cmp     A0, eax
jnz     short @@not_next
mov     eax, goalBasePtr
mov     A0, eax

@@not_next:         ; CODE XREF: HandleInstantReplayStateSwitch+44↑j
mov     esi, A0
test    byte ptr [esi+3], 80h
jz      short @@loop ; if high bit not set, keep looping
mov     eax, A0     ; found dword with high bit set
mov     currentGoalPtr, eax ; set current goal ptr to point at it
mov     replayState, 1

@@out:              ; CODE XREF: HandleInstantReplayStateSwitch+29↑j
retn
; ---------------------------------------------------------------------------

@@already_replaying: ; CODE XREF: HandleInstantReplayStateSwitch+9↑j
cmp     replayState, 3
jz      short @@switch_back_to_normal_mode
cmp     replayState, 2
jz      short @@switch_to_slow_motion_mode
retn
; ---------------------------------------------------------------------------

@@switch_back_to_normal_mode:
                    ; CODE XREF: HandleInstantReplayStateSwitch+78↑j
mov     replayState, 2
retn
; ---------------------------------------------------------------------------

@@switch_to_slow_motion_mode:
                    ; CODE XREF: HandleInstantReplayStateSwitch+82↑j
mov     replayState, 3
retn
HandleInstantReplayStateSwitch endp


