mov     g_cameraX, 176
mov     g_oldCameraY, 0
mov     g_cameraY, 349
push    D0
push    D1
push    D2
push    D3
push    D4
push    D5
push    D6
push    D7
push    A0
push    A1
push    A2
push    A3
push    A4
push    A5
push    A6
