mov     ax, word ptr D2
mov     g_cameraY, ax
call    ScrollToCurrent
pop     A0

@@start_replaying:  ; CODE XREF: DrawReplayFrame+12↑j
mov     esi, A0
mov     eax, [esi]
add     A0, 4
mov     D0, eax
test    D0, 80000000h
jz      @@is_sprite
call    ValidateHilPointerAdd
and     D0, 7FFFFFFFh
mov     eax, D0
mov     D1, eax
mov     ax, word ptr D0+2
mov     word ptr D2, ax
push    A0
call    MoveView
pop     A0
mov     esi, A0
mov     ax, [esi]
add     A0, 2
mov     hilLeftTeamGoals, ax
mov     esi, A0
mov     ax, [esi]
add     A0, 2
mov     hilRightTeamGoals, ax
call    ValidateHilPointerAdd
mov     esi, A0
mov     ax, [esi]
add     A0, 2
mov     animPatternsState, ax
mov     esi, A0
mov     ax, [esi]
add     A0, 2
mov     animPatternsState, ax
call    ValidateHilPointerAdd
push    D0
push    D1
push    D2
push    D3
push    D4
push    D5
push    D6
push    D7
push    A0
push    A1
push    A2
push    A3
push    A4
push    A5
push    A6
