cmp     D0, -1
jnz     @@next_dword
jmp     @@end_of_scene_out
; ---------------------------------------------------------------------------

@@is_sprite:        ; CODE XREF: DrawReplayFrame+18F↑j
                    ; DrawReplayFrame+3C5↓j
call    ValidateHilPointerAdd
mov     eax, D0
mov     D1, eax
mov     D3, 12
mov     cl, byte ptr D3
shl     D1, cl
mov     D3, 22
mov     cl, byte ptr D3
sar     D1, cl      ; x
mov     eax, D0
mov     D2, eax
mov     cl, byte ptr D3
shl     D2, cl
mov     cl, byte ptr D3
sar     D2, cl      ; y
mov     D3, 20
