push    A0
call    DrawSprite16Pixels
pop     A0
mov     esi, A0
mov     eax, [esi]
add     A0, 4
mov     D0, eax
cmp     D0, -1
jnz     short @@next_dword

@@end_of_scene_out: ; CODE XREF: DrawReplayFrame+307↑j
mov     replayState, 0
retn
; ---------------------------------------------------------------------------
jmp     short @@draw_result
; ---------------------------------------------------------------------------

@@next_dword:       ; CODE XREF: DrawReplayFrame+301↑j
                    ; DrawReplayFrame+3AD↑j
