mov     word ptr D0, ax
mov     esi, A0
movzx   ebx, word ptr D0
add     byte ptr [esi+ebx], 1
add     A1, size PlayerInfo
dec     word ptr D1
jns     short @@next_player
retn
CountFaces endp


