CopyAdvertisementsData proc near
                    ; CODE XREF: ConvertColorsAndTextSprites+A5↑p
mov     eax, g_spriteGraphicsPtr
mov     A2, eax     ; A2 = spriteGraphicsPtr
mov     A3, offset advert1Pointers
mov     eax, A2
add     eax, 227    ; from 227th sprite on...
add     eax, 227
add     eax, 227
add     eax, 227
