mov     word ptr D0, 7 ; D0 = counter, get 8 sprites

@@spr_ptrs_loop:    ; CODE XREF: CopyAdvertisementsData+6D↓j
mov     esi, A1
mov     eax, [esi]  ; get pointer to sprite struct
add     A1, 4       ; increment sprite pointer
mov     A0, eax     ; A0 = pointer to sprite struct
mov     esi, A0
mov     eax, [esi+SpriteGraphics.sprData] ; get pointer to sprite data
mov     esi, A3     ; esi -> advert pointer buffer
mov     [esi], eax  ; put pointer to sprite data into advert buffer
add     A3, 4       ; increment advert buffer pointer
