mov     ax, g_trainingGame
or      ax, ax
jnz     @@out       ; no commercials while training!
cmp     gameStatePl, ST_GAME_IN_PROGRESS
jz      @@game_in_progress_hide_adverts
cmp     g_cameraY, 84
jg      @@game_in_progress_hide_adverts
