mov     A6, offset advert3Pointers
mov     word ptr D1, 432
jmp     short cseg_71E77
; ---------------------------------------------------------------------------

@@second_advert:    ; CODE XREF: ManageAdvertisements+12B↑j
mov     word ptr D7, SPR_ADVERT_2_PART_1
