jz      @@finished_scrolling
jmp     short @@handle_ad_scrolling
; ---------------------------------------------------------------------------

@@start_sliding_ad: ; CODE XREF: ManageAdvertisements+1CA↑j
mov     advertSlideTimer, 40

@@handle_ad_scrolling: ; CODE XREF: ManageAdvertisements+1A2↑j
                    ; ManageAdvertisements+1B8↑j ...
mov     A0, offset advertInGameSprites
