UpdateAndApplyTeamControls proc near ; CODE XREF: GameLoop+4B5↑p
call    UpdateGameTimersAndCameraBreakMode
mov     ax, fireBlocked
or      ax, ax
jz      short @@no_stats_exit
call    Player1StatusProc
mov     al, pl1Fire
or      al, al
jnz     @@out
call    Player2StatusProc
mov     al, pl2Fire
or      al, al
jnz     @@out
mov     fireBlocked, 0
mov     pl1FireCounter, 0
mov     pl2FireCounter, 0
jmp     @@out
; ---------------------------------------------------------------------------

@@no_stats_exit:    ; CODE XREF: UpdateAndApplyTeamControls+E↑j
add     teamSwitchCounter, 1
mov     A6, offset topTeamData
test    byte ptr teamSwitchCounter, 1
jnz     short @@update_controlled_player
mov     A6, offset bottomTeamData

@@update_controlled_player: ; CODE XREF: UpdateAndApplyTeamControls+6D↑j
call    UpdateControlledPlayer
call    UpdatePlayerBeingPassedTo
mov     esi, A6     ; now pointers to current controlled player, and player getting passed to are set
mov     ax, [esi+TeamGeneralInfo.playerNumber]
mov     word ptr D0, ax
or      ax, ax
jz      @@team1_controls_done
cmp     word ptr D0, 2
jz      @@update_pl2_controls_fields
call    Player1StatusProc ; this is team controlled by player1
mov     ax, pl1Direction
mov     esi, A6
mov     [esi+TeamGeneralInfo.currentAllowedDirection], ax ; direction or -1 if nothing pressed
                    ; (changes if allowed)
mov     ax, pl1Direction
mov     esi, A6
mov     [esi+TeamGeneralInfo.direction], ax ; direction or -1 if nothing pressed
                    ; (always changes)
mov     al, pl1ShortFire
mov     esi, A6
mov     [esi+TeamGeneralInfo.fireThisFrame], al
mov     al, pl1SecondaryFire
mov     esi, A6
mov     [esi+TeamGeneralInfo.secondaryFire], al
mov     al, pl1Fire
mov     esi, A6
mov     [esi+TeamGeneralInfo.firePressed], al
or      al, al
jz      short @@reset_team1_fire_counter
mov     esi, A6     ; firing
add     [esi+TeamGeneralInfo.fireCounter], 1 ; firing this cycle, increase timer
jmp     short @@set_pl1_quick_and_normal_fire_flags
; ---------------------------------------------------------------------------

@@reset_team1_fire_counter: ; CODE XREF: UpdateAndApplyTeamControls+FE↑j
mov     esi, A6
mov     [esi+TeamGeneralInfo.fireCounter], 0 ; fire released this cycle, reset counter

@@set_pl1_quick_and_normal_fire_flags:
                    ; CODE XREF: UpdateAndApplyTeamControls+10B↑j
mov     ax, pl1FireCounter
mov     word ptr D0, ax
mov     esi, A6
mov     [esi+TeamGeneralInfo.quickFire], 0
mov     [esi+TeamGeneralInfo.normalFire], 0
or      ax, ax
jz      short @@pl1_firing_check_done
mov     esi, A6
mov     [esi+TeamGeneralInfo.quickFire], -1 ; issue quick fire, counter counted up to zero
mov     [esi+TeamGeneralInfo.normalFire], -1

@@pl1_firing_check_done: ; CODE XREF: UpdateAndApplyTeamControls+136↑j
jz      @@team1_controls_done ; out of here in any case?
js      short @@pl1_check_for_normal_fire
mov     esi, A6
mov     [esi+TeamGeneralInfo.quickFire], 0 ; counter is still counting, do not issue fire just yet (must check)
mov     [esi+TeamGeneralInfo.normalFire], 0
cmp     word ptr D0, 4
jg      short @@pl1_set_normal_fire
mov     [esi+TeamGeneralInfo.quickFire], -1
jmp     short @@reset_pl1_fire_counter
; ---------------------------------------------------------------------------

@@pl1_set_normal_fire: ; CODE XREF: UpdateAndApplyTeamControls+164↑j
mov     [esi+TeamGeneralInfo.normalFire], -1 ; issue normal fire if button is held for more than 4 ticks

@@reset_pl1_fire_counter: ; CODE XREF: UpdateAndApplyTeamControls+16A↑j
mov     pl1FireCounter, 0 ; reset it too, so it doesn't trigger again next cycle
jmp     short @@team1_controls_done
; ---------------------------------------------------------------------------

@@pl1_check_for_normal_fire:
                    ; CODE XREF: UpdateAndApplyTeamControls+14C↑j
mov     esi, A6
mov     [esi+TeamGeneralInfo.quickFire], 0 ; reset it, counter is negative, not 0 yet
mov     esi, A6
mov     al, [esi+TeamGeneralInfo.normalFire]
or      al, al
jz      short @@pl1_reset_fire
mov     esi, A6
mov     [esi+TeamGeneralInfo.normalFire], 0 ; reset normal fire in any case

@@pl1_reset_fire:   ; CODE XREF: UpdateAndApplyTeamControls+190↑j
mov     esi, A6
mov     [esi+TeamGeneralInfo.quickFire], 0
mov     esi, A6
mov     [esi+TeamGeneralInfo.normalFire], 0
cmp     word ptr D0, -4
jge     short @@pl1_no_normal_fire_yet
mov     [esi+TeamGeneralInfo.normalFire], -1

@@pl1_no_normal_fire_yet: ; CODE XREF: UpdateAndApplyTeamControls+1B8↑j
jge     short @@team1_controls_done
mov     pl1FireCounter, 0

@@team1_controls_done: ; CODE XREF: UpdateAndApplyTeamControls+96↑j
                    ; UpdateAndApplyTeamControls:@@pl1_firing_check_done↑j ...
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.resetControls]
or      ax, ax
jnz     @@out
mov     ax, g_inSubstitutesMenu
or      ax, ax
jz      short @@pl1_update_the_game
mov     esi, A6
mov     [esi+TeamGeneralInfo.currentAllowedDirection], -1 ; reset all fire types
mov     [esi+TeamGeneralInfo.quickFire], 0
mov     [esi+TeamGeneralInfo.normalFire], 0
mov     [esi+TeamGeneralInfo.firePressed], 0
mov     [esi+TeamGeneralInfo.fireThisFrame], 0
mov     [esi+TeamGeneralInfo.fireCounter], 0

@@pl1_update_the_game: ; CODE XREF: UpdateAndApplyTeamControls+1E8↑j
call    UpdatePlayers ; <------
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.headerOrTackle]
or      ax, ax
jz      @@out
mov     esi, A6
mov     [esi+TeamGeneralInfo.headerOrTackle], 0
mov     pl1FireCounter, 0
retn
; ---------------------------------------------------------------------------

@@update_pl2_controls_fields:
                    ; CODE XREF: UpdateAndApplyTeamControls+A4↑j
call    Player2StatusProc
mov     ax, pl2Direction
mov     esi, A6
mov     [esi+TeamGeneralInfo.currentAllowedDirection], ax
mov     ax, pl2Direction
mov     esi, A6
mov     [esi+TeamGeneralInfo.direction], ax
mov     al, pl2ShortFire
mov     esi, A6
mov     [esi+TeamGeneralInfo.fireThisFrame], al
mov     al, pl2SecondaryFire
mov     esi, A6
mov     [esi+TeamGeneralInfo.secondaryFire], al
mov     al, pl2Fire
mov     esi, A6
mov     [esi+TeamGeneralInfo.firePressed], al
mov     al, pl2Fire
mov     esi, A6
mov     [esi+TeamGeneralInfo.firePressed], al
or      al, al
jz      short @@reset_team2_fire_counter
mov     esi, A6
add     [esi+TeamGeneralInfo.fireCounter], 1
jmp     short @@set_pl2_quick_and_normal_fire_flags
; ---------------------------------------------------------------------------

@@reset_team2_fire_counter:
                    ; CODE XREF: UpdateAndApplyTeamControls+29C↑j
mov     esi, A6
mov     [esi+TeamGeneralInfo.fireCounter], 0

@@set_pl2_quick_and_normal_fire_flags:
                    ; CODE XREF: UpdateAndApplyTeamControls+2A9↑j
mov     ax, pl2FireCounter
mov     word ptr D0, ax
mov     esi, A6
