or      ax, ax
jz      short @@pl2_firing_check_done
mov     [esi+TeamGeneralInfo.quickFire], -1
mov     [esi+TeamGeneralInfo.normalFire], -1

@@pl2_firing_check_done: ; CODE XREF: UpdateAndApplyTeamControls+2D4↑j
jz      @@team2_controls_done
