cmp     word ptr D0, 4
mov     esi, A6
mov     [esi+TeamGeneralInfo.quickFire], 0
mov     [esi+TeamGeneralInfo.normalFire], 0
jg      short @@pl2_set_normal_fire
mov     esi, A6
mov     [esi+TeamGeneralInfo.quickFire], -1
jmp     short @@reset_pl2_fire_counter
; ---------------------------------------------------------------------------

@@pl2_set_normal_fire: ; CODE XREF: UpdateAndApplyTeamControls+2FC↑j
mov     [esi+TeamGeneralInfo.normalFire], -1

@@reset_pl2_fire_counter: ; CODE XREF: UpdateAndApplyTeamControls+308↑j
mov     pl2FireCounter, 0
jmp     short @@team2_controls_done
; ---------------------------------------------------------------------------

@@pl2_check_for_normal_fire:
                    ; CODE XREF: UpdateAndApplyTeamControls+2E4↑j
mov     esi, A6
mov     [esi+TeamGeneralInfo.quickFire], 0
mov     esi, A6
mov     al, [esi+TeamGeneralInfo.normalFire]
or      al, al
jz      short @@pl2_reset_fire
mov     esi, A6
mov     [esi+TeamGeneralInfo.normalFire], 0

@@pl2_reset_fire:   ; CODE XREF: UpdateAndApplyTeamControls+32E↑j
mov     esi, A6
mov     [esi+TeamGeneralInfo.quickFire], 0
cmp     word ptr D0, -4
mov     esi, A6
mov     [esi+TeamGeneralInfo.normalFire], 0
jge     short @@pl2_no_normal_fire_yet
