@@team2_controls_done:
                    ; CODE XREF: UpdateAndApplyTeamControls:@@pl2_firing_check_done↑j
                    ; UpdateAndApplyTeamControls+317↑j ...
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.resetControls]
or      ax, ax
jnz     short @@out
mov     ax, g_inSubstitutesMenu
or      ax, ax
jz      short @@pl2_update_the_game
mov     esi, A6
mov     [esi+TeamGeneralInfo.currentAllowedDirection], -1
mov     [esi+TeamGeneralInfo.quickFire], 0
mov     [esi+TeamGeneralInfo.normalFire], 0
mov     [esi+TeamGeneralInfo.firePressed], 0
