; =============== S U B R O U T I N E =======================================

; in:
;      A6 -> current team data
;
; Update players distance from the ball. Update controlling player if
; he's closest to the ball. Stop him if he was getting passed to.

UpdateControlledPlayer proc near
                    ; CODE XREF: UpdateAndApplyTeamControls:@@update_controlled_player↑p
mov     A2, offset ballSprite
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.x+2)]
mov     word ptr D3, ax ; D3 = ball x
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.y+2)]
mov     word ptr D4, ax ; D4 = ball y
mov     esi, A6
mov     eax, [esi+TeamGeneralInfo.spritesTable]
mov     A1, eax
mov     A3, 0       ; A3 = pointer to player closest to the ball
mov     A4, 0
mov     D5, -1      ; D5 = distance of closest player to the ball
mov     D7, -1
mov     word ptr D6, 10 ; counter (11 players)

@@players_loop:     ; CODE XREF: UpdateControlledPlayer+1E4↓j
mov     esi, A1
mov     eax, [esi]
add     A1, 4
mov     A2, eax     ; A2 -> current player sprite
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.x+2)]
mov     word ptr D1, ax
mov     ax, word ptr D3
sub     word ptr D1, ax ; D1 = player x - ball x
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.y+2)]
mov     word ptr D2, ax
mov     ax, word ptr D4
sub     word ptr D2, ax ; D2 = player y - ball y
mov     ax, word ptr D1
mov     bx, word ptr D1
imul    bx
mov     word ptr D1, ax
mov     word ptr D1+2, dx ; D1 = sqr(player x - ball x)
mov     ax, word ptr D2
mov     bx, word ptr D2
imul    bx
mov     word ptr D2, ax
mov     word ptr D2+2, dx ; D2 = sqr(player y - ball y)
mov     eax, D2
add     D1, eax     ; D1 = sqr(player x - ball x) + sqr(player y - ball y)
mov     eax, D1
mov     esi, A2
mov     [esi+Sprite.ballDistance], eax ; update player's distance from the ball
cmp     gameStatePl, ST_GAME_IN_PROGRESS
jnz     short @@check_is_player_sent_away
mov     esi, A2
mov     ax, [esi+Sprite.onScreen]
or      ax, ax
jz      @@next

@@check_is_player_sent_away: ; CODE XREF: UpdateControlledPlayer+112↑j
mov     esi, A2
mov     ax, [esi+Sprite.sentAway]
or      ax, ax
jnz     @@next
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.goaliePlayingOrOut]
or      ax, ax
jnz     short @@check_is_player_getting_pass
mov     esi, A2
cmp     [esi+Sprite.playerOrdinal], 1 ; skip goalkeeper
jz      @@next

@@check_is_player_getting_pass:
                    ; CODE XREF: UpdateControlledPlayer+147↑j
mov     esi, A6
mov     eax, [esi+TeamGeneralInfo.passingKickingPlayer]
cmp     A2, eax
jz      short @@next
nop
nop
nop
nop
mov     esi, A2     ; check if player can play at all at this moment
cmp     [esi+Sprite.playerState], PL_TACKLING
jz      short @@next
mov     esi, A2
cmp     [esi+Sprite.playerState], PL_TACKLED
jz      short @@next
mov     esi, A2
cmp     [esi+Sprite.playerState], PL_JUMP_HEADING
jz      short @@next
mov     esi, A2
cmp     [esi+Sprite.playerState], PL_STATIC_HEADING
jz      short @@next
mov     esi, A2
cmp     [esi+Sprite.playerState], PL_ROLLING_INJURED
jz      short @@next
mov     esi, A6
mov     eax, [esi+TeamGeneralInfo.passToPlayerPtr]
cmp     A2, eax
jz      short @@next
mov     eax, D5     ; D5 = closest distance so far
cmp     D1, eax     ; D1 = distance of current player from the ball
jnb     short @@next
mov     eax, D1     ; we have new closest distance
mov     D5, eax
mov     eax, A2
mov     A3, eax     ; A3 -> closest active player to the ball

@@next:             ; CODE XREF: UpdateControlledPlayer+121↑j
                    ; UpdateControlledPlayer+134↑j ...
dec     word ptr D6
jns     @@players_loop
mov     ax, playingPenalties
or      ax, ax
jz      short @@check_closest_active_player
cmp     gameStatePl, ST_GAME_IN_PROGRESS
jz      @@out

@@check_closest_active_player: ; CODE XREF: UpdateControlledPlayer+1F3↑j
cmp     A3, 0
jz      @@out
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.ballOutOfPlay]
or      ax, ax
jz      @@out
mov     esi, A6     ; ball is out of play here
mov     eax, [esi+TeamGeneralInfo.controlledPlayer]
cmp     A3, eax
jz      short @@its_controlled_player
push    A3          ; it's not controlled player, we need to update
mov     esi, A6
mov     eax, [esi+TeamGeneralInfo.controlledPlayer]
mov     A3, eax     ; A3 is now old controlled player
cmp     A3, 0
jz      short @@no_old_controlling_player
mov     esi, A3
cmp     [esi+Sprite.playerState], PL_NORMAL
jnz     short @@no_old_controlling_player
mov     esi, A3     ; stop player that was controlled so far
mov     ax, word ptr [esi+(Sprite.x+2)]
mov     esi, A3
mov     [esi+Sprite.destX], ax
mov     esi, A3
mov     ax, word ptr [esi+(Sprite.y+2)]
mov     esi, A3
mov     [esi+Sprite.destY], ax

@@no_old_controlling_player: ; CODE XREF: UpdateControlledPlayer+24F↑j
                    ; UpdateControlledPlayer+25B↑j
pop     A3

@@its_controlled_player: ; CODE XREF: UpdateControlledPlayer+232↑j
mov     eax, A3     ; set new controlled player
mov     esi, A6
mov     [esi+TeamGeneralInfo.controlledPlayer], eax
mov     esi, A6
mov     eax, [esi+TeamGeneralInfo.passToPlayerPtr]
cmp     A3, eax
jnz     short @@out
push    A3          ; new player we're controlling has an incoming pass
mov     esi, A6
mov     eax, [esi+TeamGeneralInfo.passToPlayerPtr]
mov     A3, eax
cmp     A3, 0
jz      short @@noone_getting_that_pass
mov     esi, A3
cmp     [esi+Sprite.playerState], PL_NORMAL
jnz     short @@noone_getting_that_pass
mov     esi, A3     ; stop him, so he can take the pass
mov     ax, word ptr [esi+(Sprite.x+2)]
mov     esi, A3
mov     [esi+Sprite.destX], ax
mov     esi, A3
mov     ax, word ptr [esi+(Sprite.y+2)]
mov     esi, A3
mov     [esi+Sprite.destY], ax

@@noone_getting_that_pass: ; CODE XREF: UpdateControlledPlayer+2C5↑j
                    ; UpdateControlledPlayer+2D1↑j
pop     A3
mov     esi, A6
mov     [esi+TeamGeneralInfo.passToPlayerPtr], 0

@@out:              ; CODE XREF: UpdateControlledPlayer+1FD↑j
                    ; UpdateControlledPlayer+20A↑j ...
retn
UpdateControlledPlayer endp


; =============== S U B R O U T I N E =======================================

; in:
;      A6 -> team data
;
; Find closest player being passed to and update passToPlayerPtr.
; Stop him so he can get the pass if game is running, do not if game is stopped.

UpdatePlayerBeingPassedTo proc near
                    ; CODE XREF: UpdateAndApplyTeamControls+7E↑p
cmp     gameStatePl, ST_GAME_IN_PROGRESS
jnz     @@game_stopped
mov     A2, offset ballSprite ; game is running
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.x+2)]
mov     esi, A6
mov     [esi+TeamGeneralInfo.ballX], ax
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.y+2)]
mov     esi, A6
mov     [esi+TeamGeneralInfo.ballY], ax ; update ball coordinates in team
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.ballInPlay]
or      ax, ax
jz      @@out
mov     esi, A6     ; do it only if ball in play
mov     ax, [esi+TeamGeneralInfo.playerSwitchTimer]
or      ax, ax
jnz     @@out
mov     esi, A6     ; do it only if controlled player has "stabilized" AND ball is in play
mov     ax, [esi+TeamGeneralInfo.passingToPlayer]
or      ax, ax
jz      short @@ball_in_pass
mov     esi, A6
mov     eax, [esi+TeamGeneralInfo.passToPlayerPtr]
or      eax, eax
jnz     @@out       ; go out if there is already a player being passed to, that's temporary controlled by cpu

@@ball_in_pass:     ; CODE XREF: UpdatePlayerBeingPassedTo+73↑j
mov     ax, playingPenalties
or      ax, ax
jz      short @@not_playing_penalties
cmp     gameStatePl, ST_PENALTIES
jnz     @@out
mov     eax, penaltyShooterSprite
mov     A3, eax     ; closest player to ball = penalty shooter
mov     esi, A6
mov     [esi+TeamGeneralInfo.ballInPlay], 0
jmp     @@skip_searching_for_closest_player
; ---------------------------------------------------------------------------

@@not_playing_penalties: ; CODE XREF: UpdatePlayerBeingPassedTo+8F↑j
mov     esi, A6
mov     eax, [esi+TeamGeneralInfo.spritesTable]
mov     A1, eax
mov     A2, offset ballSprite
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.x+2)]
mov     word ptr D3, ax ; D3 = ball x
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.y+2)]
mov     word ptr D4, ax ; D4 = ball y
mov     A3, 0       ; A3 = ptr to closest (not controlled) player to the ball
mov     A4, 0
mov     D5, 0FFFFFFFFh ; D5 = least player distance to the ball, init to max dword
mov     D7, -1
mov     word ptr D6, 10 ; loop counter

@@find_closest_player_loop: ; CODE XREF: UpdatePlayerBeingPassedTo+1DD↓j
mov     esi, A1
mov     eax, [esi]
add     A1, 4
mov     A2, eax     ; A2 -> current player sprite
mov     esi, A2
mov     ax, [esi+Sprite.onScreen]
or      ax, ax
jz      @@next
mov     esi, A2
mov     ax, [esi+Sprite.sentAway]
or      ax, ax
jnz     short @@next
nop                 ; player must be drawn in previous cycle, and not sent away
nop
nop
nop
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.ballOutOfPlayOrKeeper]
or      ax, ax
