; Foul has been conceeded. Set referee x, y, speed and destination
; coordinates. Referee comes from above or below screen, depending on
; current camera position. X coordinate is card coordinate +/- 0..7, sign
; depends on which vertical half camera is in.

ActivateReferee proc near ; CODE XREF: PlayerTacklingTestFoul+4B5↓p
                    ; PlayerTacklingTestFoul+4E2↓p
mov     A0, offset refereeSprite
mov     ax, foulXCoordinate
mov     word ptr D1, ax
mov     ax, foulYCoordinate
mov     word ptr D2, ax
add     word ptr D1, 28
add     word ptr D2, 5 ; a bit right and below the foul spot
mov     ax, word ptr D1
mov     esi, A0
mov     [esi+Sprite.destX], ax
mov     ax, word ptr D2
mov     esi, A0
mov     [esi+Sprite.destY], ax ; set referee destination
call    Rand
shr     word ptr D0, 3 ; get random number 0..31
cmp     foulXCoordinate, 336 ; half of pitch by x
jb      short @@check_half_pitch_y
neg     word ptr D0

@@check_half_pitch_y: ; CODE XREF: ActivateReferee+68↑j
mov     ax, g_cameraY ; set referee y above/below screen
mov     word ptr D2, ax
sub     word ptr D2, 20
cmp     foulYCoordinate, 449 ; half of pitch by y
ja      short @@add_randomness
mov     ax, g_cameraY
mov     word ptr D2, ax
add     word ptr D2, 215

@@add_randomness:   ; CODE XREF: ActivateReferee+8E↑j
mov     ax, word ptr D0 ; add +/- 0..31 to x coordinate
add     word ptr D1, ax
mov     ax, word ptr D1
mov     esi, A0
mov     word ptr [esi+(Sprite.x+2)], ax
mov     ax, word ptr D2
mov     esi, A0
mov     word ptr [esi+(Sprite.y+2)], ax
mov     esi, A0
mov     word ptr [esi+Sprite.x], 0
mov     esi, A0
mov     word ptr [esi+Sprite.y], 0
mov     ax, kRefereeSpeed
mov     esi, A0
mov     [esi+Sprite.speed], ax
mov     esi, A0
mov     [esi+Sprite.visible], 1
call    InitDisplaySprites
mov     A1, offset refComingAnimTable
call    InitRefereeAnimationTable
mov     refState, REF_INCOMING
retn
ActivateReferee endp


