; in:
;      A0 -> player
;
; globals:
;   read:
;     goalScored
;     lastTeamScoredPtr
;     playerScoredPtr
;     currentGameTick
;
; Sets next picture frame for players. Also takes care of cheering after
; scored goal.

SetNextPlayerFrame proc near ; CODE XREF: MovePlayers+27↑p
mov     esi, A0
mov     ax, [esi+Sprite.onScreen]
or      ax, ax
jz      @@out
mov     esi, A0
sub     [esi+Sprite.cycleFramesTimer], 1
jnz     @@out       ; nothing to do before cycle frames timer elapses
mov     esi, A0     ; after timer cycles once, increase frame index
add     [esi+Sprite.frameIndex], 1 ; advance to next frame
mov     esi, A0
mov     ax, [esi+Sprite.frameDelay]
mov     esi, A0
mov     [esi+Sprite.cycleFramesTimer], ax ; reset timer
mov     esi, A0
mov     eax, [esi+Sprite.frameIndicesTable]
mov     A1, eax

@@next_frame_index: ; CODE XREF: SetNextPlayerFrame+D9↓j
                    ; SetNextPlayerFrame+EA↓j ...
mov     esi, A0
mov     ax, [esi+Sprite.frameIndex]
mov     word ptr D0, ax
shl     word ptr D0, 1
mov     esi, A1
movzx   ebx, word ptr D0
mov     ax, [esi+ebx]
mov     word ptr D0, ax ; D0 = next frame sprite index
or      ax, ax
jns     @@bump_swith_counter
cmp     word ptr D0, -999 ; (kLastFrameLoopMarker)
jz      short @@reset_index ; we reached end of table, start again from the beginning
cmp     word ptr D0, -101 ; (kLastFrameHoldMarker)
jz      short @@pause_frame ; show the current frame again (undo the increment)
cmp     word ptr D0, -100 ; (kFrameLoopbackMarker)
jle     short @@add_negative_offset
neg     word ptr D0 ; -99..-1 => 1..99
mov     ax, word ptr D0 ; this represents our new frame delay
mov     esi, A0
mov     [esi+Sprite.frameDelay], ax
mov     ax, word ptr D0
mov     esi, A0
mov     [esi+Sprite.cycleFramesTimer], ax
mov     esi, A0     ; set delay and timer vars and go to next frame index
add     [esi+Sprite.frameIndex], 1
jmp     @@next_frame_index
; ---------------------------------------------------------------------------

@@reset_index:      ; CODE XREF: SetNextPlayerFrame+91↑j
mov     esi, A0
mov     [esi+Sprite.frameIndex], 0
jmp     @@next_frame_index
; ---------------------------------------------------------------------------

@@add_negative_offset: ; CODE XREF: SetNextPlayerFrame+A5↑j
add     word ptr D0, 100 ; -100, -101, -102... => 0, -1, -2...
mov     ax, word ptr D0 ; frame index offset (for partial animation loops)
mov     esi, A0
add     [esi+Sprite.frameIndex], ax
jmp     @@next_frame_index
; ---------------------------------------------------------------------------

@@pause_frame:      ; CODE XREF: SetNextPlayerFrame+9B↑j
mov     esi, A0
sub     [esi+Sprite.frameIndex], 1
jmp     @@out
; ---------------------------------------------------------------------------

@@bump_swith_counter: ; CODE XREF: SetNextPlayerFrame+82↑j
mov     esi, A0     ; D0 will be the next picture index
add     [esi+Sprite.frameSwitchCounter], 1
mov     esi, A0
mov     ax, [esi+Sprite.frameOffset]
add     word ptr D0, ax
mov     ax, goalScored
or      ax, ax
jz      @@set_picture_index
mov     esi, A0     ; goal scored
cmp     [esi+Sprite.playerState], PL_NORMAL
jnz     @@set_picture_index
mov     esi, A0     ; goal is scored, and player is in normal state
mov     ax, [esi+Sprite.direction]
or      ax, ax
jz      short @@player_facing_up_or_down
mov     esi, A0
cmp     [esi+Sprite.direction], 4
jnz     @@set_picture_index

@@player_facing_up_or_down: ; CODE XREF: SetNextPlayerFrame+164↑j
mov     ax, lastTeamScoredNumber
mov     word ptr D1, ax
mov     esi, A0
mov     ax, [esi+Sprite.teamNumber]
cmp     word ptr D1, ax
jnz     @@set_picture_index
mov     esi, A0     ; player is from team that scored
cmp     [esi+Sprite.playerOrdinal], 1
jz      short @@set_picture_index
nop                 ; and is not a keeper
nop
nop
nop
mov     eax, lastPlayerScored
cmp     A0, eax
jnz     short @@not_the_player_that_scored
mov     ax, currentGameTick ; this player scored
mov     word ptr D1, ax
and     word ptr D1, 7Fh
cmp     word ptr D1, 100 ; cheering 78.90625% of time
ja      short @@set_picture_index
jmp     short @@make_player_cheer
; ---------------------------------------------------------------------------

@@not_the_player_that_scored: ; CODE XREF: SetNextPlayerFrame+1B5↑j
mov     esi, A0
mov     ax, [esi+Sprite.playerOrdinal]
mov     word ptr D1, ax
shl     word ptr D1, 2
mov     ax, currentGameTick
add     word ptr D1, ax
and     word ptr D1, 3Fh
cmp     word ptr D1, 31 ; cheering 50% of time
ja      short @@set_picture_index

@@make_player_cheer: ; CODE XREF: SetNextPlayerFrame+1D5↑j
add     word ptr D0, 365
sub     word ptr D0, 341

@@set_picture_index: ; CODE XREF: SetNextPlayerFrame+141↑j
                    ; SetNextPlayerFrame+151↑j ...
mov     ax, word ptr D0
mov     esi, A0
mov     [esi+Sprite.imageIndex], ax

@@out:              ; CODE XREF: SetNextPlayerFrame+D↑j
                    ; SetNextPlayerFrame+1E↑j ...
retn
SetNextPlayerFrame endp


