; in:
;      A0 -> player
;
; globals:
;   read:
;      gameStatePl
;      breakCameraMode
;
; Update x and y coordinates based on deltas. If sprite has reached its
; destination stop it, and set standing animation table.

MovePlayer proc near ; CODE XREF: MovePlayers+2C↑p
mov     esi, A0
mov     ax, [esi+Sprite.onScreen]
or      ax, ax
jz      @@havent_been_drawn

@@check_delta_x:    ; CODE XREF: MovePlayer+1E9↓j
mov     esi, A0
mov     eax, [esi+Sprite.deltaX]
mov     D0, eax
or      eax, eax
jz      @@check_delta_y
jns     short @@moving_right
mov     esi, A0     ; moving left
mov     ax, [esi+Sprite.destX]
mov     word ptr D1, ax
mov     eax, D0
mov     esi, A0
add     [esi+Sprite.x], eax ; x += delta x
mov     esi, A0
mov     ax, word ptr [esi+(Sprite.x+2)]
cmp     word ptr D1, ax ; if dest x is less than x, sprite is still moving
jl      short @@check_delta_y

@@x_axis_on_destination: ; CODE XREF: MovePlayer+AA↓j
mov     ax, word ptr D1
mov     esi, A0
mov     word ptr [esi+(Sprite.x+2)], ax
mov     esi, A0
mov     [esi+Sprite.deltaX], 0 ; set delta x to 0 if reached destination
jmp     short @@check_delta_y
; ---------------------------------------------------------------------------

@@moving_right:     ; CODE XREF: MovePlayer+29↑j
mov     esi, A0
mov     ax, [esi+Sprite.destX]
mov     word ptr D1, ax
mov     eax, D0
mov     esi, A0
add     [esi+Sprite.x], eax ; x += delta x
mov     esi, A0
mov     ax, word ptr [esi+(Sprite.x+2)]
cmp     word ptr D1, ax ; if dest x is greater than x, sprite is still moving
jle     short @@x_axis_on_destination

@@check_delta_y:    ; CODE XREF: MovePlayer+23↑j MovePlayer+5A↑j ...
mov     esi, A0
mov     eax, [esi+Sprite.deltaY]
mov     D0, eax
or      eax, eax
jz      @@check_player_state
jns     short @@moving_down
mov     esi, A0     ; moving up
mov     ax, [esi+Sprite.destY]
mov     word ptr D1, ax
mov     eax, D0
mov     esi, A0
add     [esi+Sprite.y], eax ; y += delta y
mov     esi, A0
mov     ax, word ptr [esi+(Sprite.y+2)]
cmp     word ptr D1, ax
jl      @@out2

@@reached_y_dest:   ; CODE XREF: MovePlayer+147↓j
mov     ax, word ptr D1 ; if we reached y destination (equal or greater), stop
mov     esi, A0
mov     word ptr [esi+(Sprite.y+2)], ax
mov     esi, A0
mov     [esi+Sprite.deltaY], 0
jmp     short @@check_player_state
; ---------------------------------------------------------------------------

@@moving_down:      ; CODE XREF: MovePlayer+C2↑j
mov     esi, A0
mov     ax, [esi+Sprite.destY]
mov     word ptr D1, ax
mov     eax, D0
mov     esi, A0
add     [esi+Sprite.y], eax ; y += delta y
mov     esi, A0
mov     ax, word ptr [esi+(Sprite.y+2)]
cmp     word ptr D1, ax
jle     short @@reached_y_dest

@@check_player_state: ; CODE XREF: MovePlayer+BC↑j MovePlayer+116↑j
mov     esi, A0
cmp     [esi+Sprite.playerState], PL_NORMAL
jnz     @@out2
mov     esi, A0
mov     eax, [esi+Sprite.deltaX]
or      eax, eax
jnz     short @@out2
nop
nop
nop
nop
mov     esi, A0
mov     eax, [esi+Sprite.deltaY]
or      eax, eax
jnz     short @@out2
cmp     gameStatePl, ST_GAME_IN_PROGRESS ; player must be in normal state, and not moving
jz      short @@update_animation_table
cmp     breakCameraMode, 3
jnz     short @@update_animation_table
mov     esi, A0
cmp     [esi+Sprite.destReachedState], 2
jnz     short @@update_animation_table
mov     esi, A0     ; if game not in progress and breakCameraMode is 3 and we had value 2 here, set it to 3
mov     [esi+Sprite.destReachedState], 3

@@update_animation_table: ; CODE XREF: MovePlayer+17F↑j
                    ; MovePlayer+189↑j ...
mov     esi, A0     ; since player is standing at this point, assign corresponding anim table
cmp     [esi+Sprite.animationTable], offset playerNormalStandingAnimTable
jz      short @@out2 ; return if already set
mov     eax, A0
mov     A1, eax     ; A1 must point to sprite
mov     eax, A0
mov     A4, eax     ; save
mov     A0, offset playerNormalStandingAnimTable
call    SetPlayerAnimationTable
mov     eax, A4
mov     A0, eax

@@out2:             ; CODE XREF: MovePlayer+F3↑j MovePlayer+153↑j ...
retn
; ---------------------------------------------------------------------------

@@havent_been_drawn: ; CODE XREF: MovePlayer+D↑j
cmp     gameStatePl, ST_GAME_IN_PROGRESS
jnz     @@check_delta_x
mov     esi, A0
mov     ax, [esi+Sprite.destX]
mov     word ptr D1, ax
mov     esi, A0
mov     eax, [esi+Sprite.deltaX]
mov     D0, eax
or      eax, eax
jz      short @@check_dest_y
jns     short @@moving_right2
mov     eax, D0     ; moving left
mov     esi, A0
add     [esi+Sprite.x], eax
mov     esi, A0
mov     ax, word ptr [esi+(Sprite.x+2)]
cmp     word ptr D1, ax
jl      short @@check_dest_y

@@not_moving_on_x_axis: ; CODE XREF: MovePlayer+272↓j
mov     ax, word ptr D1
mov     esi, A0
mov     word ptr [esi+(Sprite.x+2)], ax
mov     esi, A0
mov     [esi+Sprite.deltaX], 0
jmp     short @@check_dest_y
; ---------------------------------------------------------------------------

@@moving_right2:    ; CODE XREF: MovePlayer+211↑j
mov     eax, D0
mov     esi, A0
add     [esi+Sprite.x], eax
mov     esi, A0
mov     ax, word ptr [esi+(Sprite.x+2)]
cmp     word ptr D1, ax
jle     short @@not_moving_on_x_axis

@@check_dest_y:     ; CODE XREF: MovePlayer+20F↑j MovePlayer+232↑j ...
mov     esi, A0
mov     ax, [esi+Sprite.destY]
mov     word ptr D1, ax
mov     esi, A0
mov     eax, [esi+Sprite.deltaY]
mov     D0, eax
or      eax, eax
jz      short @@out
jns     short @@moving_down2
mov     eax, D0     ; moving up
mov     esi, A0
add     [esi+Sprite.y], eax
mov     esi, A0
mov     ax, word ptr [esi+(Sprite.y+2)]
cmp     word ptr D1, ax
jl      short @@out

@@reached_y_dest2:  ; CODE XREF: MovePlayer+2F7↓j
mov     ax, word ptr D1
mov     esi, A0
mov     word ptr [esi+(Sprite.y+2)], ax
mov     esi, A0
mov     [esi+Sprite.deltaY], 0
jmp     short @@out
; ---------------------------------------------------------------------------

@@moving_down2:     ; CODE XREF: MovePlayer+296↑j
mov     eax, D0
mov     esi, A0
add     [esi+Sprite.y], eax
mov     esi, A0
mov     ax, word ptr [esi+(Sprite.y+2)]
cmp     word ptr D1, ax
jle     short @@reached_y_dest2

@@out:              ; CODE XREF: MovePlayer+294↑j MovePlayer+2B7↑j ...
retn
MovePlayer endp


