; =============== S U B R O U T I N E =======================================

; Display "endless" strip of images, scrolling bottom to top. Use buffer 3 images large,
; images 0 and 2 are empty and real images is in spot 1. Scrolling window is 2 images high,
; soon as it scrolls out we load new image to spot 2 and restart, it looks seamless.
;
; returns: 0 - finished naturally (and zf set)
;          1 - aborted

ShowLoader1AndOne256 proc near ; CODE XREF: SWOS+2A↑p
mov     ebx, offset partOneImages
jmp     short $+2
ShowLoader1AndOne256 endp


; =============== S U B R O U T I N E =======================================

; in:
;     ebx -> list of pointers to images to show, terminated with -1

ShowPictures proc near ; CODE XREF: ShowRestOfPics+5↑j
                    ; ShowLoader1AndOne256+5↑j
mov     edi, 0A0000h ; video buffer
mov     ecx, 16000  ; 64kb
xor     eax, eax
rep stosd           ; clear screen
mov     edi, linAdr384k
mov     ecx, 192000 ; clear 3 images worth of buffer space
xor     al, al
rep stosb
push    ebx
mov     eax, [ebx]
mov     A0, eax
mov     eax, linAdr384k
mov     A1, eax
call    LoadFile    ; load first image into buffer, spot 1 will remain empty
mov     esi, linAdr384k
add     esi, 64000
mov     ecx, 768    ; apply palette from picture 1
mov     edi, offset g_workingPalette
rep movsb
mov     edi, linAdr384k
mov     ecx, 192000
xor     al, al
rep stosb           ; clear 3 images worth of buffer space again
call    FadeIn      ; fade in picture palette
                    ; note: palette from first picture is used
                    ; throughout the intro, rest are ignored
pop     edi
mov     eax, linAdr384k
add     eax, 64000
mov     A1, eax     ; A1 -> image 2 spot in buffer

@@draw_picture_loop: ; CODE XREF: ShowPictures+FE↓j
mov     eax, [edi]  ; edi is pointing to table of pointers to file names
cmp     eax, -1     ; getting picture names, until -1
                    ; (that's terminating char)
jz      @@exit
mov     A0, eax
push    edi
call    LoadFile
mov     edi, linAdr384k
add     edi, 128000 ; load current image to 2nd spot in buffer
mov     ecx, 768
xor     al, al
rep stosb           ; zero out loaded image palette
mov     currentLine, 0
mov     ecx, 400    ; scroll 400 lines (= 2 images) before moving on to next image
                    ; (image + empty area the size of image)

@@scroll_image_loop: ; CODE XREF: ShowPictures+F8↓j
push    ecx
cli
mov     dx, 3DAh    ; waiting retrace here

@@wait_retrace_end: ; CODE XREF: ShowPictures+B3↓j
in      al, dx      ; Video status bits:
                    ; 0: retrace.  1=display is in vert or horiz retrace.
                    ; 1: 1=light pen is triggered; 0=armed
                    ; 2: 1=light pen switch is open; 0=closed
                    ; 3: 1=vertical sync pulse is occurring.
and     al, 8
jnz     short @@wait_retrace_end
mov     dx, 3DAh

@@wait_retrace_start: ; CODE XREF: ShowPictures+BC↓j
in      al, dx      ; Video status bits:
                    ; 0: retrace.  1=display is in vert or horiz retrace.
                    ; 1: 1=light pen is triggered; 0=armed
                    ; 2: 1=light pen switch is open; 0=closed
                    ; 3: 1=vertical sync pulse is occurring.
and     al, 8
jz      short @@wait_retrace_start
sti
mov     esi, linAdr384k
add     esi, currentLine
mov     edi, 0A0000h
mov     ecx, 16000
rep movsd           ; draw screen moved by one line
add     currentLine, 320
call    JoyKeyOrCtrlPressed ; check user input
jz      short @@draw_next
pop     ecx         ; interrupting intro
pop     edi
call    FadeOutToBlack ; blackout
mov     ax, 1       ; return 1, intro interrupted
or      ax, ax
retn
; ---------------------------------------------------------------------------

@@draw_next:        ; CODE XREF: ShowPictures+E6↑j
pop     ecx
loop    @@scroll_image_loop ; draw next line
pop     edi
add     edi, 4
jmp     @@draw_picture_loop ; draw next picture
; ---------------------------------------------------------------------------

@@exit:             ; CODE XREF: ShowPictures+75↑j
call    FadeOutToBlack ; blackout
xor     ax, ax      ; 0 - intro ended without interruption
retn
ShowPictures endp

