; in:
;      A0 -> animation table
;      A1 -> player
;
; Sets player's animation table and frame indices table and sets up starting state.
; Frames table pointer must be present, or the game crashes. If some animation table
; is too short, make sure it's never called with inaccessible players/goalkeepers.

SetPlayerAnimationTable proc near
                    ; CODE XREF: CheckForThrowInAndGoalkeepersBall+4A↑p
                    ; UpdateGameTimersAndCameraBreakMode+8E3↑p ...
mov     eax, A0
mov     esi, A1
mov     [esi+Sprite.animationTable], eax ; set animation table
push    small [word ptr D0]
mov     esi, A1
mov     ax, [esi+Sprite.teamNumber]
mov     word ptr D0, ax
sub     word ptr D0, 1 ; index by team, value is 0 or 1
mov     esi, A1
cmp     [esi+Sprite.playerOrdinal], 1
jnz     short @@not_goalkeeper
add     word ptr D0, 2

@@not_goalkeeper:   ; CODE XREF: SetPlayerAnimationTable+37↑j
shl     word ptr D0, 3 ; 0 = player team 1
                    ; 1 = player team 2
                    ; 2 = goalkeeper team 1
                    ; 3 = goalkeeper team 2
mov     esi, A1
mov     ax, [esi+Sprite.direction] ; direction is 0..7
add     word ptr D0, ax
shl     word ptr D0, 2 ; offset = 32 * playerTeam + 4 * direction
mov     esi, A0
mov     ax, [esi]   ; first word is frame delay
mov     esi, A1
mov     [esi+Sprite.frameDelay], ax
mov     esi, A0
movzx   ebx, word ptr D0
mov     eax, [esi+ebx+2] ; frame indices pointers begin from offset 2 in the animation table
mov     esi, A1
mov     [esi+Sprite.frameIndicesTable], eax
or      eax, eax
jz      short @@fatal_error
mov     esi, A1
mov     [esi+Sprite.frameSwitchCounter], -1
mov     esi, A1
mov     [esi+Sprite.frameIndex], -1
mov     esi, A1
mov     [esi+Sprite.cycleFramesTimer], 1
mov     esi, A1
mov     ax, [esi+Sprite.direction]
mov     esi, A1
mov     [esi+Sprite.startingDirection], ax
pop     small [word ptr D0]
retn
; ---------------------------------------------------------------------------

@@fatal_error:      ; CODE XREF: SetPlayerAnimationTable+91↑j
int     3           ; Trap to Debugger

@@endless_loop:     ; CODE XREF: SetPlayerAnimationTable:@@endless_loop↓j
jmp     short @@endless_loop
SetPlayerAnimationTable endp


