mov     word ptr D0, ax
mov     ax, team2PenaltyAttempts
cmp     word ptr D0, ax
jnz     @@next_penalty
mov     ax, team1PenaltyGoals
mov     word ptr D0, ax
mov     ax, team2PenaltyGoals
cmp     word ptr D0, ax
jz      @@next_penalty

