sub     word ptr D0, ax
mov     ax, team1PenaltyGoals
add     word ptr D0, ax
mov     ax, team2PenaltyGoals
cmp     word ptr D0, ax
jb      short @@finish_penalties
mov     word ptr D0, 5
mov     ax, team2PenaltyAttempts
sub     word ptr D0, ax
mov     ax, team2PenaltyGoals
add     word ptr D0, ax
mov     ax, team1PenaltyGoals
cmp     word ptr D0, ax
jb      @@finish_penalties

