add     teamPlayingUp, 3
neg     teamStarting
add     teamStarting, 3
mov     hideBall, 0
call    InitTeamsData
mov     gameState, ST_PENALTIES
mov     breakCameraMode, -1
mov     cameraDirection, 0 ; north
mov     byte ptr playerTurnFlags, 83h ; allow only NW, N, NE
mov     foulXCoordinate, 336 ; upper white spot
mov     foulYCoordinate, 187
mov     gameStatePl, 101
mov     gameNotInProgressCounterWriteOnly, 0
mov     A6, offset bottomTeamData
mov     eax, A6
mov     lastTeamPlayedBeforeBreak, eax
mov     stoppageTimerTotal, 0
mov     stoppageTimerActive, 0
