; =============== S U B R O U T I N E =======================================

; in:
;      A6 -> team data
;
; Apply "after effects" to pass/kick. Apply spin if player holding left/right
; directions, and high kick if player holding back direction. Also update ball
; for normal kicks too. Slow down ball after kick/pass.

ApplyBallAfterTouch proc near
                    ; CODE XREF: UpdatePlayers:@@apply_after_touch_and_set_ball_location_flags↓p
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.passInProgress]
or      ax, ax
jnz     @@passing_now
mov     esi, A6     ; pass not in progress, so it's a kick
mov     eax, [esi+TeamGeneralInfo.opponentsTeam]
mov     A0, eax
mov     esi, A0
mov     ax, [esi+TeamGeneralInfo.goalkeeperSavedCommentTimer]
or      ax, ax
js      @@reset_spin_timer_out
cmp     gameStatePl, ST_GAME_IN_PROGRESS
jz      short @@game_in_progress
cmp     gameState, ST_KEEPER_HOLDS_BALL
jz      @@reset_spin_timer_out

@@game_in_progress: ; CODE XREF: ApplyBallAfterTouch+3E↑j
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.spinTimer]
mov     word ptr D0, ax
or      ax, ax
js      @@out
jnz     short @@accepting_spin
mov     esi, A6
mov     [esi+TeamGeneralInfo.leftSpin], 0
mov     esi, A6
mov     [esi+TeamGeneralInfo.rightSpin], 0

@@accepting_spin:   ; CODE XREF: ApplyBallAfterTouch+67↑j
mov     A1, offset ballSprite
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.leftSpin]
or      ax, ax
jnz     @@already_spining_left
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.rightSpin]
or      ax, ax
jnz     short @@already_spining_right
mov     esi, A6     ; calculate is it left or right spin
mov     ax, [esi+TeamGeneralInfo.currentAllowedDirection]
mov     word ptr D1, ax
or      ax, ax
js      @@not_starting_spin ; player not holding any direction, no spin for now
mov     esi, A6     ; player pressing some direction
mov     ax, [esi+TeamGeneralInfo.controlledPlDirection]
mov     word ptr D0, ax
mov     ax, word ptr D1
sub     word ptr D0, ax
jz      @@not_starting_spin
and     word ptr D0, 7
cmp     word ptr D0, 4
jz      @@not_starting_spin
jb      short @@spin_left ; some direction is pressed on controller, except same and opposite directions, so start up the spin
mov     esi, A6
mov     [esi+TeamGeneralInfo.rightSpin], 1

@@already_spining_right: ; CODE XREF: ApplyBallAfterTouch+AB↑j
mov     D1, 4
jmp     short @@calculate_initial_spin
; ---------------------------------------------------------------------------

@@spin_left:        ; CODE XREF: ApplyBallAfterTouch+FF↑j
mov     esi, A6
mov     [esi+TeamGeneralInfo.leftSpin], 1

@@already_spining_left: ; CODE XREF: ApplyBallAfterTouch+98↑j
mov     word ptr D1, 0

@@calculate_initial_spin: ; CODE XREF: ApplyBallAfterTouch+117↑j
mov     esi, A6     ; D1 = 0 for left spin, 4 for right spin, also spin left/right flags set by now
mov     ax, [esi+TeamGeneralInfo.controlledPlDirection]
mov     word ptr D0, ax
mov     A0, offset kKickSpinFactor
shl     word ptr D0, 3
mov     ax, word ptr D1
add     word ptr D0, ax
mov     A2, offset kSpinMultiplierFactor
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.spinTimer]
mov     word ptr D2, ax
shl     word ptr D2, 1
mov     esi, A2
movzx   ebx, word ptr D2
mov     ax, [esi+ebx]
mov     word ptr D2, ax
mov     esi, A0
movzx   ebx, word ptr D0
mov     ax, [esi+ebx]
mov     word ptr D1, ax
mov     ax, word ptr D1
imul    word ptr D2
mov     word ptr D1, ax
mov     word ptr D1+2, dx
mov     ax, word ptr D1
mov     esi, A1     ; A1 -> ball sprite
add     [esi+Sprite.destX], ax ; apply x axis spin
mov     esi, A0
movzx   ebx, word ptr D0
mov     ax, [esi+ebx+2]
mov     word ptr D1, ax
mov     ax, word ptr D1
imul    word ptr D2
mov     word ptr D1, ax
mov     word ptr D1+2, dx
mov     ax, word ptr D1
mov     esi, A1
add     [esi+Sprite.destY], ax ; apply y axis spin

@@not_starting_spin: ; CODE XREF: ApplyBallAfterTouch+C0↑j
                    ; ApplyBallAfterTouch+E3↑j ...
mov     esi, A6
cmp     [esi+TeamGeneralInfo.spinTimer], 4
jnz     @@increase_spin_timer
mov     esi, A6     ; spin time = 4 here, check for high kick
mov     ax, [esi+TeamGeneralInfo.currentAllowedDirection]
mov     word ptr D1, ax
or      ax, ax
js      short @@normal_not_high_kick
nop
nop
nop
nop
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.controlledPlDirection]
mov     word ptr D0, ax
mov     ax, word ptr D1
sub     word ptr D0, ax
jz      short @@jmp_increase_spin_timer
nop
nop
nop
nop
and     word ptr D0, 7
cmp     word ptr D0, 2
jz      short @@normal_not_high_kick
cmp     word ptr D0, 6
jz      short @@normal_not_high_kick
cmp     word ptr D0, 3
jb      short @@jmp_increase_spin_timer
cmp     word ptr D0, 5
ja      short @@jmp_increase_spin_timer
mov     eax, kHighKickDeltaZ ; only if player is holding back+left/back/back+right
mov     esi, A1
mov     [esi+Sprite.deltaZ], eax
mov     ax, kHighKickBallSpeed
mov     esi, A1
mov     [esi+Sprite.speed], ax
jmp     short @@do_some_speed_adjustment
; ---------------------------------------------------------------------------

@@normal_not_high_kick: ; CODE XREF: ApplyBallAfterTouch+23C↑j
                    ; ApplyBallAfterTouch+275↑j ...
mov     eax, kNormalKickDeltaZ
mov     esi, A1
mov     [esi+Sprite.deltaZ], eax
mov     ax, kNormalKickBallSpeed
mov     esi, A1
mov     [esi+Sprite.speed], ax
jmp     short @@do_some_speed_adjustment
; ---------------------------------------------------------------------------

@@jmp_increase_spin_timer: ; CODE XREF: ApplyBallAfterTouch+25F↑j
                    ; ApplyBallAfterTouch+289↑j ...
jmp     @@increase_spin_timer
; ---------------------------------------------------------------------------

@@do_some_speed_adjustment: ; CODE XREF: ApplyBallAfterTouch+2B3↑j
                    ; ApplyBallAfterTouch+2D3↑j
mov     esi, A6     ; slow down the ball after the kick, decide by how much based on direction
cmp     [esi+TeamGeneralInfo.controlledPlDirection], 0
jz      @@decrease_ball_speed_by_quarter
mov     esi, A6
cmp     [esi+TeamGeneralInfo.controlledPlDirection], 4
jz      short @@decrease_ball_speed_by_quarter
mov     esi, A6
test    byte ptr [esi+TeamGeneralInfo.controlledPlDirection], 1
jz      @@increase_spin_timer
mov     esi, A1     ; do this only for diagonal directions
mov     ax, [esi+Sprite.speed]
mov     word ptr D1, ax
shr     word ptr D1, 2
neg     word ptr D1 ; D1 = -speed / 4
mov     esi, A1
mov     ax, [esi+Sprite.speed]
add     word ptr D1, ax ; D1 = 3/4 speed
mov     esi, A1
mov     ax, [esi+Sprite.speed]
mov     word ptr D2, ax
shr     word ptr D2, 3 ; D2 = 1/8 speed
mov     ax, word ptr D2
add     word ptr D1, ax ; D1 = 3/4 speed + 1/8 speed
mov     ax, word ptr D1
mov     esi, A1
mov     [esi+Sprite.speed], ax ; reduce speed to 7/8 (87.5%)
jmp     short @@increase_spin_timer
; ---------------------------------------------------------------------------

@@decrease_ball_speed_by_quarter: ; CODE XREF: ApplyBallAfterTouch+2E5↑j
                    ; ApplyBallAfterTouch+2F6↑j
mov     esi, A1
mov     ax, [esi+Sprite.speed]
mov     word ptr D1, ax
shr     word ptr D1, 2
neg     word ptr D1
mov     esi, A1
mov     ax, [esi+Sprite.speed]
add     word ptr D1, ax
mov     ax, word ptr D1
mov     esi, A1
mov     [esi+Sprite.speed], ax ; decrease speed by quarter (75% now)

@@increase_spin_timer: ; CODE XREF: ApplyBallAfterTouch+223↑j
                    ; ApplyBallAfterTouch:@@jmp_increase_spin_timer↑j ...
mov     esi, A6
add     [esi+TeamGeneralInfo.spinTimer], 1
mov     esi, A6
cmp     [esi+TeamGeneralInfo.spinTimer], 10
jnz     short @@out

@@reset_spin_timer_out: ; CODE XREF: ApplyBallAfterTouch+30↑j
                    ; ApplyBallAfterTouch+48↑j
mov     esi, A6
mov     [esi+TeamGeneralInfo.spinTimer], -1

@@out:              ; CODE XREF: ApplyBallAfterTouch+61↑j
                    ; ApplyBallAfterTouch+3C5↑j
retn
; ---------------------------------------------------------------------------

@@passing_now:      ; CODE XREF: ApplyBallAfterTouch+10↑j
mov     esi, A6
mov     eax, [esi+TeamGeneralInfo.opponentsTeam]
mov     A0, eax
mov     esi, A0
mov     ax, [esi+TeamGeneralInfo.goalkeeperSavedCommentTimer]
or      ax, ax      ; if opponent's goalkeeper has saved, no more spin
js      @@out_reset_spin_timer
cmp     gameStatePl, ST_GAME_IN_PROGRESS
jz      short @@game_in_progress2
cmp     gameState, ST_KEEPER_HOLDS_BALL
jz      @@out_reset_spin_timer

@@game_in_progress2: ; CODE XREF: ApplyBallAfterTouch+3FC↑j
mov     esi, A6     ; spin timer not negative, and game is in progress, and keeper isn't holding the ball
mov     ax, [esi+TeamGeneralInfo.spinTimer]
mov     word ptr D0, ax
or      ax, ax      ; now check the timer, if spin is starting or already in progress
js      @@out2      ; spin not in progress, nothing for us to do
jnz     short @@spin_timer_running
