UpdatePlayerSpeed proc near
                    ; CODE XREF: UpdatePlayers:@@update_player_speed_and_deltas↓p
mov     esi, A1
cmp     [esi+Sprite.playerState], PL_NORMAL
jnz     @@out
cmp     gameStatePl, ST_GAME_IN_PROGRESS ; doing this only for sprites in normal state
jnz     short @@not_goalkeeper
mov     esi, A1
cmp     [esi+Sprite.playerOrdinal], 1
jnz     short @@not_goalkeeper
mov     esi, A6     ; game is in progress and the player is goalkeeper
mov     eax, [esi+TeamGeneralInfo.controlledPlayer]
cmp     A1, eax
jnz     @@out       ; skip goalkeepers that are not player controlled during the game

@@not_goalkeeper:   ; CODE XREF: UpdatePlayerSpeed+18↑j
                    ; UpdatePlayerSpeed+25↑j
call    GetPlayerPointerFromShirtNumber
mov     esi, A4
mov     al, [esi+PlayerInfoHeader.speed]
mov     byte ptr D0, al
mov     al, byte ptr D0
cbw
mov     word ptr D0, ax ; D0 = player speed (from file structure)
shl     word ptr D0, 1
mov     A0, offset kPlayerSpeedsGameInProgress
cmp     gameStatePl, ST_GAME_IN_PROGRESS
jz      short @@convert_speed
mov     A0, offset kPlayerSpeedsGameStopped

@@convert_speed:    ; CODE XREF: UpdatePlayerSpeed+75↑j
mov     esi, A0
movzx   ebx, word ptr D0
mov     ax, [esi+ebx]
mov     esi, A1
mov     [esi+Sprite.speed], ax
mov     ax, runSlower
or      ax, ax
jz      short @@try_to_run_full_speed
mov     esi, A1     ; set speed to 62.5% (running slower when goal is scored)
mov     ax, [esi+Sprite.speed]
mov     word ptr D0, ax
shr     word ptr D0, 2
mov     ax, word ptr D0
mov     esi, A1
sub     [esi+Sprite.speed], ax
shr     word ptr D0, 1
mov     ax, word ptr D0
mov     esi, A1
sub     [esi+Sprite.speed], ax

@@try_to_run_full_speed: ; CODE XREF: UpdatePlayerSpeed+A5↑j
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.playerNumber]
or      ax, ax
jnz     short @@player_controlling
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.playerCoachNumber]
or      ax, ax
jz      short @@player_not_injured ; skip injuries for computer controlled players

@@player_controlling: ; CODE XREF: UpdatePlayerSpeed+F3↑j
mov     esi, A4
mov     al, [esi+PlayerInfoHeader.injuriesBitfield]
mov     byte ptr D0, al
or      al, al
jz      short @@player_not_injured
and     word ptr D0, 0E0h
shr     word ptr D0, 4 ; get injury degree
mov     A0, offset kInjuriesSpeedHandicap
mov     esi, A0
movzx   ebx, word ptr D0
mov     ax, [esi+ebx]
mov     word ptr D0, ax
mov     ax, word ptr D0
mov     esi, A1
add     [esi+Sprite.speed], ax

@@player_not_injured: ; CODE XREF: UpdatePlayerSpeed+102↑j
