mov     ax, [esi+Sprite.speed]
mov     word ptr D0, ax
or      ax, ax
shr     word ptr D0, 3
mov     ax, word ptr D0
mov     esi, A1
sub     [esi+Sprite.speed], ax

@@not_this_player:  ; CODE XREF: UpdatePlayerSpeed+167↑j
                    ; UpdatePlayerSpeed+176↑j
