mov     eax, [esi+TeamGeneralInfo.passToPlayerPtr]
cmp     A1, eax
jnz     @@no_pass_to_player
mov     esi, A6     ; this player is being passed to, in a player controlled team
mov     ax, [esi+TeamGeneralInfo.passingToPlayer]
or      ax, ax
jz      @@no_pass_to_player
mov     esi, A6     ; this player is being passed to, in a player controlled team, and a pass is in progress
mov     eax, dword ptr [esi+TeamGeneralInfo.longPass]
or      eax, eax
jnz     short @@long_pass_to_player
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.leftSpin]
or      ax, ax
jnz     short @@long_pass_to_player
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.rightSpin]
