jg      short @@no_pass_to_player
cmp     byte ptr D0, -7
jl      short @@no_pass_to_player
mov     word ptr D1, 512 ; 512 - speed for a bit more different direction
cmp     byte ptr D0, 5
jg      short @@set_pass_to_player_speed
cmp     byte ptr D0, -5
jl      short @@set_pass_to_player_speed
mov     word ptr D1, 256 ; 256 - speed for more similar direction

@@set_pass_to_player_speed: ; CODE XREF: UpdatePlayerSpeed+255↑j
                    ; UpdatePlayerSpeed+25E↑j
mov     ax, word ptr D1 ; 256 or 512, depending how close the ball direction is
mov     esi, A1
mov     [esi+Sprite.speed], ax

@@no_pass_to_player: ; CODE XREF: UpdatePlayerSpeed+1B0↑j
                    ; UpdatePlayerSpeed+1C5↑j ...
cmp     gameStatePl, ST_GAME_IN_PROGRESS
jz      @@calc_frame_delay
cmp     gameState, ST_FIRST_HALF_ENDED
jz      @@half_or_game_end
cmp     gameState, ST_GAME_ENDED
jz      @@half_or_game_end
cmp     gameState, ST_GOING_TO_HALFTIME
jz      short @@players_leaving_pitch
cmp     gameState, ST_PLAYERS_GOING_TO_SHOWER
jnz     @@calc_frame_delay

@@players_leaving_pitch: ; CODE XREF: UpdatePlayerSpeed+2AB↑j
mov     ax, stoppageTimerTotal
mov     word ptr D0, ax
shl     word ptr D0, 2
cmp     word ptr D0, 100
jbe     short @@set_players_leaving_pitch_speed
mov     word ptr D0, 100

@@set_players_leaving_pitch_speed: ; CODE XREF: UpdatePlayerSpeed+2D7↑j
mov     ax, word ptr D0 ; D0 = min(100, num. frames passed from game stop * 4)
mov     esi, A1
mul     [esi+Sprite.speed]
mov     word ptr D0, ax
mov     word ptr D0+2, dx
mov     ax, word ptr D0
mov     dx, word ptr D0+2
mov     bx, 100
div     bx
mov     word ptr D0, ax ; D0 = player speed weighted with time elapsed from game/half end
mov     word ptr D0+2, dx
mov     ax, word ptr D0
mov     esi, A1
mov     [esi+Sprite.speed], ax ; make players run faster gradually when they're leaving pitch
jmp     short @@calc_frame_delay
; ---------------------------------------------------------------------------

@@half_or_game_end: ; CODE XREF: UpdatePlayerSpeed+28F↑j
                    ; UpdatePlayerSpeed+29D↑j
mov     ax, stoppageTimerTotal ; slow down, and stop players gradually
mov     word ptr D0, ax
