mov     ax, word ptr D0
mov     esi, A1
sub     [esi+Sprite.speed], ax
jns     short @@calc_frame_delay
mov     esi, A1
mov     [esi+Sprite.speed], 0

@@calc_frame_delay: ; CODE XREF: UpdatePlayerSpeed+281↑j
                    ; UpdatePlayerSpeed+2B5↑j ...
mov     word ptr D0, 1280
mov     esi, A1
mov     ax, [esi+Sprite.speed]
sub     word ptr D0, ax ; subtract from max, so slow players would have greater animation delay
jns     short @@speed_difference_in_range
mov     word ptr D0, 0

@@speed_difference_in_range: ; CODE XREF: UpdatePlayerSpeed+37E↑j
shr     word ptr D0, 7 ; /= 128
add     word ptr D0, 6
mov     ax, word ptr D0
mov     esi, A1
mov     [esi+Sprite.frameDelay], ax

@@out:              ; CODE XREF: UpdatePlayerSpeed+A↑j
                    ; UpdatePlayerSpeed+36↑j
retn
UpdatePlayerSpeed endp


