GetPlayerPointerFromShirtNumber proc near
                    ; CODE XREF: SetPlayerDowntimeAfterTackle↑p
                    ; UpdatePlayerSpeed:@@not_goalkeeper↑p ...
mov     esi, A1
mov     ax, [esi+Sprite.playerOrdinal]
mov     word ptr D0, ax
sub     word ptr D0, 1
mov     A4, offset inGameTeamPlayerOffsets
shl     word ptr D0, 1
mov     esi, A4
movzx   ebx, word ptr D0
mov     ax, [esi+ebx]
mov     word ptr D0, ax
mov     esi, A6
mov     eax, [esi+TeamGeneralInfo.inGameTeamPtr]
mov     A4, eax
mov     eax, A4
movzx   ebx, word ptr D0
add     eax, ebx
mov     A4, eax
retn
GetPlayerPointerFromShirtNumber endp


