UpdateBallVariables proc near ; CODE XREF: UpdatePlayers+6F3↓p
push    D0          ; size 0xb02
push    D4
push    D5
push    D6
push    D7
mov     esi, A2
mov     eax, [esi+Sprite.x]
mov     D1, eax     ; D1 = ball x
mov     esi, A2
mov     eax, [esi+Sprite.y]
mov     D2, eax     ; D2 = ball y
mov     esi, A2
mov     eax, [esi+Sprite.z]
