mov     esi, A2
mov     eax, [esi+Sprite.deltaX]
mov     D4, eax     ; D4 = delta x
mov     esi, A2
mov     eax, [esi+Sprite.deltaY]
mov     D5, eax     ; D5 = delta y
mov     esi, A2
mov     eax, [esi+Sprite.deltaZ]
mov     D6, eax     ; D6 = delta z
mov     eax, kBallAirFriction
mov     D7, eax     ; D7 = air friction
