jl      short @@ball_going_up
cmp     D5, 10000h  ; 1.0
jg      @@ball_going_down
cmp     D4, -10000h ; -1.0
jl      @@ball_going_left
cmp     D4, 10000h  ; 1.0
jg      @@ball_going_right
jmp     @@ball_not_moving
