@@ball_going_up:    ; CODE XREF: UpdateBallVariables+86↑j
cmp     A6, offset topTeamData
jnz     @@ball_not_moving
mov     esi, A1     ; doing this for team1, ball going toward their half/goal
mov     eax, [esi+Sprite.y]
sub     D2, eax     ; D2 = ball y - player y
jge     short @@set_ball_y_to_0
mov     esi, A2     ; ball is below player, it's closer than player to his own goal
mov     ax, word ptr [esi+(Sprite.x+2)]
mov     ballDefensiveX, ax
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.y+2)]
mov     ballDefensiveY, ax
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.z+2)]
mov     ballDefensiveZ, ax
mov     esi, A1
mov     eax, [esi+Sprite.y]
add     D2, eax     ; D2 = ball y again
jmp     @@ball_above_player_check
; ---------------------------------------------------------------------------

@@set_ball_y_to_0:  ; CODE XREF: UpdateBallVariables+DC↑j
                    ; UpdateBallVariables+14E↓j
mov     eax, D7     ; ball is between player and opponent goal
sub     D6, eax     ; delta z -= air friction
mov     eax, D6
add     D3, eax     ; z += old delta z - air friction, ball speeding up as nearing ground
mov     eax, D4
add     D1, eax     ; x += delta x
mov     eax, D5
add     D2, eax     ; y += delta y, while >= 0 repeat...
jge     short @@set_ball_y_to_0
mov     eax, D4
sub     D1, eax
mov     eax, D5
sub     D2, eax
mov     eax, D6
sub     D3, eax
mov     esi, A1
mov     eax, [esi+Sprite.y]
add     D2, eax
mov     ax, word ptr D1
xchg    ax, word ptr D1+2
mov     word ptr D1, ax
mov     ax, word ptr D2
xchg    ax, word ptr D2+2
mov     word ptr D2, ax
mov     ax, word ptr D3
xchg    ax, word ptr D3+2
mov     word ptr D3, ax
mov     ax, word ptr D1
mov     ballDefensiveX, ax
mov     ax, word ptr D2
mov     ballDefensiveY, ax
mov     ax, word ptr D3
or      ax, ax
jns     short cseg_77879
mov     word ptr D3, 0

cseg_77879:         ; CODE XREF: UpdateBallVariables+1DA↑j
mov     ax, word ptr D3
mov     ballDefensiveZ, ax
mov     ax, word ptr D1
xchg    ax, word ptr D1+2
mov     word ptr D1, ax
mov     ax, word ptr D2
xchg    ax, word ptr D2+2
mov     word ptr D2, ax
mov     ax, word ptr D3
xchg    ax, word ptr D3+2
mov     word ptr D3, ax

@@ball_above_player_check: ; CODE XREF: UpdateBallVariables+11D↑j
sub     D2, 870000h ; 135.0
jge     short @@ball_above_135
mov     ax, ballDefensiveX
mov     ballNotHighX, ax
mov     ax, ballDefensiveY
mov     ballNotHighY, ax
mov     ax, ballDefensiveZ
