mov     ax, word ptr D3
xchg    ax, word ptr D3+2
mov     word ptr D3, ax
mov     ax, word ptr D1
mov     ballNotHighX, ax
mov     ax, word ptr D2
mov     ballNotHighY, ax
mov     ax, word ptr D3
or      ax, ax
jns     short cseg_779B0
mov     word ptr D3, 0

cseg_779B0:         ; CODE XREF: UpdateBallVariables+311↑j
mov     ax, word ptr D3
mov     ballNotHighZ, ax
mov     ax, word ptr D1
xchg    ax, word ptr D1+2
mov     word ptr D1, ax
mov     ax, word ptr D2
xchg    ax, word ptr D2+2
mov     word ptr D2, ax
mov     ax, word ptr D3
xchg    ax, word ptr D3+2
mov     word ptr D3, ax

