CalculateBallNextGroundXYPositions proc near
                    ; CODE XREF: UpdatePlayers+6F8↓p
push    D0
push    D4
push    D5
push    D6
push    D7
mov     esi, A2
mov     eax, [esi+Sprite.x]
mov     D1, eax     ; D1 = ball x
mov     esi, A2
mov     eax, [esi+Sprite.y]
mov     D2, eax     ; D2 = ball y
mov     esi, A2
mov     eax, [esi+Sprite.z]
mov     D3, eax     ; D3 = ball z
mov     esi, A2
mov     eax, [esi+Sprite.deltaX]
mov     D4, eax     ; D4 = ball delta x
mov     esi, A2
mov     eax, [esi+Sprite.deltaY]
mov     D5, eax     ; D5 = ball delta y
cmp     D5, -10000h ; -1.0
jl      short @@ball_moving
cmp     D5, 10000h  ; 1.0
jg      short @@ball_moving
cmp     D4, -10000h ; -1.0
jl      short @@ball_moving
cmp     D4, 10000h  ; 1.0
jg      short @@ball_moving
jmp     @@ball_standing
; ---------------------------------------------------------------------------

@@ball_moving:      ; CODE XREF: CalculateBallNextGroundXYPositions+6E↑j
                    ; CalculateBallNextGroundXYPositions+7A↑j ...
mov     esi, A2
mov     eax, [esi+Sprite.deltaZ]
mov     D6, eax     ; D6 = ball delta z
mov     eax, kBallAirFriction
mov     D7, eax
mov     D0, 140000h ; D0 = 20.0 (starting ball z difference)

@@subtract_z:       ; CODE XREF: CalculateBallNextGroundXYPositions+ED↓j
mov     eax, D0
sub     D3, eax     ; ball z -= 20.0 or less
jns     short @@z_in_range
cmp     D0, 0D0000h ; 13.0
jz      @@ball_standing
mov     eax, D0
add     D3, eax     ; restore ball z as it was
sub     D0, 10000h  ; decrease ball z difference (by 1.0)
jmp     short @@subtract_z
; ---------------------------------------------------------------------------

@@z_in_range:       ; CODE XREF: CalculateBallNextGroundXYPositions+C6↑j
                    ; CalculateBallNextGroundXYPositions+11B↓j
mov     eax, D4
add     D1, eax     ; ball x += delta x
mov     eax, D5
add     D2, eax     ; ball y += delta y
mov     eax, D7
sub     D6, eax     ; ball delta z -= ball z constant
mov     eax, D6
add     D3, eax     ; ball z += delta z
jns     short @@z_in_range
mov     eax, D0
add     D3, eax
mov     ax, word ptr D1
xchg    ax, word ptr D1+2
mov     word ptr D1, ax
mov     ax, word ptr D2
xchg    ax, word ptr D2+2
mov     word ptr D2, ax
mov     ax, word ptr D3
xchg    ax, word ptr D3+2
mov     word ptr D3, ax ; get whole parts
mov     ax, word ptr D1
mov     ballNextGroundX, ax
mov     ax, word ptr D2
mov     ballNextYGroundY, ax
mov     ax, word ptr D3
mov     ballNextZDeadVar, ax
mov     ballNextZDeadVar, 0
jmp     short @@out
; ---------------------------------------------------------------------------

@@ball_standing:    ; CODE XREF: CalculateBallNextGroundXYPositions+94↑j
                    ; CalculateBallNextGroundXYPositions+D2↑j
mov     ballNextGroundX, -1

@@out:              ; CODE XREF: CalculateBallNextGroundXYPositions+18E↑j
pop     D7
pop     D6
pop     D5
pop     D4
pop     D0
retn
CalculateBallNextGroundXYPositions endp


