; in:
;      D0 -  direction
;      D1 -  goalkeeper far jump speed flag, overrides goalkeeper jump speed if:
;                0 - no influence, use high speed as usual (2048)
;                1 - use lower speed (1280)
;                * - anything else: use low speed (1024) + low byte of currentGameTick
;                    effectively random: 1024..1279
;      D3 -  also some direction
;      A1 -> player sprite
;      A6 -> player team (general)

GoalkeeperJumping proc near ; CODE XREF: UpdatePlayers+1088↓p
                    ; UpdatePlayers+11BA↓p
mov     esi, A1
cmp     [esi+Sprite.ballDistance], 128
ja      short @@ball_far_away
mov     ax, kGoalkeeperNearJumpSpeed
mov     word ptr D1, ax
mov     ax, word ptr D1
mov     esi, A1
mov     [esi+Sprite.speed], ax
jmp     short @@speed_setting_done
; ---------------------------------------------------------------------------

@@ball_far_away:    ; CODE XREF: GoalkeeperJumping+D↑j
mov     ax, kGoalkeeperFarJumpSpeed
mov     esi, A1
mov     [esi+Sprite.speed], ax
mov     ax, word ptr D1
or      ax, ax
jz      short @@speed_setting_done
mov     ax, kGoalkeeperFarJumpSlowerSpeed
mov     esi, A1
mov     [esi+Sprite.speed], ax
cmp     word ptr D1, 1
jz      short @@speed_setting_done
mov     ax, currentGameTick
mov     word ptr D1, ax
and     word ptr D1, 0FFh
mov     ax, kGoalkeeperNearJumpSpeed
add     word ptr D1, ax
mov     ax, word ptr D1
mov     esi, A1
mov     [esi+Sprite.speed], ax

