mov     word ptr D1, ax
mov     esi, A1
mov     ax, word ptr [esi+(Sprite.y+2)]
sub     word ptr D1, ax
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.x+2)]
mov     word ptr D1, ax
mov     esi, A1
mov     ax, word ptr [esi+(Sprite.x+2)]
sub     word ptr D1, ax
mov     esi, A6
mov     byte ptr [esi+TeamGeneralInfo.field_46], 0
mov     esi, A6
