; =============== S U B R O U T I N E =======================================

; in:
;      A1 -> sprite (player)
;      A6 -> team (general)
;
; Player is tackling and hitting the ball. Adjust ball direction according to the player direction and
; controls direction (do deflected tackles). Set ball destination coordinates far away in that direction.
; Adjust ball speed after tackle to 125% of player's speed (100% if CPU player). Set player's speed
; afterward to 50%. If opponent's controlled player is more than 9u away from the ball and distance
; between the 2 players is greater than 32u it is considered a good tackle.
;  u = sqr((x1 - x2) ^ 2) + sqr((y1 - y2) ^ 2)

PlayerTackledTheBallStrong proc near ; CODE XREF: UpdatePlayers+37CC↓p
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.currentAllowedDirection]
mov     word ptr D1, ax
or      ax, ax
jns     short @@current_direction_allowed
mov     esi, A1
mov     ax, [esi+Sprite.direction]
mov     word ptr D1, ax ; keep old players direction

@@current_direction_allowed:
                    ; CODE XREF: PlayerTackledTheBallStrong+13↑j
mov     A2, offset ballSprite
mov     esi, A1
mov     ax, [esi+Sprite.direction]
mov     word ptr D0, ax
mov     ax, word ptr D1
sub     word ptr D0, ax ; D0 = difference between player and controls direction
jz      short @@set_controlled_player_direction ; do they have same direction?
and     word ptr D0, 7 ; ANDing difference with 7 maps it to a counter-clockwise oriented circle (top=0)
cmp     word ptr D0, 4 ; if it's equal to 4 those two directions are opposite
jz      short @@set_controlled_player_direction
jb      short @@controls_leaning_leftward
mov     esi, A1     ; > 4
mov     ax, [esi+Sprite.direction] ; controls leaning rightward
mov     word ptr D0, ax
