; =============== S U B R O U T I N E =======================================

; in:
;      D0 - movement delta, distance in a single frame (fixed point)
;           (absolute value is taken)
;      D4 - distance to cover (integer)
; out:
;      D7 - frames needed to cover the given distance (integer)
;
; Does division D4/D0 using loops, without direct divide instruction.
; If they're exactly divisible it will return one more, e.g. 9/3 -> 4.
; If D0 is less than 1, scales it up as well as the value which gets
; subtracted from D4 in a loop, to limit the number of loops when D0 < 1.
; It will fail for extremely low D0 values.
; Called to calculate on both x and y directions.

GetFramesNeededToCoverDistance proc near
                    ; CODE XREF: ShouldGoalkeeperDive+12D↑p
                    ; ShouldGoalkeeperDive+17B↑p ...
mov     eax, D0
or      eax, eax
jz      short @@not_moving
nop
nop
nop
nop
jns     short @@positive
neg     D0

@@positive:         ; CODE XREF: GetFramesNeededToCoverDistance+D↑j
mov     word ptr D5, 1 ; D5 = num. frames per subtraction, 1 if D0 >= 1
cmp     D0, 10000h  ; 1.0
jnb     short @@goalkeeper_delta_eq_1_or_more

@@scale_loop:       ; CODE XREF: GetFramesNeededToCoverDistance+41↓j
shl     D0, 1       ; if keeper's delta y is < 1, bring it to >= 1 and increase subtraction value along the way
shl     word ptr D5, 1 ; probably to speed up things
cmp     D0, 10000h
jb      short @@scale_loop

@@goalkeeper_delta_eq_1_or_more:
                    ; CODE XREF: GetFramesNeededToCoverDistance+28↑j
mov     ax, word ptr D4
xchg    ax, word ptr D4+2
mov     word ptr D4, ax
mov     word ptr D4, 0 ; turn dist(ball, keeper) to fixed point, value.0
mov     word ptr D7, 0

@@divide_loop:      ; CODE XREF: GetFramesNeededToCoverDistance+80↓j
mov     ax, word ptr D5
add     word ptr D7, ax
mov     eax, D0
sub     D4, eax
jns     short @@divide_loop
retn
; ---------------------------------------------------------------------------

@@not_moving:       ; CODE XREF: GetFramesNeededToCoverDistance+7↑j
mov     word ptr D7, 0
xor     ax, ax
retn
GetFramesNeededToCoverDistance endp


