add     word ptr D1, ax ; D1 = ball x + default destination offset
mov     ax, word ptr D1
mov     esi, A2
mov     [esi+Sprite.destX], ax
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.y+2)]
mov     word ptr D1, ax
mov     esi, A0
movzx   ebx, word ptr D0
mov     ax, [esi+ebx+2]
