; in:
;      A1 -> sprite (player)
;      A2 -> sprite (ball)
;      A6 -> team data
;
; Check if the tackle ends up in faul, there must be a few conditions satisfied:
; - opponent has a controlled player
; - distance between them is more than 32 units

PlayerTacklingTestFoul proc near ; CODE XREF: UpdatePlayers+3873↓p
mov     esi, A6
mov     eax, [esi+TeamGeneralInfo.opponentsTeam]
mov     A2, eax     ; A2 -> opponents team
mov     esi, A2
mov     eax, [esi+TeamGeneralInfo.controlledPlayer]
mov     A2, eax     ; A2 -> opponent's team controlled player sprite
cmp     A2, 0
jz      @@out
mov     esi, A1
mov     ax, word ptr [esi+(Sprite.x+2)]
mov     word ptr D0, ax
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.x+2)]
sub     word ptr D0, ax
mov     ax, word ptr D0
mov     bx, word ptr D0
imul    bx
mov     word ptr D0, ax
mov     word ptr D0+2, dx ; D0 = sqr(this player x - opponent's player x)
mov     esi, A1
mov     ax, word ptr [esi+(Sprite.y+2)]
mov     word ptr D1, ax
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.y+2)]
sub     word ptr D1, ax
mov     ax, word ptr D1
mov     bx, word ptr D1
imul    bx
mov     word ptr D1, ax
mov     word ptr D1+2, dx ; D1 = sqr(this player y - opponent's player y)
mov     eax, D1
add     D0, eax     ; D0 = sqr(this player x - opponent's player x) + sqr(this player y - opponent's player y)
cmp     D0, 32
jbe     short @@players_very_close

@@out:              ; CODE XREF: PlayerTacklingTestFoul+22↑j
                    ; PlayerTacklingTestFoul+EB↓j ...
retn
; ---------------------------------------------------------------------------

@@play_foul_comment_and_return:
                    ; CODE XREF: PlayerTacklingTestFoul+1A4↓j
call    PlayDangerousPlayComment
retn
; ---------------------------------------------------------------------------

@@opponents_player_goalkeeper: ; CODE XREF: PlayerTacklingTestFoul+DE↓j
mov     esi, A1     ; just slow down player who's tackling and return
shr     [esi+Sprite.speed], 1
shr     [esi+Sprite.speed], 1
or      [esi+Sprite.speed], 1
retn
; ---------------------------------------------------------------------------

@@players_very_close: ; CODE XREF: PlayerTacklingTestFoul+B6↑j
mov     esi, A2
cmp     [esi+Sprite.playerOrdinal], 1
jz      short @@opponents_player_goalkeeper
mov     esi, A2
cmp     [esi+Sprite.playerOrdinal], 1
jz      short @@out
mov     esi, A2
cmp     word ptr [esi+(Sprite.x+2)], 81 ; left out line
jl      short @@out
mov     esi, A2
cmp     word ptr [esi+(Sprite.y+2)], 129 ; upper corner line
jl      short @@out
mov     esi, A2
cmp     word ptr [esi+(Sprite.x+2)], 590 ; right out line
jg      short @@out
mov     esi, A2
cmp     word ptr [esi+(Sprite.y+2)], 769 ; lower corner line
jg      short @@out
mov     esi, A1     ; opponent's player is inside the field
shr     [esi+Sprite.speed], 1
mov     esi, A1
shr     [esi+Sprite.speed], 1
mov     esi, A1
or      [esi+Sprite.speed], 1 ; player that tackled: speed = speed / 4, but at least 1
push    A1
push    A6
mov     eax, A2
mov     A1, eax
mov     esi, A6
mov     eax, [esi+TeamGeneralInfo.opponentsTeam]
mov     A6, eax
call    PlayerTackled
pop     A6
pop     A1
mov     esi, A2
cmp     [esi+Sprite.ballDistance], 800 ; if opponent player far away from the ball, nothing, return
ja      @@out
mov     esi, A1
mov     ax, [esi+Sprite.tackleState]
or      ax, ax
jz      short @@foul_concedeed
mov     esi, A1
cmp     [esi+Sprite.tackleState], TS_GOOD_TACKLE
jz      @@play_foul_comment_and_return
mov     esi, A1
mov     ax, [esi+Sprite.direction]
mov     word ptr D0, ax ; tackling player direction
mov     esi, A2
mov     ax, [esi+Sprite.direction]
sub     word ptr D0, ax ; tackled player direction
cmp     word ptr D0, -1 ; are they facing about the same direction (+/-1)?
jl      @@out
cmp     word ptr D0, 1
jg      @@out

@@foul_concedeed:   ; CODE XREF: PlayerTacklingTestFoul+197↑j
mov     esi, A6     ; tackle from the back or not on ball
mov     eax, [esi+TeamGeneralInfo.teamStatsPtr]
mov     A0, eax
mov     esi, A0
add     [esi+TeamStatisticsData.foulsConceded], 1
mov     ax, cardsDisallowed
or      ax, ax
jnz     @@no_cards_given
mov     ax, g_trainingGame
or      ax, ax
jnz     @@no_cards_given
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.x+2)]
mov     word ptr D1, ax
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.y+2)]
mov     word ptr D2, ax
cmp     word ptr D1, 193
jl      short @@not_in_penalty_area
cmp     word ptr D1, 478
jg      short @@not_in_penalty_area
cmp     word ptr D2, 129
jl      short @@not_in_penalty_area
cmp     word ptr D2, 769
jg      short @@not_in_penalty_area
cmp     A6, offset topTeamData
jnz     short @@right_team
cmp     word ptr D2, 216
jle     @@in_penalty_area
jmp     short @@not_in_penalty_area
; ---------------------------------------------------------------------------

@@right_team:       ; CODE XREF: PlayerTacklingTestFoul+274↑j
cmp     word ptr D2, 682
jge     @@in_penalty_area

@@not_in_penalty_area: ; CODE XREF: PlayerTacklingTestFoul+247↑j
                    ; PlayerTacklingTestFoul+252↑j ...
mov     word ptr D1, 336
