cmp     A6, offset topTeamData
jz      @@left_team
mov     cameraDirection, 4 ; south
cmp     word ptr D2, 682 ; lower penalty area upper bound
jl      @@not_in_lower_penalty_area
cmp     word ptr D1, 193 ; both penalty areas left bound
jl      @@not_in_lower_penalty_area
cmp     word ptr D1, 478 ; both penalty areas right bound
jg      @@not_in_lower_penalty_area
mov     gameState, ST_PENALTY
mov     breakCameraMode, -1
mov     byte ptr playerTurnFlags, 38h ; allow only SW, S, SE
mov     foulXCoordinate, 336 ; lower white spot
mov     foulYCoordinate, 711
push    D0
push    D1
push    D2
push    D3
push    D4
push    D5
push    D6
push    D7
push    A0
push    A1
push    A2
push    A3
push    A4
push    A5
push    A6
