pop     A6
pop     A5
pop     A4
pop     A3
pop     A2
pop     A1
pop     A0
pop     D7
pop     D6
pop     D5
pop     D4
pop     D3
pop     D2
pop     D1
pop     D0
jmp     @@continue_after_penalty
; ---------------------------------------------------------------------------

