mov     esi, A2
mov     ax, word ptr [esi+(Sprite.y+2)]
mov     word ptr D1, ax
mov     esi, A0
movzx   ebx, word ptr D0
mov     ax, [esi+ebx+2]
add     word ptr D1, ax
mov     ax, word ptr D1
mov     esi, A2
mov     [esi+Sprite.destY], ax ; do the same for y
mov     ax, kBallKickingSpeed
mov     word ptr D1, ax
mov     ax, word ptr D1
