mov     esi, A0
movzx   ebx, word ptr D0
mov     ax, [esi+ebx]
mov     word ptr D0, ax
mov     ax, word ptr D0
mov     esi, A2
add     [esi+Sprite.speed], ax

@@not_a_shot_on_goal: ; CODE XREF: PlayerKickingBall+134↑j
                    ; PlayerKickingBall+163↑j ...
