; in:
;      D0 -  direction
;      A1 -> player sprite
;      A6 -> team (general)
; out:
;      A0 -> player sprite
;      D2 -  ball distance
;
; Return pointer to player closest to the ball facing approximately given
; direction. Also return his distance from the ball.

GetClosestNonControlledPlayerInDirection proc near
                    ; CODE XREF: DoPass+63↑p
mov     eax, A1
mov     A5, eax
mov     esi, A6
mov     eax, [esi+TeamGeneralInfo.spritesTable]
