shl     word ptr D0, 5
mov     A0, -1
mov     D2, -1
mov     word ptr D7, 10

@@players_loop:     ; CODE XREF: GetClosestNonControlledPlayerInDirection+111↓j
mov     esi, A2
mov     eax, [esi]
add     A2, 4
