mov     D1, eax
mov     eax, D2
cmp     D1, eax
jnb     short @@next
mov     eax, D1
mov     D2, eax
mov     eax, A1
mov     A0, eax

@@next:             ; CODE XREF: GetClosestNonControlledPlayerInDirection+8A↑j
                    ; GetClosestNonControlledPlayerInDirection+9D↑j ...
dec     word ptr D7
jns     @@players_loop
retn
GetClosestNonControlledPlayerInDirection endp


; =============== S U B R O U T I N E =======================================

; out:
;      A0 -> ball factor table, depending on game state
;
; Even indices are delta x, odd are delta y. They are added to ball
; delta x and y. Tables are different for each type of game halt.
; Called when player kicks the ball or does a pass.

GetBallDestCoordinatesTable proc near
                    ; CODE XREF: DoPass:@@no_closest_player↑p
                    ; PlayerKickingBall+43↑p
cmp     gameState, ST_THROW_IN_FORWARD_RIGHT
jb      short @@not_throw_in
cmp     gameState, ST_THROW_IN_BACK_LEFT
ja      short @@not_throw_in
cmp     foulXCoordinate, 336 ; center of pitch
ja      short @@right_throw_in
mov     A0, offset kLeftThrowInBallDestDelta ; left throw in
retn
; ---------------------------------------------------------------------------

@@right_throw_in:   ; CODE XREF: GetBallDestCoordinatesTable+1D↑j
mov     A0, offset kRightThrowInBallDestDelta
retn
; ---------------------------------------------------------------------------

@@not_throw_in:     ; CODE XREF: GetBallDestCoordinatesTable+8↑j
                    ; GetBallDestCoordinatesTable+12↑j
cmp     gameState, ST_PENALTY
jz      short @@penalty
cmp     gameState, ST_PENALTIES
jnz     short @@not_penalty

@@penalty:          ; CODE XREF: GetBallDestCoordinatesTable+3D↑j
mov     A0, offset kPenaltyBallDestDelta
retn
; ---------------------------------------------------------------------------

@@not_penalty:      ; CODE XREF: GetBallDestCoordinatesTable+47↑j
cmp     gameState, ST_CORNER_LEFT
jz      short @@corner
cmp     gameState, ST_CORNER_RIGHT
jnz     short @@not_corner

@@corner:           ; CODE XREF: GetBallDestCoordinatesTable+5C↑j
cmp     foulYCoordinate, 449
ja      short @@lower_corner
cmp     foulXCoordinate, 336
ja      short @@upper_right_corner
mov     A0, offset kUpperLeftCornerBallDestDelta ; upper left corner
retn
; ---------------------------------------------------------------------------

@@upper_right_corner: ; CODE XREF: GetBallDestCoordinatesTable+7C↑j
mov     A0, offset kUpperRightCornerBallDestDelta
retn
; ---------------------------------------------------------------------------

@@lower_corner:     ; CODE XREF: GetBallDestCoordinatesTable+71↑j
cmp     foulXCoordinate, 336
ja      short @@lower_right_corner
mov     A0, offset kLowerLeftCornerBallDestDelta ; lower left corner
retn
; ---------------------------------------------------------------------------

@@lower_right_corner: ; CODE XREF: GetBallDestCoordinatesTable+9D↑j
mov     A0, offset kLowerRightCornerBallDestDelta
retn
; ---------------------------------------------------------------------------

@@not_corner:       ; CODE XREF: GetBallDestCoordinatesTable+66↑j
mov     A0, offset kDefaultDestinations
retn
GetBallDestCoordinatesTable endp


; =============== S U B R O U T I N E =======================================

; in:
;      D0 -  direction
;      A1 -> player sprite
;
; Player starts jumping in attempt to hit the ball with his head. Set his state
