shl     word ptr D0, 2
mov     eax, A5
movzx   ebx, word ptr D0
add     eax, ebx
mov     A5, eax
mov     esi, A5
mov     ax, [esi]
add     A5, 2
mov     word ptr D0, ax
mov     esi, A1
mov     ax, word ptr [esi+(Sprite.x+2)]
add     word ptr D0, ax
mov     ax, word ptr D0
mov     esi, A1
mov     [esi+Sprite.destX], ax
mov     esi, A5
mov     ax, [esi]
mov     word ptr D0, ax
mov     esi, A1
mov     ax, word ptr [esi+(Sprite.y+2)]
add     word ptr D0, ax
mov     ax, word ptr D0
mov     esi, A1
mov     [esi+Sprite.destY], ax
mov     ax, kJumpHeaderSpeed
mov     esi, A1
mov     [esi+Sprite.speed], ax
retn
PlayerAttemptingJumpHeader endp


