; =============== S U B R O U T I N E =======================================

; in:
;      A0 -> animation table
;      A1 -> player (sprite)

SetPlayerAnimationTableAndPictureIndex proc near
                    ; CODE XREF: SetPlayerJumpHeaderHitAnimationTable+17↑p
                    ; SetJumpHeaderHitAnimTable+4A↓p ...
mov     eax, A0
mov     esi, A1
mov     [esi+Sprite.animationTable], eax
push    D0
mov     esi, A1
mov     ax, [esi+Sprite.teamNumber]
mov     word ptr D0, ax
sub     word ptr D0, 1 ; D0 = 0 for team 1, 1 for team 2
mov     esi, A1
cmp     [esi+Sprite.playerOrdinal], 1
jnz     short @@calc_table_index
add     word ptr D0, 2 ; D0: 0 - player team 1
                    ;     1 - player team 2
                    ;     2 - goalkeeper team 1
                    ;     3 - goalkeeper team 2

@@calc_table_index: ; CODE XREF: SetPlayerAnimationTableAndPictureIndex+36↑j
shl     word ptr D0, 3
mov     esi, A1
mov     ax, [esi+Sprite.direction]
add     word ptr D0, ax
shl     word ptr D0, 2 ; index = 8 * player/goalie team + direction (0..7)
mov     esi, A0
mov     ax, [esi]
mov     esi, A1
mov     [esi+Sprite.frameDelay], ax
mov     esi, A0
movzx   ebx, word ptr D0
mov     eax, [esi+ebx+2]
mov     esi, A1
mov     [esi+Sprite.frameIndicesTable], eax
or      eax, eax
jz      @@fatal_error
mov     esi, A1
mov     ax, [esi+Sprite.direction]
mov     esi, A1
mov     [esi+Sprite.startingDirection], ax
mov     esi, A1
mov     eax, [esi+Sprite.frameIndicesTable]
mov     A0, eax
mov     esi, A1
mov     ax, [esi+Sprite.frameIndex]
mov     word ptr D0, ax
shl     word ptr D0, 1
mov     esi, A0
movzx   ebx, word ptr D0
mov     ax, [esi+ebx]
mov     word ptr D0, ax
or      ax, ax
js      short @@out
mov     esi, A1
mov     ax, [esi+Sprite.frameOffset]
add     word ptr D0, ax
mov     ax, word ptr D0
mov     esi, A1
mov     [esi+Sprite.imageIndex], ax

@@out:              ; CODE XREF: SetPlayerAnimationTableAndPictureIndex+E9↑j
pop     D0
retn
; ---------------------------------------------------------------------------

@@fatal_error:      ; CODE XREF: SetPlayerAnimationTableAndPictureIndex+90↑j
int     3           ; Trap to Debugger

@@endless_loop:     ; CODE XREF: SetPlayerAnimationTableAndPictureIndex:@@endless_loop↓j
