mov     esi, A0
movzx   ebx, word ptr D0
mov     ax, [esi+ebx]
add     word ptr D1, ax ; D1 = ball next x (player x + value from table)
mov     esi, A1
mov     ax, word ptr [esi+(Sprite.y+2)]
mov     word ptr D2, ax
mov     esi, A0
movzx   ebx, word ptr D0
mov     ax, [esi+ebx+2]
add     word ptr D2, ax
mov     A0, offset ballSprite
mov     esi, A0
mov     [esi+Sprite.speed], 0 ; ball speed = 0 when player controlling it
mov     ax, word ptr D1
mov     esi, A0
mov     word ptr [esi+(Sprite.x+2)], ax
mov     ax, word ptr D2
mov     esi, A0
mov     word ptr [esi+(Sprite.y+2)], ax
mov     ax, word ptr D1
mov     esi, A0
mov     [esi+Sprite.destX], ax
mov     ax, word ptr D2
mov     esi, A0
mov     [esi+Sprite.destY], ax
mov     esi, A0
mov     word ptr [esi+(Sprite.z+2)], 0 ; ball z = 0 when player is controlling it
mov     esi, A0
mov     eax, [esi+Sprite.deltaZ]
mov     D0, eax
sar     D0, 1
mov     eax, D0
mov     esi, A0
mov     [esi+Sprite.deltaZ], eax ; halve the ball z each frame when player controlling it
call    ResetBothTeamSpinTimers
retn
UpdateBallWithControllingPlayer endp


