                    ; CODE XREF: PlayerTackledTheBallWeak+5B↑j
                    ; PlayerTackledTheBallWeak+6D↑j
mov     esi, A1
mov     ax, [esi+Sprite.direction]
mov     word ptr D0, ax

@@set_new_ball_direction_and_speed:
                    ; CODE XREF: PlayerTackledTheBallWeak+89↑j
                    ; PlayerTackledTheBallWeak+A3↑j
and     word ptr D0, 7
mov     ax, word ptr D0
