mov     esi, A0
movzx   ebx, word ptr D0
mov     ax, [esi+ebx+2]
add     word ptr D1, ax
mov     ax, word ptr D1
mov     esi, A2
mov     [esi+Sprite.destY], ax
mov     esi, A1
