; in:
;      A1 -> current player sprite
;      A6 -> team data

SetPlayerWithNoBallDestination proc near
                    ; CODE XREF: UpdatePlayers:@@set_player_with_no_ball_destination↓p
mov     A0, offset g_tacticsTable
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.tactics]
mov     word ptr D0, ax
shl     word ptr D0, 2
mov     esi, A0
movzx   ebx, word ptr D0
mov     eax, [esi+ebx]
mov     A0, eax     ; A0 -> current team tactics
cmp     gameState, ST_KEEPER_HOLDS_BALL
jz      short @@keepers_ball_or_goalout
cmp     gameState, ST_GOAL_OUT_LEFT
jz      short @@keepers_ball_or_goalout
cmp     gameState, ST_GOAL_OUT_RIGHT
jnz     short @@game_in_progress

@@keepers_ball_or_goalout:
                    ; CODE XREF: SetPlayerWithNoBallDestination+3F↑j
                    ; SetPlayerWithNoBallDestination+49↑j
mov     esi, A0
mov     al, [esi+Tactics.ballOutOfPlayTactics]
mov     byte ptr D0, al
mov     al, byte ptr D0
cbw
mov     word ptr D0, ax ; D0 = tactics index when keeper's ball or goal-out
mov     A0, offset g_tacticsTable
shl     word ptr D0, 2
mov     esi, A0
movzx   ebx, word ptr D0
mov     eax, [esi+ebx]
mov     A0, eax     ; now A0 -> team's tactics when game's not in progress (goal out or keeper's ball)

@@game_in_progress: ; CODE XREF: SetPlayerWithNoBallDestination+53↑j
mov     eax, A0
add     eax, Tactics.playerPos
mov     A0, eax     ; A0 -> player positions
mov     esi, A1
mov     ax, [esi+Sprite.playerOrdinal]
mov     word ptr D0, ax
sub     word ptr D0, 2
js      @@goalkeeper ; special treatment for goalkeeper
mov     ax, word ptr D0
mov     bx, 35      ; size of one player positions set in tactics
mul     bx
mov     word ptr D0, ax
mov     word ptr D0+2, dx ; D0 = offset of this player positions table
mov     ax, playerXQuadrantOffset
mov     word ptr D3, ax ; D3 = player quadrant x offset
mov     ax, playerYQuadrantOffset
mov     word ptr D4, ax ; D4 = player y quadrant offset
cmp     A6, offset topTeamData
jnz     short @@right_team_invert
mov     ax, ballQuadrantIndex
add     word ptr D0, ax
mov     esi, A0
movzx   ebx, word ptr D0
mov     al, [esi+ebx]
mov     byte ptr D1, al ; D1 = coded quadrant player should go to
or      al, al
jmp     short @@send_player_to_his_quadrant
; ---------------------------------------------------------------------------

@@right_team_invert: ; CODE XREF: SetPlayerWithNoBallDestination+101↑j
mov     word ptr D1, 34
mov     ax, ballQuadrantIndex
sub     word ptr D1, ax ; invert ball quadrant for other team
mov     ax, word ptr D1
add     word ptr D0, ax ; D0 = offset of this player coded quadrant-to-go
mov     byte ptr D1, 0EFh ; upper left coded quadrant
mov     esi, A0
movzx   ebx, word ptr D0
mov     al, [esi+ebx]
sub     byte ptr D1, al ; D1 = coded quadrant player should go to (inverted first)

@@send_player_to_his_quadrant:
                    ; CODE XREF: SetPlayerWithNoBallDestination+127↑j
mov     al, byte ptr D1 ; D1 = coded quadrant player should go to (x,y = nibble, nibble)
mov     byte ptr D2, al
or      al, al
shr     word ptr D1, 4 ; D1 = x quadrant
and     word ptr D1, 0Fh
and     word ptr D2, 0Fh ; D2 = y quadrant
mov     A0, offset playerXQuadrantsCoordinates
shl     word ptr D1, 1
mov     esi, A0
movzx   ebx, word ptr D1
mov     ax, [esi+ebx]
add     word ptr D3, ax ; D3 = x position to go
mov     A0, offset playerYQuadrantCoordinates
shl     word ptr D2, 1
mov     esi, A0
movzx   ebx, word ptr D2
mov     ax, [esi+ebx]
add     word ptr D4, ax ; D4 = y position to go
sub     word ptr D3, 4 ; up team player approaches its place a bit from left
                    ; (4 should be half of player width?)
cmp     A6, offset topTeamData
jz      short @@clip_x_dest
add     word ptr D3, 8 ; lower team player approaches from the right

@@clip_x_dest:      ; CODE XREF: SetPlayerWithNoBallDestination+1F1↑j
cmp     word ptr D3, 81
jge     short @@x_inside_left_pitch_border
mov     word ptr D3, 81

@@x_inside_left_pitch_border:
                    ; CODE XREF: SetPlayerWithNoBallDestination+203↑j
cmp     word ptr D3, 590
jle     short @@clip_y_dest
mov     word ptr D3, 590

@@clip_y_dest:      ; CODE XREF: SetPlayerWithNoBallDestination+217↑j
cmp     word ptr D4, 129
jge     short @@y_inside_upper_pitch_border
mov     word ptr D4, 129

@@y_inside_upper_pitch_border:
                    ; CODE XREF: SetPlayerWithNoBallDestination+22B↑j
cmp     word ptr D4, 769
jle     short @@set_player_dest_coordinates
mov     word ptr D4, 769

@@set_player_dest_coordinates:
                    ; CODE XREF: SetPlayerWithNoBallDestination+23F↑j
mov     ax, word ptr D3
mov     esi, A1
mov     [esi+Sprite.destX], ax
mov     ax, word ptr D4
mov     esi, A1
mov     [esi+Sprite.destY], ax
retn
; ---------------------------------------------------------------------------

@@goalkeeper:       ; CODE XREF: SetPlayerWithNoBallDestination+BF↑j
mov     word ptr D2, 285
mov     word ptr D3, 387 ; keepers x limits
mov     ax, word ptr D6
mov     word ptr D0, ax
sub     word ptr D0, 81 ; D0 = ball x - 81 (relative to left pitch border)
mov     ax, word ptr D3
mov     word ptr D1, ax ; D1 = 387 (right keeper limit)
mov     ax, word ptr D2
sub     word ptr D1, ax
add     word ptr D1, 1 ; D1 = keeper movement width (right - left + 1 = 103)
mov     ax, word ptr D0
mul     word ptr D1
mov     word ptr D0, ax
mov     word ptr D0+2, dx
mov     ax, word ptr D0
mov     dx, word ptr D0+2
mov     bx, 510     ; width of playable part of pitch

; formula: gX = (x * gW) / W

; W  - playable part of pitch width
; gW - width of goalkeeper space
; x  - ball position (relative to playable part)
; gX - position keeper should go to

; Scale ball's x position to position in goalkeeper's space.

div     bx
mov     word ptr D0, ax
mov     word ptr D0+2, dx ; D0 = x position goalkeeper should move to
mov     ax, word ptr D2
add     word ptr D0, ax
mov     ax, word ptr D0
mov     esi, A1
mov     [esi+Sprite.destX], ax ; finally set goalkeepers x destination
mov     word ptr D2, 135
mov     word ptr D3, 161 ; limits for upper goalkeeper
cmp     A6, offset topTeamData
jz      short @@calc_y_goalie_dest
mov     word ptr D2, 737
mov     word ptr D3, 763 ; limits for lower goalkeeper

@@calc_y_goalie_dest: ; CODE XREF: SetPlayerWithNoBallDestination+326↑j
mov     ax, word ptr D7
mov     word ptr D0, ax
sub     word ptr D0, 129 ; playable part of pitch uppper border
mov     ax, word ptr D3
mov     word ptr D1, ax
mov     ax, word ptr D2
sub     word ptr D1, ax
add     word ptr D1, 1 ; D1 = keeper movement area height
mov     ax, word ptr D0
mul     word ptr D1
mov     word ptr D0, ax
mov     word ptr D0+2, dx
mov     ax, word ptr D0
mov     dx, word ptr D0+2
mov     bx, 641     ; height of playable part of pitch
div     bx
mov     word ptr D0, ax
mov     word ptr D0+2, dx ; ball y scaled to goalie movement limits
mov     ax, word ptr D2
add     word ptr D0, ax
mov     ax, word ptr D0
mov     esi, A1
mov     [esi+Sprite.destY], ax ; finally set goalkeepers y destination
retn
SetPlayerWithNoBallDestination endp


