mov     stoppageTimerActive, 0
call    StopAllPlayers
mov     cameraXVelocity, 0
mov     cameraYVelocity, 0

@@check_whether_to_play_referee_whistle:
                    ; CODE XREF: CheckIfBallOutOfPlay+1A↑j
mov     ax, playRefereeWhistle
or      ax, ax
jz      short @@out
call    PlayRefereeWhistleSample

@@out:              ; CODE XREF: CheckIfBallOutOfPlay+8E0↑j
retn
CheckIfBallOutOfPlay endp


; =============== S U B R O U T I N E =======================================


CalculateNextBallPosition proc near ; CODE XREF: UpdateBall+F69↑p
mov     A0, offset ballSprite
mov     esi, A0
mov     eax, [esi+Sprite.x]
mov     D5, eax     ; D5 = ball x
mov     esi, A0
mov     eax, [esi+Sprite.y]
mov     D6, eax     ; D6 = ball y
mov     esi, A0
mov     eax, [esi+Sprite.z]
mov     D7, eax     ; D7 = ball z
mov     esi, A0
mov     ax, [esi+Sprite.speed]
or      ax, ax
jz      @@assign_ball_next_x_and_y
mov     esi, A0
mov     eax, [esi+Sprite.deltaX]
mov     D1, eax     ; D1 = ball delta x
mov     esi, A0
mov     eax, [esi+Sprite.deltaY]
mov     D2, eax     ; D2 = ball delta y
mov     esi, A0
mov     eax, [esi+Sprite.deltaZ]
mov     D3, eax     ; D3 = ball delta z
mov     eax, kBallAirFriction
mov     D4, eax     ; D4 = air friction
mov     eax, D3
or      eax, eax
jg      short @@ball_very_high ; delta z positive, ball rising
mov     esi, A0
mov     ax, word ptr [esi+(Sprite.z+2)] ; get z whole part in ax
mov     word ptr D0, ax
cmp     word ptr D0, 20 ; check the height of ball
jbe     @@ball_low
cmp     word ptr D0, 30
jbe     @@ball_a_little_bit_high
cmp     word ptr D0, 35
jbe     short @@ball_high

; make ball move - use of z coordinate is very specific:
; z coordinate will go to zero, but in a loop, and x and
; y coordinates will be increased by the corresponding
; delta; in each loop iteration, delta z is lowered by a constant

@@ball_very_high:   ; CODE XREF: CalculateNextBallPosition+82↑j
shl     D1, 3       ; delta x *= 8
shl     D2, 3       ; delta y *= 8
shl     D4, 3       ; air friction *= 8
sar     D7, 3       ; z /= 8

@@ball_still_in_the_air: ; CODE XREF: CalculateNextBallPosition+102↓j
mov     eax, D1
add     D5, eax     ; x += delta x
mov     eax, D2
add     D6, eax     ; y += delta y
mov     eax, D4
sub     D3, eax     ; delta z -= air friction (include air friction)
mov     eax, D3
add     D7, eax     ; z += delta z
jns     short @@ball_still_in_the_air
jmp     @@assign_ball_next_x_and_y
; ---------------------------------------------------------------------------

@@ball_high:        ; CODE XREF: CalculateNextBallPosition+B8↑j
shl     D1, 2       ; delta x *= 4
shl     D2, 2       ; delta y *= 4
shl     D4, 2       ; air friction *= 4
sar     D7, 2       ; z /= 4

@@ball_still_in_the_air_2: ; CODE XREF: CalculateNextBallPosition+151↓j
mov     eax, D1
add     D5, eax     ; x += delta x
mov     eax, D2
add     D6, eax     ; y += delta y
mov     eax, D4
sub     D3, eax     ; delta z -= air friction (include air friction)
mov     eax, D3
add     D7, eax     ; z += delta z
jns     short @@ball_still_in_the_air_2
jmp     short @@assign_ball_next_x_and_y
; ---------------------------------------------------------------------------

@@ball_a_little_bit_high: ; CODE XREF: CalculateNextBallPosition+AA↑j
shl     D1, 1       ; delta x *= 2
shl     D2, 1       ; delta y *= 2
shl     D4, 1       ; air friction *= 2
sar     D7, 1       ; z /= 2

@@ball_still_in_the_air_3: ; CODE XREF: CalculateNextBallPosition+199↓j
mov     eax, D1
add     D5, eax     ; x += delta x
mov     eax, D2
add     D6, eax     ; y += delta y
mov     eax, D4
sub     D3, eax     ; delta z -= air friction (include air friction)
mov     eax, D3
add     D7, eax     ; z += delta z
jns     short @@ball_still_in_the_air_3
jmp     short @@assign_ball_next_x_and_y
; ---------------------------------------------------------------------------

@@ball_low:         ; CODE XREF: CalculateNextBallPosition+9C↑j
                    ; CalculateNextBallPosition+1C9↓j
mov     eax, D1
add     D5, eax     ; x += delta x
mov     eax, D2
add     D6, eax     ; y += delta y
mov     eax, D4
sub     D3, eax     ; delta z -= air friction (include air friction)
mov     eax, D3
add     D7, eax     ; z += delta z
jns     short @@ball_low

@@assign_ball_next_x_and_y: ; CODE XREF: CalculateNextBallPosition+41↑j
                    ; CalculateNextBallPosition+104↑j ...
mov     ax, word ptr D5
xchg    ax, word ptr D5+2
mov     word ptr D5, ax ; swap words of ball x, so the whole part is at offset 0 now
mov     ax, word ptr D6
xchg    ax, word ptr D6+2 ; ditto for ball y
mov     word ptr D6, ax
mov     ax, word ptr D5
mov     ballNextX, ax ; ballNextX = x.whole()
mov     ax, word ptr D6
mov     ballNextY, ax ; ballNextY = y.whole()
retn
CalculateNextBallPosition endp


