UpdateReferee proc near ; CODE XREF: GameLoop+4C4↑p
mov     ax, refState
or      ax, ax
jz      @@out
mov     A0, offset refereeSprite
mov     esi, A0
mov     ax, [esi+Sprite.visible]
or      ax, ax
jz      @@out
mov     esi, A0
mov     ax, [esi+Sprite.onScreen]
or      ax, ax
jz      @@check_if_game_in_progress
mov     esi, A0
sub     [esi+Sprite.cycleFramesTimer], 1
jnz     @@update_state
mov     esi, A0
add     [esi+Sprite.frameIndex], 1
mov     ax, [esi+Sprite.frameDelay]
mov     [esi+Sprite.cycleFramesTimer], ax
mov     esi, A0
mov     eax, [esi+Sprite.frameIndicesTable]
mov     A1, eax

@@update_next_frame: ; CODE XREF: UpdateReferee+ED↓j
                    ; UpdateReferee+FB↓j ...
mov     esi, A0
mov     ax, [esi+Sprite.frameIndex]
mov     word ptr D0, ax
shl     word ptr D0, 1
mov     esi, A1
movzx   ebx, word ptr D0
mov     ax, [esi+ebx]
mov     word ptr D0, ax
or      ax, ax
jns     @@set_picture
cmp     word ptr D0, -999
jz      short @@reset_index
cmp     word ptr D0, -101
jz      short @@hold_last_frame
cmp     word ptr D0, -100
jle     short @@loop_back_index
neg     word ptr D0
mov     ax, word ptr D0
mov     esi, A0
mov     [esi+Sprite.frameDelay], ax
mov     ax, word ptr D0
mov     [esi+Sprite.cycleFramesTimer], ax
add     [esi+Sprite.frameIndex], 1
jmp     short @@update_next_frame
; ---------------------------------------------------------------------------

@@reset_index:      ; CODE XREF: UpdateReferee+B1↑j
mov     esi, A0
mov     [esi+Sprite.frameIndex], 0
jmp     @@update_next_frame
; ---------------------------------------------------------------------------

@@loop_back_index:  ; CODE XREF: UpdateReferee+C5↑j
add     word ptr D0, 100
mov     ax, word ptr D0
mov     esi, A0
add     [esi+Sprite.frameIndex], ax
jmp     @@update_next_frame
; ---------------------------------------------------------------------------

@@hold_last_frame:  ; CODE XREF: UpdateReferee+BB↑j
mov     esi, A0
sub     [esi+Sprite.frameIndex], 1
jmp     short @@update_state
; ---------------------------------------------------------------------------

@@set_picture:      ; CODE XREF: UpdateReferee+A2↑j
mov     esi, A0
add     [esi+Sprite.frameSwitchCounter], 1
mov     ax, word ptr D0
mov     esi, A0
mov     [esi+Sprite.imageIndex], ax

@@update_state:     ; CODE XREF: UpdateReferee+4A↑j
                    ; UpdateReferee+128↑j ...
cmp     refState, REF_ABOUT_TO_GIVE_CARD
jz      @@giving_card
cmp     refState, REF_INCOMING
jz      short @@update_deltas_and_direction
cmp     refState, REF_LEAVING
jnz     @@out
mov     esi, A0     ; referee leaving
mov     ax, [esi+Sprite.onScreen]
or      ax, ax
jnz     short @@update_deltas_and_direction
mov     refState, REF_OFF_SCREEN
mov     esi, A0
mov     [esi+Sprite.visible], 0
call    InitDisplaySprites
jmp     @@out
; ---------------------------------------------------------------------------

@@update_deltas_and_direction: ; CODE XREF: UpdateReferee+15B↑j
                    ; UpdateReferee+178↑j
mov     ax, kRefereeSpeed
mov     esi, A0
mov     [esi+Sprite.speed], ax
mov     esi, A0
mov     ax, [esi+Sprite.direction]
mov     word ptr D5, ax
mov     ax, [esi+Sprite.destX]
mov     word ptr D1, ax
mov     ax, [esi+Sprite.destY]
mov     word ptr D2, ax
mov     ax, word ptr [esi+(Sprite.x+2)]
mov     word ptr D3, ax
mov     ax, word ptr [esi+(Sprite.y+2)]
mov     word ptr D4, ax
mov     ax, [esi+Sprite.speed]
mov     word ptr D0, ax
push    D5
push    A0
call    CalculateDeltaXAndY
pop     A0
pop     D5
mov     eax, D1
mov     esi, A0
mov     [esi+Sprite.deltaX], eax
mov     eax, D2
mov     [esi+Sprite.deltaY], eax
add     word ptr D0, 16
and     word ptr D0, 0FFh
shr     word ptr D0, 5
mov     ax, word ptr D0
mov     [esi+Sprite.direction], ax
mov     ax, word ptr D5 ; D5 = referee old direction
cmp     word ptr D0, ax
jz      short @@move_referee
mov     A1, offset refComingAnimTable
call    InitRefereeAnimationTable

@@move_referee:     ; CODE XREF: UpdateReferee+24E↑j
mov     esi, A0
mov     ax, [esi+Sprite.destX]
mov     word ptr D1, ax
mov     esi, A0
mov     eax, [esi+Sprite.deltaX]
mov     D0, eax
or      eax, eax
jz      short @@check_delta_y2
jns     short @@moving_right2
mov     eax, D0
mov     esi, A0
add     [esi+Sprite.x], eax
mov     esi, A0
mov     ax, word ptr [esi+(Sprite.x+2)]
cmp     word ptr D1, ax
jl      short @@check_delta_y2

@@reached_x_destination2: ; CODE XREF: UpdateReferee+2E2↓j
mov     ax, word ptr D1
mov     esi, A0
mov     word ptr [esi+(Sprite.x+2)], ax
mov     esi, A0
mov     [esi+Sprite.deltaX], 0
jmp     short @@check_delta_y2
; ---------------------------------------------------------------------------

@@moving_right2:    ; CODE XREF: UpdateReferee+281↑j
mov     eax, D0
mov     esi, A0
add     [esi+Sprite.x], eax
mov     esi, A0
mov     ax, word ptr [esi+(Sprite.x+2)]
cmp     word ptr D1, ax
jle     short @@reached_x_destination2

@@check_delta_y2:   ; CODE XREF: UpdateReferee+27F↑j
                    ; UpdateReferee+2A2↑j ...
mov     esi, A0
mov     ax, [esi+Sprite.destY]
mov     word ptr D1, ax
mov     esi, A0
mov     eax, [esi+Sprite.deltaY]
mov     D0, eax
or      eax, eax
jz      short @@check_if_ref_arrived
jns     short @@moving_down2
mov     eax, D0
mov     esi, A0
add     [esi+Sprite.y], eax
mov     esi, A0
mov     ax, word ptr [esi+(Sprite.y+2)]
cmp     word ptr D1, ax
jl      @@out

@@reached_y_destination2: ; CODE XREF: UpdateReferee+36B↓j
mov     ax, word ptr D1
mov     esi, A0
mov     word ptr [esi+(Sprite.y+2)], ax
mov     esi, A0
mov     [esi+Sprite.deltaY], 0
jmp     short @@check_if_ref_arrived
; ---------------------------------------------------------------------------

@@moving_down2:     ; CODE XREF: UpdateReferee+306↑j
mov     eax, D0
mov     esi, A0
add     [esi+Sprite.y], eax
mov     esi, A0
mov     ax, word ptr [esi+(Sprite.y+2)]
cmp     word ptr D1, ax
jle     short @@reached_y_destination2

@@check_if_ref_arrived: ; CODE XREF: UpdateReferee+304↑j
                    ; UpdateReferee+34A↑j
mov     esi, A0
mov     eax, [esi+Sprite.deltaX]
or      eax, eax
jnz     @@out
mov     esi, A0
mov     eax, [esi+Sprite.deltaY]
or      eax, eax
jnz     @@out
mov     refState, REF_WAITING_PLAYER
mov     esi, A0
mov     [esi+Sprite.direction], 6 ; facing left
mov     A1, offset refWaitingAnimTable
call    InitRefereeAnimationTable
jmp     short @@out
; ---------------------------------------------------------------------------

@@giving_card:      ; CODE XREF: UpdateReferee+14D↑j
mov     refState, REF_BOOKING
cmp     whichCard, CARD_RED
jz      short @@red_card
cmp     whichCard, CARD_SECOND_YELLOW
jz      short @@red_card_second_yellow
mov     A1, offset refYellowCardAnimTable
call    InitRefereeAnimationTable
call    EnqueueYellowCardSample
jmp     short @@out
; ---------------------------------------------------------------------------

@@red_card:         ; CODE XREF: UpdateReferee+3C6↑j
mov     A1, offset refRedCardAnimTable
call    InitRefereeAnimationTable
call    EnqueueRedCardSample
jmp     short @@out
; ---------------------------------------------------------------------------

@@red_card_second_yellow: ; CODE XREF: UpdateReferee+3D0↑j
mov     A1, offset refSecondYellowAnimTable
call    InitRefereeAnimationTable
call    EnqueueRedCardSample
jmp     short $+2
; ---------------------------------------------------------------------------

@@out:              ; CODE XREF: UpdateReferee+9↑j UpdateReferee+26↑j ...
retn
; ---------------------------------------------------------------------------

@@check_if_game_in_progress: ; CODE XREF: UpdateReferee+39↑j
cmp     gameStatePl, ST_GAME_IN_PROGRESS
jnz     @@update_state
mov     esi, A0
mov     ax, [esi+Sprite.destX]
mov     word ptr D1, ax
mov     esi, A0
mov     eax, [esi+Sprite.deltaX]
mov     D0, eax
or      eax, eax
jz      short @@check_delta_y
jns     short @@moving_right
mov     eax, D0
mov     esi, A0
add     [esi+Sprite.x], eax
mov     esi, A0
mov     ax, word ptr [esi+(Sprite.x+2)]
cmp     word ptr D1, ax
jl      short @@check_delta_y

@@reached_x_destination: ; CODE XREF: UpdateReferee+4A6↓j
mov     ax, word ptr D1
mov     esi, A0
mov     word ptr [esi+(Sprite.x+2)], ax
mov     esi, A0
mov     [esi+Sprite.deltaX], 0
jmp     short @@check_delta_y
; ---------------------------------------------------------------------------

@@moving_right:     ; CODE XREF: UpdateReferee+445↑j
mov     eax, D0
mov     esi, A0
add     [esi+Sprite.x], eax
mov     esi, A0
mov     ax, word ptr [esi+(Sprite.x+2)]
cmp     word ptr D1, ax
jle     short @@reached_x_destination

@@check_delta_y:    ; CODE XREF: UpdateReferee+443↑j
                    ; UpdateReferee+466↑j ...
mov     esi, A0
mov     ax, [esi+Sprite.destY]
mov     word ptr D1, ax
mov     esi, A0
mov     eax, [esi+Sprite.deltaY]
mov     D0, eax
or      eax, eax
jz      short @@out2
jns     short @@moving_down
mov     eax, D0
mov     esi, A0
add     [esi+Sprite.y], eax
mov     esi, A0
mov     ax, word ptr [esi+(Sprite.y+2)]
cmp     word ptr D1, ax
jl      short @@out2

@@reached_y_destination: ; CODE XREF: UpdateReferee+52B↓j
mov     ax, word ptr D1
mov     esi, A0
mov     word ptr [esi+(Sprite.y+2)], ax
mov     esi, A0
mov     [esi+Sprite.deltaY], 0
jmp     short @@out2
; ---------------------------------------------------------------------------

@@moving_down:      ; CODE XREF: UpdateReferee+4CA↑j
mov     eax, D0
mov     esi, A0
add     [esi+Sprite.y], eax
mov     esi, A0
mov     ax, word ptr [esi+(Sprite.y+2)]
cmp     word ptr D1, ax
jle     short @@reached_y_destination

@@out2:             ; CODE XREF: UpdateReferee+4C8↑j
                    ; UpdateReferee+4EB↑j ...
retn
UpdateReferee endp


