SetRefereeToLeavingState proc near
                    ; CODE XREF: UpdateBookedPlayerNumberSprite:@@referree_leaving↑p
mov     A0, offset refereeSprite
call    Rand
shr     word ptr D0, 2
sub     word ptr D0, 32 ; D0 = -32..31
mov     word ptr D2, 129
cmp     foulYCoordinate, 449
ja      short @@set_dest_x
mov     word ptr D2, 770

@@set_dest_x:       ; CODE XREF: SetRefereeToLeavingState+31↑j
mov     esi, A0
mov     ax, word ptr [esi+(Sprite.x+2)]
add     word ptr D0, ax
mov     ax, word ptr D0
mov     esi, A0
mov     [esi+Sprite.destX], ax ; destX = x + -32..31
mov     ax, word ptr D2
mov     esi, A0
mov     [esi+Sprite.destY], ax
mov     A1, offset refComingAnimTable
call    InitRefereeAnimationTable
mov     refState, REF_LEAVING
retn
SetRefereeToLeavingState endp


