; in:
;      A1 -> player (sprite)
;      A6 -> team general data
;
; Static header was activated now we need to aim it somewhere.

SetStaticHeaderDirection proc near
                    ; CODE XREF: UpdatePlayers:@@check_for_static_header_hit↓p
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.currentAllowedDirection]
mov     word ptr D0, ax
or      ax, ax
js      short @@out
nop
nop
nop
nop
mov     esi, A1
cmp     [esi+Sprite.playerDownTimer], 18
ja      short @@out
mov     esi, A1
cmp     [esi+Sprite.animationTable], offset staticHeaderAttemptAnimTable
jnz     short @@out
mov     esi, A1
mov     ax, [esi+Sprite.direction]
sub     word ptr D0, ax
jz      short @@out
