@@turn_right:       ; CODE XREF: SetStaticHeaderDirection+59↑j
mov     esi, A1
add     [esi+Sprite.direction], 1

@@normalize_direction: ; CODE XREF: SetStaticHeaderDirection+66↑j
mov     esi, A1
and     [esi+Sprite.direction], 7

@@out:              ; CODE XREF: SetStaticHeaderDirection+13↑j
                    ; SetStaticHeaderDirection+23↑j ...
retn
SetStaticHeaderDirection endp


; =============== S U B R O U T I N E =======================================

; in:
;      A1 -> player (sprite)
;      A6 -> team general info
;
; Runs when a player makes contact with the ball while doing static header.
; Applies ball speed and destination. Increases player speed, updates delta z
; and plays kick sample.

PlayerHittingStaticHeader proc near ; CODE XREF: UpdatePlayers+3991↓p
mov     esi, A6
mov     [esi+TeamGeneralInfo.passInProgress], 0
mov     esi, A1
cmp     [esi+Sprite.animationTable], offset staticHeaderHitAnimTable
jz      @@set_static_header_anim_table
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.currentAllowedDirection]
mov     word ptr D0, ax
mov     esi, A1
mov     ax, [esi+Sprite.direction]
sub     word ptr D0, ax
jz      @@set_static_header_anim_table
and     word ptr D0, 7
cmp     word ptr D0, 4
jz      @@set_static_header_anim_table
jb      short @@turn_player_right
mov     esi, A6     ; turn player left
mov     ax, [esi+Sprite.speed]
mov     word ptr D0, ax
mov     esi, A1
sub     [esi+Sprite.direction], 1
mov     esi, A1
and     [esi+Sprite.direction], 7
mov     esi, A1
mov     ax, [esi+Sprite.direction]
cmp     word ptr D0, ax
jz      short @@fix_sprite_direction
mov     esi, A1
sub     [esi+Sprite.direction], 1
jmp     short @@fix_sprite_direction
; ---------------------------------------------------------------------------

@@turn_player_right: ; CODE XREF: PlayerHittingStaticHeader+5F↑j
mov     esi, A6
mov     ax, [esi+Sprite.speed]
mov     word ptr D0, ax
mov     esi, A1
add     [esi+Sprite.direction], 1
mov     esi, A1
and     [esi+Sprite.direction], 7
mov     esi, A1
mov     ax, [esi+Sprite.direction]
cmp     word ptr D0, ax
jz      short @@fix_sprite_direction
mov     esi, A1
add     [esi+Sprite.direction], 1

@@fix_sprite_direction: ; CODE XREF: PlayerHittingStaticHeader+98↑j
                    ; PlayerHittingStaticHeader+A5↑j ...
mov     esi, A1     ; only allowed to turn player twice toward controls (max 90 degrees)
and     [esi+Sprite.direction], 7

@@set_static_header_anim_table:
                    ; CODE XREF: PlayerHittingStaticHeader+1C↑j
                    ; PlayerHittingStaticHeader+43↑j ...
mov     A0, offset staticHeaderHitAnimTable
call    SetPlayerAnimationTableAndPictureIndex
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.currentAllowedDirection]
mov     word ptr D1, ax
jns     short @@got_direction
mov     esi, A1
mov     ax, [esi+Sprite.direction]
mov     word ptr D1, ax

@@got_direction:    ; CODE XREF: PlayerHittingStaticHeader+115↑j
mov     A2, offset ballSprite
mov     ax, word ptr D1 ; D1 = direction
mov     word ptr D0, ax
mov     ax, word ptr D0
mov     esi, A6
mov     [esi+TeamGeneralInfo.controlledPlDirection], ax
mov     A0, offset kDefaultDestinations
shl     word ptr D0, 2
mov     esi, A0
movzx   ebx, word ptr D0
mov     ax, [esi+ebx]
mov     word ptr D1, ax
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.x+2)]
add     word ptr D1, ax
mov     ax, word ptr D1
mov     esi, A2
mov     [esi+Sprite.destX], ax
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.y+2)]
mov     word ptr D1, ax
mov     esi, A0
movzx   ebx, word ptr D0
mov     ax, [esi+ebx+2]
add     word ptr D1, ax
mov     ax, word ptr D1
mov     esi, A2
mov     [esi+Sprite.destY], ax
mov     ax, kStaticHeaderBallSpeed
mov     esi, A2
mov     [esi+Sprite.speed], ax
call    GetPlayerPointerFromShirtNumber
mov     A0, offset kPlayerHeaderSpeedIncrease
mov     esi, A4
mov     al, [esi+PlayerInfoHeader.heading]
mov     byte ptr D0, al
mov     al, byte ptr D0
cbw
mov     word ptr D0, ax
shl     word ptr D0, 1
mov     esi, A0
movzx   ebx, word ptr D0
mov     ax, [esi+ebx]
mov     word ptr D0, ax
mov     ax, word ptr D0
mov     esi, A2
add     [esi+Sprite.speed], ax
mov     esi, A2
mov     eax, [esi+Sprite.deltaZ]
mov     D0, eax
neg     D0
sar     D0, 1
mov     eax, D0
mov     esi, A2
mov     [esi+Sprite.deltaZ], eax ; player delta Z = -delta Z / 2
mov     esi, A1
mov     [esi+Sprite.heading], 1
call    PlayKickSample
call    ResetBothTeamSpinTimers
retn
PlayerHittingStaticHeader endp


