; in:
;      D0 - some direction
;      A1 -> player sprite
;
; Players jumps in place trying to hit static header.

AttemptStaticHeader proc near ; CODE XREF: UpdatePlayers+25B0↓p
mov     esi, A1
mov     [esi+Sprite.heading], 0
mov     ax, word ptr D0
mov     esi, A1
mov     [esi+Sprite.direction], ax
mov     A5, offset kDefaultDestinations
shl     word ptr D0, 2
mov     eax, A5
movzx   ebx, word ptr D0
add     eax, ebx
mov     A5, eax
mov     esi, A5
mov     ax, [esi]
add     A5, 2
mov     word ptr D0, ax
mov     esi, A1
mov     ax, word ptr [esi+(Sprite.x+2)]
add     word ptr D0, ax
mov     ax, word ptr D0
mov     esi, A1
mov     [esi+Sprite.destX], ax
mov     esi, A5
mov     ax, [esi]
mov     word ptr D0, ax
mov     esi, A1
mov     ax, word ptr [esi+(Sprite.y+2)]
add     word ptr D0, ax
mov     ax, word ptr D0
mov     esi, A1
mov     [esi+Sprite.destY], ax
mov     ax, kStaticHeaderPlayerSpeed
mov     esi, A1
mov     [esi+Sprite.speed], ax
