call    SetPlayerAnimationTable
mov     esi, A1
mov     [esi+Sprite.playerState], PL_STATIC_HEADING
mov     esi, A1
mov     [esi+Sprite.playerDownTimer], 20
retn
AttemptStaticHeader endp

