align 4

; =============== S U B R O U T I N E =======================================

; in:
;      A6 -> team data
;
; This is practically main SWOS procedure. Everything happens here.
; Binary size: 0x5438/21,560 bytes

UpdatePlayers proc near
                    ; CODE XREF: UpdateAndApplyTeamControls:@@pl1_update_the_game↑p
                    ; UpdateAndApplyTeamControls:@@pl2_update_the_game↑p
mov     eax, lastPlayerPlayed
mov     prevLastPlayer, eax
mov     eax, lastTeamPlayed
mov     prevLastTeamPlayed, eax
mov     eax, lastKeeperPlayed
or      eax, eax
jz      short @@update_goalkeeper_saved_timer
cmp     lastPlayerPlayed, offset goalie1Sprite
jz      short @@update_goalkeeper_saved_timer
cmp     lastPlayerPlayed, offset goalie2Sprite
jz      short @@update_goalkeeper_saved_timer
mov     lastKeeperPlayed, 0 ; some sanity check, if last played keeper pointer doesn't point to any of two
                    ; goalkeepers in the game, set it to null (maybe goalkeeper was substituted?)

@@update_goalkeeper_saved_timer: ; CODE XREF: UpdatePlayers+1B↑j
                    ; UpdatePlayers+27↑j ...
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.goalkeeperSavedCommentTimer]
or      ax, ax
jz      short @@update_pass_kick_timer
js      short @@decay_goalkeeper_saved_timer
mov     esi, A6     ; goalkeeper saved timer is positive, decrease it
sub     [esi+TeamGeneralInfo.goalkeeperSavedCommentTimer], 1
jmp     short @@update_pass_kick_timer
; ---------------------------------------------------------------------------

@@decay_goalkeeper_saved_timer: ; CODE XREF: UpdatePlayers+4E↑j
mov     esi, A6     ; goalkeeper saved timer is negative, increase it
add     [esi+TeamGeneralInfo.goalkeeperSavedCommentTimer], 1

@@update_pass_kick_timer: ; CODE XREF: UpdatePlayers+4C↑j
                    ; UpdatePlayers+5B↑j
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.passKickTimer]
or      ax, ax
jz      short @@update_won_the_ball_timer
mov     esi, A6     ; pass kick timer not zero, decrease it
sub     [esi+TeamGeneralInfo.passKickTimer], 1
jnz     short @@update_won_the_ball_timer
mov     esi, A6
mov     [esi+TeamGeneralInfo.passingKickingPlayer], 0

@@update_won_the_ball_timer: ; CODE XREF: UpdatePlayers+75↑j
                    ; UpdatePlayers+82↑j
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.wonTheBallTimer]
or      ax, ax
jz      short @@update_player_switch_timer
mov     esi, A6
sub     [esi+TeamGeneralInfo.wonTheBallTimer], 1

@@update_player_switch_timer: ; CODE XREF: UpdatePlayers+A1↑j
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.playerSwitchTimer]
or      ax, ax
jz      short @@apply_after_touch_and_set_ball_location_flags
mov     esi, A6
sub     [esi+TeamGeneralInfo.playerSwitchTimer], 1

; === inital timers updated

@@apply_after_touch_and_set_ball_location_flags:
                    ; CODE XREF: UpdatePlayers+BE↑j
call    ApplyBallAfterTouch ; handle kicks, passes, after touch
mov     A2, offset ballSprite ; A2 -> ball sprite, from now on
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.x+2)]
mov     word ptr D1, ax
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.y+2)]
mov     word ptr D2, ax ; D1 = ball x, D2 = ball y
mov     ballInUpperPenaltyArea, 0
mov     ballInLowerPenaltyArea, 0
mov     ballInGoalkeeperArea, 0
cmp     word ptr D1, 193 ; left penalty area limit
jl      @@not_in_penalty_area
cmp     word ptr D1, 478 ; right penalty area limit
jg      short @@not_in_penalty_area
nop
nop
nop
nop
cmp     word ptr D2, 129 ; top goal line
jl      short @@not_in_penalty_area
nop
nop
nop
nop
cmp     word ptr D2, 769 ; bottom goal line
jg      short @@not_in_penalty_area
cmp     word ptr D2, 216 ; top penalty line
jle     short @@upper_penalty_area
cmp     word ptr D2, 682 ; bottom penalty line
jl      short @@not_in_penalty_area
mov     ballInLowerPenaltyArea, 1
jmp     short @@check_goalkeeper_area
; ---------------------------------------------------------------------------

@@upper_penalty_area: ; CODE XREF: UpdatePlayers+156↑j
mov     ballInUpperPenaltyArea, 1

@@check_goalkeeper_area: ; CODE XREF: UpdatePlayers+16C↑j
cmp     word ptr D1, 273 ; goalkeeper area left
jl      short @@not_in_penalty_area
cmp     word ptr D1, 398 ; goalkeeper area right
jg      short @@not_in_penalty_area
cmp     word ptr D2, 158 ; top goalkeepeer area bottom
jle     short @@goalkeeper_area
cmp     word ptr D2, 740
jl      short @@not_in_penalty_area ; bottom goalkeeper area top

@@goalkeeper_area:  ; CODE XREF: UpdatePlayers+196↑j
mov     ballInGoalkeeperArea, 1

@@not_in_penalty_area: ; CODE XREF: UpdatePlayers+11E↑j
                    ; UpdatePlayers+12D↑j ...
cmp     gameStatePl, ST_GAME_IN_PROGRESS
jnz     short @@update_player_index
mov     ax, goalOut
or      ax, ax
jz      short @@update_player_index
mov     eax, dword ptr ballInUpperPenaltyArea
or      eax, eax
jnz     short @@update_player_index
