mov     esi, A6
cmp     [esi+TeamGeneralInfo.updatePlayerIndex], 11
jnz     short @@init_players_loop
mov     esi, A6
mov     [esi+TeamGeneralInfo.updatePlayerIndex], 0

@@init_players_loop: ; CODE XREF: UpdatePlayers+1E9↑j
mov     word ptr D4, 10 ; counter, 11 players
mov     esi, A6
