; === players loop

@@players_loop:     ; CODE XREF: UpdatePlayers+53CF↓j
push    small [word ptr D4] ; save how many players are left (0 based)
mov     esi, A3
mov     eax, [esi]
add     A3, 4
mov     A1, eax     ; A1 -> current player sprite
mov     esi, A1
mov     ax, [esi+Sprite.direction]
mov     esi, A1
mov     [esi+Sprite.playerDirection], ax
mov     esi, A1
mov     eax, [esi+Sprite.deltaX]
mov     D0, eax
mov     esi, A1
mov     eax, [esi+Sprite.deltaY]
