mov     esi, A1
cmp     [esi+Sprite.injuryLevel], -1
jz      @@injury_forever

@@jmp_not_controlled_player: ; CODE XREF: UpdatePlayers+2CE↑j
jmp     @@not_controlled_player
; ---------------------------------------------------------------------------

@@update_player_ball_distance: ; CODE XREF: UpdatePlayers+299↑j
                    ; UpdatePlayers+2A6↑j ...
mov     esi, A6     ; no pass in prograss
mov     al, [esi+TeamGeneralInfo.plVeryCloseToBall]
mov     [esi+TeamGeneralInfo.prevPlVeryCloseToBall], al
mov     esi, A6
mov     [esi+TeamGeneralInfo.plVeryCloseToBall], 0
mov     [esi+TeamGeneralInfo.plCloseToBall], 0
mov     [esi+TeamGeneralInfo.plNotFarFromBall], 0
mov     esi, A1
mov     eax, [esi+Sprite.ballDistance]
mov     D0, eax
cmp     D0, 32
jbe     short @@very_close_to_ball
cmp     D0, 72
jbe     short @@close_to_ball
cmp     D0, 2450
jbe     short @@somewhat_close_to_ball
jmp     short @@update_ball_height
; ---------------------------------------------------------------------------

@@very_close_to_ball: ; CODE XREF: UpdatePlayers+319↑j
mov     esi, A6
mov     [esi+TeamGeneralInfo.plVeryCloseToBall], 1
jmp     short @@update_ball_height
; ---------------------------------------------------------------------------

@@close_to_ball:    ; CODE XREF: UpdatePlayers+322↑j
mov     esi, A6
mov     [esi+TeamGeneralInfo.plCloseToBall], 1
jmp     short @@update_ball_height
; ---------------------------------------------------------------------------

@@somewhat_close_to_ball: ; CODE XREF: UpdatePlayers+32E↑j
mov     esi, A6
mov     [esi+TeamGeneralInfo.plNotFarFromBall], 1

@@update_ball_height: ; CODE XREF: UpdatePlayers+330↑j
                    ; UpdatePlayers+33C↑j ...
mov     esi, A6
mov     [esi+TeamGeneralInfo.ballLessEqual4], 0
mov     [esi+TeamGeneralInfo.ball4To8], 0
mov     [esi+TeamGeneralInfo.ball8To12], 0
mov     [esi+TeamGeneralInfo.ball12To17], 0
mov     [esi+TeamGeneralInfo.ballAbove17], 0
mov     esi, A2     ; A2 -> ball sprite
mov     ax, word ptr [esi+(Sprite.z+2)]
mov     word ptr D0, ax
cmp     word ptr D0, 17
ja      short @@ball_too_high
cmp     word ptr D0, 12
ja      short @@ball_high
cmp     word ptr D0, 8
ja      short @@ball_medium_height
cmp     word ptr D0, 4
ja      short @@ball_low
mov     esi, A6
mov     [esi+TeamGeneralInfo.ballLessEqual4], 1
jmp     short @@check_player_state
; ---------------------------------------------------------------------------

@@ball_low:         ; CODE XREF: UpdatePlayers+3A4↑j
mov     esi, A6
mov     [esi+TeamGeneralInfo.ball4To8], 1
jmp     short @@check_player_state
; ---------------------------------------------------------------------------

@@ball_medium_height: ; CODE XREF: UpdatePlayers+39A↑j
mov     esi, A6
mov     [esi+TeamGeneralInfo.ball8To12], 1
jmp     short @@check_player_state
; ---------------------------------------------------------------------------

@@ball_high:        ; CODE XREF: UpdatePlayers+390↑j
mov     esi, A6
mov     [esi+TeamGeneralInfo.ball12To17], 1
jmp     short @@check_player_state
; ---------------------------------------------------------------------------

@@ball_too_high:    ; CODE XREF: UpdatePlayers+386↑j
mov     esi, A6
mov     [esi+TeamGeneralInfo.ballAbove17], 1

@@check_player_state: ; CODE XREF: UpdatePlayers+3B0↑j
                    ; UpdatePlayers+3BC↑j ...
mov     esi, A1     ; switch on player state
cmp     [esi+Sprite.playerState], PL_TACKLING
jz      @@player_tackling
mov     esi, A1
cmp     [esi+Sprite.playerState], PL_JUMP_HEADING
jz      @@player_jump_heading
mov     esi, A1
cmp     [esi+Sprite.playerState], PL_STATIC_HEADING
jz      @@player_doing_static_header
mov     esi, A1
cmp     [esi+Sprite.playerState], PL_THROW_IN
jz      @@player_taking_throw_in
mov     esi, A1
cmp     [esi+Sprite.playerState], PL_GOALIE_DIVING_HIGH
jz      @@goalie_diving
mov     esi, A1
cmp     [esi+Sprite.playerState], PL_GOALIE_DIVING_LOW
jz      @@goalie_diving
mov     esi, A1
cmp     [esi+Sprite.playerState], PL_GOALIE_CATCHING_BALL
jz      @@goalie_catching_the_ball
mov     esi, A1
cmp     [esi+Sprite.playerState], PL_DOWN
jz      @@player_down_st_10
mov     esi, A1
cmp     [esi+Sprite.playerState], PL_BOOKED
jz      @@player_booked
mov     esi, A1
cmp     [esi+Sprite.playerState], PL_SAD
jz      @@player_sad_or_happy
mov     esi, A1
cmp     [esi+Sprite.playerState], PL_HAPPY
jz      @@player_sad_or_happy
mov     esi, A1
cmp     [esi+Sprite.playerState], PL_GOALIE_CLAIMED
jz      @@goalie_claimed
; === player in normal state

mov     esi, A1
cmp     [esi+Sprite.playerOrdinal], 1
jz      short @@player_goalkeeper
mov     esi, A6
mov     eax, [esi+TeamGeneralInfo.controlledPlayer]
cmp     A1, eax
jz      @@its_controlled_player
mov     esi, A6
mov     eax, [esi+TeamGeneralInfo.passToPlayerPtr]
cmp     A1, eax
jz      @@player_expecting_pass
int     3           ; Trap to Debugger

@@endless_loop:     ; CODE XREF: UpdatePlayers:@@endless_loop↓j
jmp     short @@endless_loop
; ---------------------------------------------------------------------------

@@player_goalkeeper: ; CODE XREF: UpdatePlayers+4AB↑j
mov     goalTypeScored, GT_REGULAR ; don't allow goalkeeper to be own goal scorer... why?
mov     ax, playingPenalties
or      ax, ax
jz      short @@update_shot_chance_table_for_goalie
cmp     penaltiesTimer, 55
ja      @@update_player_speed_and_deltas ; penalty has been shot, the keeper is still down

@@update_shot_chance_table_for_goalie: ; CODE XREF: UpdatePlayers+4EC↑j
call    UpdatePlayerShotChanceTable
mov     ax, lastPlayerTurnFlags+1 ; why +1? makes it 0 always
or      ax, ax
jnz     @@this_player_last_played
mov     ballNextGroundX, -1
mov     esi, A6
mov     ax, [esi+TeamGeneralInfo.goalkeeperPlaying]
or      ax, ax
jz      short @@update_ball_out_or_keepers
mov     esi, A6     ; goalkeeper has the ball, and plays like an ordinary player
mov     byte ptr [esi+TeamGeneralInfo.goaliePlayingOrOut], 1
mov     byte ptr [esi+TeamGeneralInfo.ballOutOfPlayOrKeeper], 0
mov     esi, A6
mov     eax, [esi+TeamGeneralInfo.controlledPlayer]
cmp     A1, eax
jz      @@its_controlled_player
mov     esi, A6     ; goalkeeper playing, but not controlled player, kludge it
mov     [esi+TeamGeneralInfo.goalkeeperPlaying], 0

@@update_ball_out_or_keepers: ; CODE XREF: UpdatePlayers+529↑j
mov     esi, A6     ; A6 -> team data
mov     byte ptr [esi+TeamGeneralInfo.ballOutOfPlayOrKeeper], 0
mov     byte ptr [esi+TeamGeneralInfo.goaliePlayingOrOut], 0
cmp     gameStatePl, ST_GAME_IN_PROGRESS
jz      short @@update_goalkeeper_speed
mov     byte ptr [esi+TeamGeneralInfo.goaliePlayingOrOut], -1
mov     byte ptr [esi+TeamGeneralInfo.ballOutOfPlayOrKeeper], -1
mov     ax, kGoalkeeperSpeedWhenGameStopped
mov     esi, A1
mov     [esi+Sprite.speed], ax

@@update_goalkeeper_speed: ; CODE XREF: UpdatePlayers+573↑j
mov     ax, kGoalkeeperGameSpeed
mov     esi, A1
mov     [esi+Sprite.speed], ax
mov     esi, A1
cmp     word ptr [esi+(Sprite.y+2)], 449
ja      short @@goalkeeper_in_lower_half
cmp     A6, offset bottomTeamData ; goalkeeper in upper half
jz      @@this_player_last_played
jmp     short @@goalkeeper_in_upper_half
; ---------------------------------------------------------------------------

@@goalkeeper_in_lower_half: ; CODE XREF: UpdatePlayers+5A9↑j
cmp     A6, offset topTeamData
jz      @@this_player_last_played

@@goalkeeper_in_upper_half: ; CODE XREF: UpdatePlayers+5BB↑j
mov     esi, A1
cmp     [esi+Sprite.playerState], PL_GOALIE_CATCHING_BALL
jnz     @@goalie_not_catching_the_ball ; this jump is always taken
cmp     gameStatePl, ST_GAME_IN_PROGRESS ; unreachable code (state was checked above and it wasn't goalie catching ball)
mov     esi, A1
sub     [esi+Sprite.playerDownTimer], 1
jz      short @@player_got_up ; goalkeeper in the air, set ball coordinates as player destination (with y +/-1)
mov     esi, A2     ; A2 -> ball sprite
mov     ax, word ptr [esi+(Sprite.x+2)]
mov     esi, A1     ; A1 -> player sprite
mov     [esi+Sprite.destX], ax
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.y+2)]
mov     esi, A1
mov     [esi+Sprite.destY], ax
cmp     A6, offset bottomTeamData
jz      short @@increase_y_dest
mov     esi, A1
sub     [esi+Sprite.destY], 1 ; decrease y for upper team (go a little behind the ball)
jmp     cseg_7FCD0
; ---------------------------------------------------------------------------

@@increase_y_dest:  ; CODE XREF: UpdatePlayers+623↑j
mov     esi, A1
add     [esi+Sprite.destY], 1
jmp     cseg_7FCD0
; ---------------------------------------------------------------------------

@@player_got_up:    ; CODE XREF: UpdatePlayers+5EF↑j
mov     esi, A1     ; player just got up
mov     [esi+Sprite.playerState], PL_NORMAL
mov     A0, offset playerNormalStandingAnimTable
call    SetPlayerAnimationTable

@@goalie_not_catching_the_ball: ; CODE XREF: UpdatePlayers+5D7↑j
mov     esi, A6
mov     eax, [esi+TeamGeneralInfo.controlledPlayer]
cmp     A1, eax
jz      @@its_controlled_player
mov     esi, A6
mov     eax, [esi+TeamGeneralInfo.passToPlayerPtr]
cmp     A1, eax
jz      @@player_expecting_pass
cmp     gameStatePl, ST_GAME_IN_PROGRESS ; goalkeeper that is not controlled or passed to
jnz     @@not_controlled_player
mov     esi, A2     ; A2 -> ball sprite
mov     ax, word ptr [esi+(Sprite.x+2)]
mov     word ptr D1, ax ; D1 = ball x
mov     esi, A2
mov     ax, word ptr [esi+(Sprite.y+2)]
mov     word ptr D2, ax ; D2 = ball y
cmp     A6, offset bottomTeamData
jz      short cseg_7F0DF
mov     ax, ballInUpperPenaltyArea ; upper team
or      ax, ax
jz      @@check_pass_to_player
jmp     short @@ball_in_penalty_area
; ---------------------------------------------------------------------------

cseg_7F0DF:         ; CODE XREF: UpdatePlayers+6C0↑j
mov     ax, ballInLowerPenaltyArea ; lower team
