;      D1 - extension
;      A0 -> selected filename
;      zero flag - clear = error
;                  set = OK
; globals:
;   read:
;     g_skipNonCompetitionFiles - if -1, .TAC and .HIL files
;                                 are not searched for
;   write:
;     selectedFilename
;     extension

GetFilenameAndExtension proc near
                    ; CODE XREF: LoadOldCompetitionMenu+3C↑p
                    ; LoadTactics+32↑p ...
mov     eax, D0
mov     g_extension, eax
mov     eax, A1
mov     menuTitle, eax
mov     A1, offset inputSaveFilename
call    StringCopy
mov     A0, 0
mov     A1, offset numberOfFiles
call    FindFiles
jnz     @@error
mov     totalNumberOfFiles, 0
mov     numMatchedFiles, 0
mov     ax, word ptr numberOfFiles
mov     word ptr D0, ax
or      ax, ax
jz      @@done_copying
sub     word ptr D0, 1 ; return num. files found + 1
mov     A0, offset foundFilenamesBuffer
mov     A1, offset foundFilesPtrTable
mov     A3, offset extensionsBuffer

@@files_loop:       ; CODE XREF: GetFilenameAndExtension+19E↓j
mov     eax, A0
mov     A2, eax     ; A2 -> current file in foundFilenamesBuffer

@@search_dot_loop:  ; CODE XREF: GetFilenameAndExtension+A8↓j
mov     esi, A2
inc     A2
cmp     byte ptr [esi], '.'
jnz     short @@search_dot_loop
mov     esi, A2
mov     al, [esi-1] ; letter before dot
mov     byte ptr D1, al
shl     D1, 8
mov     esi, A2
mov     al, [esi]
inc     A2
mov     byte ptr D1, al
shl     D1, 8
mov     esi, A2
mov     al, [esi]
inc     A2
mov     byte ptr D1, al
shl     D1, 8
mov     esi, A2
mov     al, [esi]
inc     A2
mov     byte ptr D1, al ; D1 = .extension
cmp     D1, '.DIY'
jz      short @@extension_ok
cmp     D1, '.PRE'
jz      short @@extension_ok
cmp     D1, '.SEA'
jz      short @@extension_ok
cmp     D1, '.CAR'
jz      short @@extension_ok
cmp     g_skipNonCompetitionFiles, -1
jz      short @@next_file
cmp     D1, '.TAC'
jz      short @@extension_ok
cmp     D1, '.HIL'
jnz     short @@next_file

@@extension_ok:     ; CODE XREF: GetFilenameAndExtension+110↑j
                    ; GetFilenameAndExtension+11C↑j ...
add     totalNumberOfFiles, 1
add     numMatchedFiles, 1
mov     eax, A0     ; A0 -> foundFilenamesBuffer
mov     esi, A1     ; A1 -> foundFilesPtrTable
mov     [esi], eax
add     A1, 4       ; A1 - first 4 bytes = number of files
mov     eax, D1     ; D1 = .extension
mov     esi, A3     ; A3 -> extensionsBuffer
mov     [esi], eax
add     A3, 4       ; A3 - first 4 bytes = extension

@@next_file:        ; CODE XREF: GetFilenameAndExtension+13E↑j
                    ; GetFilenameAndExtension+156↑j
add     A0, 32      ; advance pointer to next file
dec     word ptr D0
jns     @@files_loop

@@done_copying:     ; CODE XREF: GetFilenameAndExtension+63↑j
mov     savingFile, 0
mov     A6, offset selectFilesMenu
push    A5
call    ShowMenu
pop     A5
mov     eax, g_extension
mov     D1, eax
mov     A0, offset g_selectedFilename
mov     esi, A0
mov     al, [esi]
or      al, al
jz      short @@return_error
mov     word ptr D0, 0
xor     ax, ax
retn
; ---------------------------------------------------------------------------

@@error:            ; CODE XREF: GetFilenameAndExtension+3C↑j
call    nullsub_9

@@return_error:     ; CODE XREF: GetFilenameAndExtension+1E6↑j
mov     word ptr D0, 1
mov     ax, 1
or      ax, ax
retn
GetFilenameAndExtension endp


; =============== S U B R O U T I N E =======================================

; in:
;      A1 -> var to write number of files found (dword),
;            followed by a buffer for filenames (512 x 32 bytes)
; globals:
;      g_extension - dword that holds filter extension
; out:
;      zero flag - always set
;
; Fills buffer in A1:
;   word - number of files
;   file names (0 terminated), 32 bytes alloted for each

FindFiles proc near ; CODE XREF: GetFilenameAndExtension+37↑p
mov     edi, offset dta.filename
mov     ecx, 14
xor     al, al
rep stosb
mov     eax, g_extension
or      eax, eax
jnz     short FindFilesExtensionPresent
mov     word ptr g_extension+2, '.*'
mov     word ptr g_extension, 0

FindFilesExtensionPresent: ; CODE XREF: FindFiles+15↑j
                    ; SelectFileToSaveDialog+37↓p
mov     al, byte ptr g_extension+3
mov     ext1, al
mov     al, byte ptr g_extension+2
mov     ext2, al
mov     al, byte ptr g_extension+1
mov     ext3, al
mov     al, byte ptr g_extension
mov     ext4, al
mov     numFiles, 0
call    SetDTA
call    FindFirstFile
cmp     al, -1
jz      @@out

@@next_file:        ; CODE XREF: FindFiles+107↓j
mov     esi, offset dta.filename
mov     ecx, 14

@@find_dot_loop:    ; CODE XREF: FindFiles+7C↓j
cmp     byte ptr [esi], '.'
jz      short @@dot_found
inc     esi
loop    @@find_dot_loop
jmp     @@not_found
; ---------------------------------------------------------------------------

@@dot_found:        ; CODE XREF: FindFiles+79↑j
cmp     word ptr g_extension+2, '.*'
jz      short @@test_if_extension_acceptable
mov     al, byte ptr g_extension+2
cmp     [esi+1], al
jnz     short @@not_found
nop
nop
nop
nop
mov     al, byte ptr g_extension+1
cmp     [esi+2], al
jnz     short @@not_found
mov     al, byte ptr g_extension
cmp     [esi+3], al
jnz     short @@not_found

@@test_if_extension_acceptable: ; CODE XREF: FindFiles+8C↑j
cmp     byte ptr [esi+1], 'D'
jz      short @@letter_exceptable
cmp     byte ptr [esi+1], 'P'
jz      short @@letter_exceptable
cmp     byte ptr [esi+1], 'S'
jz      short @@letter_exceptable
cmp     byte ptr [esi+1], 'T'
jz      short @@letter_exceptable
cmp     byte ptr [esi+1], 'H'
jz      short @@letter_exceptable
cmp     byte ptr [esi+1], 'C'
jz      short @@letter_exceptable
jmp     short @@not_found
; ---------------------------------------------------------------------------

@@letter_exceptable: ; CODE XREF: FindFiles+B4↑j FindFiles+BA↑j ...
mov     esi, offset dta.filename
mov     edi, A1
add     edi, 4
mov     eax, 32
movzx   ebx, numFiles ; get current file offset in buffer
mul     ebx
add     edi, eax
mov     cx, 14
rep movsb           ; copy to file names buffer
add     numFiles, 1 ; next file

@@not_found:        ; CODE XREF: FindFiles+7E↑j FindFiles+96↑j ...
call    FindNextFile
jnb     @@next_file

@@out:              ; CODE XREF: FindFiles+66↑j
mov     edi, A1
mov     ax, numFiles
mov     [edi], ax   ; put number of files in the buffer
xor     ax, ax
retn
FindFiles endp


; =============== S U B R O U T I N E =======================================


FindFirstFile proc near ; CODE XREF: FindFiles+5F↑p
xor     cx, cx      ; no attriutes
mov     edx, offset asciizFileSpec
mov     ah, 4Eh
int     21h         ; DOS - 2+ - FIND FIRST ASCIZ (FINDFIRST)
                    ; CX = search attributes
                    ; DS:DX -> ASCIZ filespec
                    ; (drive, path, and wildcards allowed)
retn
FindFirstFile endp


; =============== S U B R O U T I N E =======================================


FindNextFile proc near ; CODE XREF: FindFiles:@@not_found↑p
mov     ah, 4Fh
int     21h         ; DOS - 2+ - FIND NEXT ASCIZ (FINDNEXT)
                    ; [DTA] = data block from
                    ; last AH = 4Eh/4Fh call
retn
FindNextFile endp


; =============== S U B R O U T I N E =======================================


SetDTA proc near    ; CODE XREF: FindFiles+5A↑p
mov     edx, offset dta
mov     ah, 1Ah
int     21h         ; DOS - SET DISK TRANSFER AREA ADDRESS
                    ; DS:DX -> disk transfer buffer
retn
SetDTA endp


