SelectFilesInit proc near ; DATA XREF: dseg:selectFilesMenu↓o
mov     ax, savingFile
or      ax, ax
jz      short @@check_if_any_files
mov     al, inputSaveFilename
or      al, al
jz      short @@save_filename_empty
mov     word ptr D0, 49 ; save
call    SetCurrentEntry
jmp     short @@default_entry_selected
; ---------------------------------------------------------------------------

@@save_filename_empty: ; CODE XREF: SelectFilesInit+12↑j
mov     word ptr D0, 48 ; save filename
call    SetCurrentEntry
jmp     short @@default_entry_selected
; ---------------------------------------------------------------------------

@@check_if_any_files: ; CODE XREF: SelectFilesInit+9↑j
mov     ax, numMatchedFiles
or      ax, ax
jnz     short @@default_entry_selected
mov     word ptr D0, 50 ; abort
call    SetCurrentEntry

@@default_entry_selected: ; CODE XREF: SelectFilesInit+22↑j
                    ; SelectFilesInit+32↑j ...
mov     ax, numMatchedFiles
mov     word ptr D2, ax
sub     word ptr D2, 2
js      @@sorting_done

@@outer_sort_loop:  ; CODE XREF: SelectFilesInit+187↓j
mov     A2, offset foundFilesPtrTable
mov     A3, offset extensionsBuffer
mov     word ptr D3, 0 ; D3 = sorted flag (had swaps in this iteration)
mov     ax, word ptr D2
mov     word ptr D1, ax ; sort filename list by extension first, then names

@@inner_sort_loop:  ; CODE XREF: SelectFilesInit+178↓j
mov     esi, A2
mov     eax, [esi]
add     A2, 4
mov     A0, eax     ; A0 -> filename
mov     esi, A3
mov     eax, [esi]
add     A3, 4
mov     D0, eax     ; D0 = extension
mov     esi, A3
mov     eax, [esi]
cmp     D0, eax
jb      @@next_item ; sort list
ja      short @@swap
mov     esi, A2
mov     eax, [esi]
mov     A1, eax

@@compare_filename_characters: ; CODE XREF: SelectFilesInit+10E↓j
mov     esi, A0
mov     al, [esi]
inc     A0
mov     byte ptr D0, al
or      al, al
jz      short @@next_item
nop
nop
nop
nop
mov     esi, A1
mov     al, [esi]
inc     A1
cmp     byte ptr D0, al
jb      short @@next_item
ja      short @@swap
jmp     short @@compare_filename_characters
; ---------------------------------------------------------------------------

@@swap:             ; CODE XREF: SelectFilesInit+CC↑j
                    ; SelectFilesInit+10C↑j
mov     esi, A2
mov     eax, [esi-4]
mov     D0, eax
mov     esi, A2
mov     eax, [esi]
mov     esi, A2
mov     [esi-4], eax
mov     eax, D0
mov     esi, A2
mov     [esi], eax
mov     esi, A3
mov     eax, [esi-4]
mov     D0, eax
mov     esi, A3
mov     eax, [esi]
mov     esi, A3
mov     [esi-4], eax
mov     eax, D0
mov     esi, A3
mov     [esi], eax
mov     word ptr D3, 1

@@next_item:        ; CODE XREF: SelectFilesInit+C6↑j
                    ; SelectFilesInit+F0↑j ...
dec     word ptr D1
jns     @@inner_sort_loop
mov     ax, word ptr D3
or      ax, ax
jnz     @@outer_sort_loop

@@sorting_done:     ; CODE XREF: SelectFilesInit+61↑j
jmp     short $+2

SelectFilesOnReturn: ; DATA XREF: dseg:0017F7DC↓o
push    D0
mov     D0, 0       ; title
call    CalcMenuEntryAddress
pop     D0
mov     eax, menuTitle
mov     esi, A0
mov     [esi+MenuEntry.fg.string], eax
mov     ax, savingFile
or      ax, ax
jz      @@not_saving2
push    D0
mov     D0, 48      ; save filename
call    CalcMenuEntryAddress
pop     D0
mov     esi, A0
mov     [esi+MenuEntry.isInvisible], 0
mov     esi, A0
mov     eax, [esi+MenuEntry.fg.string]
mov     A1, eax
mov     esi, A1
mov     byte ptr [esi], 0
mov     A0, offset inputSaveFilename
mov     byte ptr D0, '.'
call    StringCopyUntilChar ; fill save filename entry
push    D0
mov     D0, 47      ; filename label
call    CalcMenuEntryAddress
pop     D0
mov     esi, A0
mov     [esi+MenuEntry.isInvisible], 0
mov     al, inputSaveFilename
or      al, al
jz      short @@no_filename
push    D0
mov     D0, 49      ; save label
call    CalcMenuEntryAddress
pop     D0
mov     esi, A0
mov     [esi+MenuEntry.isInvisible], 0
jmp     short @@check_range
; ---------------------------------------------------------------------------

@@no_filename:      ; CODE XREF: SelectFilesInit+249↑j
jmp     short @@check_range
; ---------------------------------------------------------------------------

@@not_saving2:      ; CODE XREF: SelectFilesInit+1C1↑j
mov     ax, numMatchedFiles
or      ax, ax
jnz     short $+2

@@check_range:      ; CODE XREF: SelectFilesInit+272↑j
                    ; SelectFilesInit:@@no_filename↑j
cmp     numMatchedFiles, 8
ja      short @@more_than_8_files
mov     selFilesColumn1NumItems, 0
mov     ax, numMatchedFiles
mov     selFilesColumn2NumItems, ax
mov     selFilesColumn3NumItems, 0
jmp     @@reposition_filename_entries
; ---------------------------------------------------------------------------

@@more_than_8_files: ; CODE XREF: SelectFilesInit+289↑j
mov     ax, numMatchedFiles
mov     word ptr D0, ax
mov     ax, word ptr D0
cwde
mov     D0, eax
mov     ax, word ptr D0
mov     dx, word ptr D0+2
mov     bx, 3
div     bx
mov     word ptr D0, ax
mov     word ptr D0+2, dx
mov     ax, word ptr D0
mov     selFilesColumn1NumItems, ax
mov     ax, word ptr D0
mov     selFilesColumn2NumItems, ax
mov     ax, word ptr D0
mov     selFilesColumn3NumItems, ax
mov     ax, word ptr D0
xchg    ax, word ptr D0+2
mov     word ptr D0, ax ; D0 = num. files % 3
cmp     word ptr D0, 1
jnz     short @@remainder_not_1
add     selFilesColumn2NumItems, 1
jmp     short @@reposition_filename_entries
; ---------------------------------------------------------------------------

@@remainder_not_1:  ; CODE XREF: SelectFilesInit+326↑j
cmp     word ptr D0, 2
jnz     short @@reposition_filename_entries
add     selFilesColumn1NumItems, 1
add     selFilesColumn2NumItems, 1

@@reposition_filename_entries: ; CODE XREF: SelectFilesInit+2A9↑j
                    ; SelectFilesInit+330↑j ...
call    RepositionSelectFileEntries
jmp     short $+2
mov     A1, offset foundFilesPtrTable
mov     eax, A0
xchg    eax, A2
mov     A0, eax
push    D0
mov     D0, 1       ; first filename
call    CalcMenuEntryAddress
pop     D0
mov     eax, A0
xchg    eax, A2     ; A2 -> current filename entry
mov     A0, eax
mov     word ptr D6, 0 ; D6 - number of shown entries

@@initialize_filenames_loop: ; CODE XREF: SelectFilesInit+53B↓j
mov     esi, A2
mov     [esi+MenuEntry.isInvisible], 1
mov     ax, word ptr numberOfFiles
cmp     word ptr D6, ax
jnb     @@next_filename_entry
mov     word ptr D2, 0

@@set_filename_entries_visibility_loop:
                    ; CODE XREF: SelectFilesInit+4B5↓j
mov     ax, word ptr D2
mov     word ptr D1, ax
mov     esi, A2
mov     ax, [esi+MenuEntry.ordinal]
mov     word ptr D0, ax
sub     word ptr D0, 1 ; D0 = file entry ordinal, zero-based (since they start at 1)
mov     ax, word ptr D0
cwde
mov     D0, eax
mov     ax, word ptr D0
mov     dx, word ptr D0+2
mov     bx, 15      ; divide with max. number of items per column
div     bx
mov     word ptr D0, ax
mov     word ptr D0+2, dx
or      ax, ax
jnz     short @@not_first_column
mov     ax, selFilesColumn1NumItems
add     word ptr D1, ax
jmp     short @@num_items_in_column_determined
; ---------------------------------------------------------------------------

@@not_first_column: ; CODE XREF: SelectFilesInit+41D↑j
cmp     word ptr D0, 1
jnz     short @@column3
mov     ax, selFilesColumn2NumItems
add     word ptr D1, ax
jmp     short @@num_items_in_column_determined
; ---------------------------------------------------------------------------

@@column3:          ; CODE XREF: SelectFilesInit+436↑j
mov     ax, word ptr D2
mov     word ptr D1, ax
mov     ax, selFilesColumn3NumItems
add     word ptr D1, ax

@@num_items_in_column_determined: ; CODE XREF: SelectFilesInit+42C↑j
                    ; SelectFilesInit+445↑j
mov     ax, word ptr D0
xchg    ax, word ptr D0+2
mov     word ptr D0, ax ; D0 = would be index inside the column
mov     ax, word ptr D2
cmp     word ptr D0, ax ; compare actual column position to max. number of items in the column
jb      short @@next_filename_hide_entry
mov     ax, word ptr D1
cmp     word ptr D0, ax
jb      short @@show_entry

@@next_filename_hide_entry: ; CODE XREF: SelectFilesInit+480↑j
add     A2, size MenuEntry
mov     esi, A2
cmp     [esi+MenuEntry.ordinal], 46
jz      @@out
mov     esi, A2
mov     [esi+MenuEntry.isInvisible], 1
jmp     @@set_filename_entries_visibility_loop
; ---------------------------------------------------------------------------

@@show_entry:       ; CODE XREF: SelectFilesInit+48F↑j
mov     esi, A2
mov     [esi+MenuEntry.isInvisible], 0
mov     esi, A1
mov     eax, [esi]
add     A1, 4
mov     A0, eax
mov     esi, A2
mov     eax, [esi+MenuEntry.fg.string]
mov     A3, eax

@@remove_extension_loop: ; CODE XREF: SelectFilesInit+50E↓j
                    ; SelectFilesInit+51D↓j
mov     esi, A0
mov     al, [esi]
inc     A0
mov     esi, A3
mov     [esi], al
inc     A3
mov     esi, A0
cmp     byte ptr [esi-1], '.'
jnz     short @@remove_extension_loop
mov     esi, A3
mov     byte ptr [esi-1], 0
xor     ax, ax
jnz     short @@remove_extension_loop ; never taken

@@next_filename_entry: ; CODE XREF: SelectFilesInit+3BA↑j
add     A2, size MenuEntry
mov     esi, A2
cmp     [esi+MenuEntry.ordinal], 46
jz      short @@out
add     word ptr D6, 1
jmp     @@initialize_filenames_loop
; ---------------------------------------------------------------------------

@@out:              ; CODE XREF: SelectFilesInit+4A3↑j
                    ; SelectFilesInit+531↑j
retn
SelectFilesInit endp


; =============== S U B R O U T I N E =======================================

; This proc draws description of items (career, highlight, etc.)
; by using normally invisible entry 46 (45 is max files). It accomplishes
; this by putting description strings and moving only one entry giving
; effect that there are more entries ;)
;
; in:
;     A5 -> current entry that's beeing drawn

SelFilesDrawItemDescription proc near ; DATA XREF: dseg:0017F822↓o
mov     esi, A5
mov     ax, [esi+MenuEntry.ordinal]
mov     word ptr D0, ax
sub     word ptr D0, 1
cmp     word ptr D0, 15
jb      short @@column1
cmp     word ptr D0, 30
jb      short @@column2
sub     word ptr D0, 15
mov     ax, selFilesColumn2NumItems
add     word ptr D0, ax

@@column2:          ; CODE XREF: SelFilesDrawItemDescription+2A↑j
sub     word ptr D0, 15
mov     ax, selFilesColumn1NumItems
add     word ptr D0, ax

@@column1:          ; CODE XREF: SelFilesDrawItemDescription+20↑j
shl     word ptr D0, 2 ; D0 = index in previously found files
mov     A0, offset extensionsBuffer
mov     esi, A0
movzx   ebx, word ptr D0
mov     eax, [esi+ebx]
mov     D1, eax     ; D1 -> extension
mov     eax, A5
mov     A1, eax     ; A1 -> entry that's being drawn
mov     eax, A0
xchg    eax, A5
mov     A0, eax
push    D0
mov     D0, 46
call    CalcMenuEntryAddress
pop     D0
mov     eax, A0
xchg    eax, A5     ; A5 -> entry 46 (invisible entry for descriptions)
mov     A0, eax
mov     A0, offset aDiy ; "DIY***"
cmp     D1, '.DIY'
jz      short @@found_ext
mov     A0, offset aPreset ; "PRESET"
cmp     D1, '.PRE'
jz      short @@found_ext
mov     A0, offset aSeason_0 ; "SEASON"
cmp     D1, '.SEA'
jz      short @@found_ext
mov     A0, offset aCareer_0 ; "CAREER"
cmp     D1, '.CAR'
jz      short @@found_ext
mov     A0, offset aTact ; "TACT**"
cmp     D1, '.TAC'
jz      short @@found_ext
mov     A0, offset aHigh ; "HIGH**"

@@found_ext:        ; CODE XREF: SelFilesDrawItemDescription+D6↑j
                    ; SelFilesDrawItemDescription+EC↑j ...
mov     eax, A0     ; A0 = file description
mov     esi, A5
mov     [esi+MenuEntry.fg.string], eax
mov     esi, A1
mov     ax, [esi+MenuEntry.x]
mov     esi, A5
mov     [esi+MenuEntry.x], ax
mov     esi, A5
add     [esi+MenuEntry.x], 57 ; description entry x = main entry x + 57
mov     esi, A1
mov     ax, [esi+MenuEntry.y]
mov     esi, A5
mov     [esi+MenuEntry.y], ax ; description entry y = main entry y
mov     esi, A5
mov     [esi+MenuEntry.isInvisible], 0 ; make it visible for a redraw
call    DrawMenuItem
mov     esi, A5
mov     [esi+MenuEntry.isInvisible], 1 ; make it invisible again
retn
SelFilesDrawItemDescription endp


