; ---------------------------------------------------------------------------

@@end_of_string:    ; CODE XREF: SelectFilesInputSaveFilenameOnSelect+76↑j
push    D0          ; this is only reached if the string is empty
mov     D0, 48      ; input save filename
call    CalcMenuEntryAddress
pop     D0
mov     esi, A0
mov     eax, [esi+MenuEntry.fg.string]
mov     A1, eax
mov     A0, offset inputSaveFilename
mov     byte ptr D0, '.'
call    StringCopyUntilChar
mov     eax, A0
xchg    eax, A5
mov     A0, eax
push    D0
mov     D0, 48
call    CalcMenuEntryAddress
pop     D0
mov     eax, A0
xchg    eax, A5
mov     A0, eax
call    CallDrawMenuItem

@@out:              ; CODE XREF: SelectFilesInputSaveFilenameOnSelect+5C↑j
retn
SelectFilesInputSaveFilenameOnSelect endp


