SelFilesOnSelectCommon proc near ; DATA XREF: dseg:0017F81C↓o
mov     esi, A5
mov     ax, [esi+MenuEntry.ordinal]
mov     word ptr D0, ax
sub     word ptr D0, 1
cmp     word ptr D0, 15
jb      short @@column1
cmp     word ptr D0, 30
jb      short @@column2
sub     word ptr D0, 15
mov     ax, selFilesColumn2NumItems
add     word ptr D0, ax

@@column2:          ; CODE XREF: SelFilesOnSelectCommon+2A↑j
sub     word ptr D0, 15
