; =============== S U B R O U T I N E =======================================

; in:
;      D6 - delta x
;      D7 - delta y
;      D1 - camera x
;      D2 - camera y (these 2 not used)
; out:
;      D1 - new camera x
;      D2 - new camera y
;
; sets globals:
;      scrollTileX, scrollTileOffsetX, scrollTileY, scrollTileOffsetY
;
; Loop scrolling pixel by pixel until we arrive at the desired screen location.

ScrollPitch proc near ; CODE XREF: ScrollToCurrent+2F↑p
mov     ax, word ptr D6
or      ax, ax
