mov     ax, word ptr D6
or      ax, ax
jns     short @@test_delta_y
neg     word ptr D6 ; D6 = abs(deltaX)
mov     A0, offset ScrollLeft ; delta x < 0
mov     A1, offset FillPatternsLeftColumn

@@test_delta_y:     ; CODE XREF: ScrollPitch+1F↑j ScrollPitch+3E↑j
mov     ax, word ptr D7
or      ax, ax
jnz     short @@delta_y_nonzero
