mov     A3, offset NoVerticalScroll
jmp     short @@check_if_need_drawing_loop
; ---------------------------------------------------------------------------

@@delta_y_nonzero:  ; CODE XREF: ScrollPitch+64↑j
mov     A2, offset ScrollDown ; delta y > 0
mov     A3, offset FillPatternsBottomRow
mov     ax, word ptr D7
or      ax, ax
jns     short @@check_if_need_drawing_loop
neg     word ptr D7 ; D7 = abs(deltaY)
mov     A2, offset ScrollUp ; delta y < 0
mov     A3, offset FillPatternsTopRow

@@check_if_need_drawing_loop: ; CODE XREF: ScrollPitch+7A↑j
                    ; ScrollPitch+99↑j ...
mov     ax, word ptr D7
mov     word ptr D0, ax
mov     ax, word ptr D6
or      word ptr D0, ax
jz      @@out       ; return if delta x == delta y == 0 (scrolling done)
mov     ax, word ptr D6
or      ax, ax
jz      short @@check_delta_y
call    A0          ; delta x != 0, first call
sub     word ptr D6, 1
mov     ax, scrollTileOffsetX
mov     word ptr D5, ax
call    A1          ; second call, actual drawing

@@check_delta_y:    ; CODE XREF: ScrollPitch+DE↑j
mov     ax, word ptr D7
or      ax, ax
jz      short @@no_delta_y
