UpdateVisibleScreenPtr proc near ; CODE XREF: ScrollToCurrent+34↑p
cmp     EGA_graphics, -1
jz      EGA_GetVisibleScreenPtr
movzx   eax, scrollTileY
shl     eax, 4
movzx   ebx, scrollTileOffsetY
add     eax, ebx
shl     eax, 7
mov     ebx, eax
shl     eax, 1
add     eax, ebx
mov     vscreenDeltaY, eax ; vscreenDeltaY = 384 * (scrollTileOffsetY + 16 * scrollTileY)
mov     ax, scrollTileX
shl     ax, 4
add     ax, scrollTileOffsetX
mov     vscreenDeltaX, ax ; vscreenDeltaX = scrollTileOffsetX + 16 * scrollTileX
