movzx   eax, vscreenDeltaX
add     esi, eax
mov     eax, vscreenDeltaY
add     esi, eax
add     esi, 6160   ; 384 * 16 + 16, 1 empty row on top, and 1 empty column on the left
                    ; (actually they get filled while scrolling)
mov     vsPtr, esi
retn
UpdateVisibleScreenPtr endp


