xor     edx, edx
mov     ax, word ptr D2
shl     ax, 2
mov     dx, ax
shl     ax, 1
add     dx, ax
shl     ax, 2
add     dx, ax
shl     dx, 2
add     ebx, edx    ; ebx += 176 * D2 + 4 * D1
mov     esi, [ebx]  ; get ptr
mov     ax, word ptr D4
shl     ax, 7
mov     bx, ax
shl     ax, 1
