InitBackground proc near ; CODE XREF: GameLoop+313↑p
                    ; ViewHighLightsMain+6D↑p ...
cmp     EGA_graphics, -1 ; virtual screen dimensions seem to be 384 x 288
jz      EGAInitBackground
mov     ebx, offset g_pitchDatBuffer
mov     edi, linAdr384k
mov     ecx, 18

@@outer_loop:       ; CODE XREF: InitBackground+4A↓j
push    ecx
push    ebx
push    edi
mov     ecx, 24     ; fill 24 x 16 = 384, whole virtual screen row

@@inner_loop:       ; CODE XREF: InitBackground+39↓j
mov     esi, [ebx]  ; ebx -> array of pattern pointers, esi -> current pattern
push    ebx
push    ecx
push    edi
