pop     edi
pop     ecx
pop     ebx
add     ebx, 4      ; next pattern pointer
add     edi, 16     ; advance to next uncovered position in a row
loop    @@inner_loop
pop     edi
pop     ebx
pop     ecx
add     edi, 24 * 16 * 16 ; (= 384 * 16) advance screen pointer 16 lines for next pattern
add     ebx, 44 * 4 ; advance 44 patterns - length of line in g_pitchDatBuffer
