EGAFlip proc near   ; CODE XREF: Flip+8↑j SetEGAPalette+50↓p
call    ReadGamePort
mov     dseg_183286, 1
mov     ax, scrollTileOffsetX
and     ax, 8
jnz     short cseg_96CBA
mov     dseg_183286, 0

cseg_96CBA:         ; CODE XREF: EGAFlip+18↑j
movzx   ecx, PIT_countdown
mov     al, 110110b ; counter 0, mode 3, write MSB than LSB
call    ProgramPIT
mov     dx, 3DAh

@@retrace_going:    ; CODE XREF: EGAFlip+38↓j
in      al, dx      ; Video status bits:
                    ; 0: retrace.  1=display is in vert or horiz retrace.
                    ; 1: 1=light pen is triggered; 0=armed
                    ; 2: 1=light pen switch is open; 0=closed
                    ; 3: 1=vertical sync pulse is occurring.
and     al, 8
jnz     short @@retrace_going
cli
mov     bx, pageOffset
add     bx, dseg_183286
add     bx, word ptr vscreenDeltaY
add     bx, vscreenDeltaX
add     bx, 770
mov     dx, 3D4h
mov     al, 0Ch     ; start address high
mov     ah, bh
out     dx, ax
inc     al          ; start address low
mov     ah, bl
out     dx, ax      ; horizontal total
mov     dx, 3DAh

@@drawing_now:      ; CODE XREF: EGAFlip+73↓j
in      al, dx      ; video status bits
and     al, 8
jz      short @@drawing_now
in      al, dx      ; video status bits
mov     dx, 3C0h
mov     al, 33h
out     dx, al      ; EGA: horizontal pixel panning:
                    ; Number of dots to shift data left.
                    ; Bits 0-3 valid (0-0fH)
mov     ax, scrollTileOffsetX
and     ax, 7
out     dx, al      ; EGA: palette register: select colors for attribute AL:
                    ; 0: RED
                    ; 1: GREEN
                    ; 2: BLUE
                    ; 3: blue
                    ; 4: green
                    ; 5: red
sti
xor     pageOffset, 20480
cmp     dseg_166760, offset numSpritesSaved
jz      short cseg_96D41
mov     dseg_166760, offset numSpritesSaved
jmp     short @@exit
; ---------------------------------------------------------------------------

cseg_96D41:         ; CODE XREF: EGAFlip+9C↑j
mov     dseg_166760, offset dseg_167766

@@exit:             ; CODE XREF: EGAFlip+A8↑j
retn
EGAFlip endp


