SetEGAPalette proc near ; CODE XREF: GameLoop+202↑p
                    ; ViewHighLightsMain+18↑p
cmp     EGA_graphics, -1
jnz     short @@out
mov     ax, 13
int     10h         ; set mode 13h
mov     ah, 24      ; number of words in horizontal line
mov     al, 13h     ; offset register
mov     dx, 3D4h
out     dx, ax      ; Video: CRT cntrlr addr
xor     cx, cx

@@loop:             ; CODE XREF: SetEGAPalette+45↓j
mov     ebx, 463h   ; base address of crt controller
mov     dx, [ebx]
add     dl, 6       ; status register
push    dx
cli
in      al, dx      ; do a dummy read from status register
                    ; to reset the flip-flop to load index
mov     dl, 0C0h    ; VGA attribute and sequencer register
mov     al, cl      ; select color register
out     dx, al
mov     al, cl
out     dx, al      ; write color
pop     dx
in      al, dx      ; reset flip-flop
mov     dl, 0C0h
mov     al, 20h     ; 20h ?!
out     dx, al
sti
add     cx, 1
cmp     cx, 16
jnz     short @@loop
mov     pageOffset, 0
call    EGAFlip

@@out:              ; CODE XREF: SetEGAPalette+8↑j
retn
SetEGAPalette endp


